window.__D("tolt-4",[[65,"והנה ע\"י בחי' יין המשמח נמשך בחי' לבוש לבחי' הגוף של הנפש שהוא בחי' לבושי מדות הנפש אהבה ויראה כו' אבל ע\"י בחי' דם ענבים נמשך לבוש לבחי' הראש והפנים של הנפש והוא בחי' ראיה ושמיעה."],[65,"וכמ\"ש הביטו אליו ונהרו וגו'. וכי אפשר להסתכל בשכינה כו' אלא היינו לאסתכלא ביקרא דמלכא כו' והענין כמאמר רז\"ל במקום שבע\"ת עומדים כו' כי צדיקים גמורים ע\"י שמחה של מצוה והתענגם על ה' ממשיכים ענג העליון מלמעלה למטה אבל הבעל תשובה ע\"י התגברותו על הרע שבנפשו במסירת נפש היא בבחי' הסתלקות מלמטה למעלה כדרך הגבורות ורשפי אש כו'. ולכן נעשה לבוש לנשמתו ג\"כ למעלה על בחי' ראש הנ\"ל:"],[65,"<b>והנה<\/b> זהו כל עבודתנו בקיום המצות בזמן הזה להמשיך לנפש שתתעלה בעילוי אחר עילוי לאור באור א\"ס ב\"ה ותהיה הנפש צרורה כו'. אבל תכלית השלימות של ימות המשיח בקיום המצות ומעשה הקרבנות שיהיו הקרבנות כבשים ופרים וכו' ג\"כ נכללים ומתעלים בעילוי אחר עילוי באור א\"ס ב\"ה. אך בזמן הגלות אי אפשר לנפש האדם להעלותם ולקשרם במקורם מאחר שהיא מקושרת בעצמה למטה. אבל לימות המשיח שיקויים ונגלה כבוד ה' וראו כל בשר וגו'. שנשמות ישראל יהיו במעלה אז יהיה זמן קיום המעש' והעלאת ניצוצות שנפלו אפילו הבהמות."],[65,"וכמו שהיה בתחלת בריאת העולם שקודם שנבר' אדם הראשון נא' ואדם אין לעבד את האדמה וגו'. ואח\"כ נעשה אדם ויניחהו בג\"ע לעבדה ולשמרה. אלא שאח\"כ ויגרש את האדם וגו' כלומר שלא הי' בבחי' אדם והוצרך לילך ולתקן נפשו."],[65,"ושלימות בחי' אדם הוא בזמן המשיח שנאמר עליו הנה ישכיל עבדי ירום ונשא וגבה מאד מא\"ד הוא אותיות אד\"ם. וכן ראשי תיבות אד\"ם אד\"ם דו\"ד משי\"ח שבזמן ימות המשיח נשלם בחינת אדם ואזי הוא זמן היום לעשותם זמן קיום המצות בשלימות שיהיה הקרבת קרבנות כמצות רצונך. משא\"כ בזמן הגלות אין עשיית המצו' כרצונך ממש אלא לעילוי הנפש שיתקן בחי' אדם שלא יהיה ואדם אין לעבד. אבל עיקר העבודה לעבדה ולשמרה הוא בימות המשיח דוקא. והתפלה שהיא בחי' נשיאת הנפש הוא כנגד הקרבנות אבל אינה בבחי' קרבנות ממש כי שם בחינת עליות כל העולמות בכלל ואפילו נפש הבהמה היורדת למטה לארץ."],[65,"והנה על בחינת גפן ויין הנ\"ל נאמר אסרי לגפן עירה פי' שבימות המשיח שיושלם בחי' אדם ⟦מז,א⟧אז יהיו כלל ישראל מתעלים במעלה העליונה שיהיה בבחי' גפן ויין המשמח בשמחה של מצוה וגם יהי' אוסרי אוסר יו\"ד שבחי' יו\"ד היא בחי' חכ' עילאה הוא אוסר ומקשר לבחי' גפן (וענין החכמה הוא בחי' בטול שצ\"ל בהשמח' עמ\"ש ע\"פ ולא נחם אלקי' דרך ארץ פלשתים וע\"פ ביום השמע\"צ). ועי\"ז יהי' בבחי' עירה. כי הנה עירה סובל ב' פירושים לשון עיר פרא אדם ובחי' עיר אלהים. וביאור הדבר כי עיר פרא אדם יולד כתי'. פי' יולד היינו כשהמדו' אצלו כתולדתו וטבעו שלא נהפכו אצלו לעמוד כנגד טבעו כי זהו עבודת האדם לעמוד נגד טבעו הקשה מפני אהבת ה' ויראתו. משא\"כ כשהטבע מסייע אין זו עבודה תמה ונקרא עיר פרא אדם אבל כשהוא מקושר בבחי' גפן בחי' יין היוצא מן הגפן ע\"י דריכה ומן הרגליות וכו' כנ\"ל אזי נעשה בחי' עירה עיר ה' שהוא בחי' עיר אלהינו כמו שאמרו רז\"ל אימתי נקרא גדול כשהוא בעיר אלהינו וגו'."],[65,"ולשרקה בני אתונו. הנה שורקה היא זמורה רכה וילדה שענביה מועטים עדיין ומעט יין היוצא ממנה נק' שורקה נקודת שור\"ק כי הנה גפן הוא בחינת סגו\"ל וגם כל נקודת גЧפЧן הוא סגו\"ל וכדכתי' גפן ממצרים תסיע וגו' כסו הרים צלה פי' צלה בחי' צל כמ\"ש ה' צלך דהיינו ישת חשך סתרו והוא העולה למעלה ומכסה על בחי' הרים שהם האבות."],[65,"והנה האבות הם שלשה בחינת סגו\"ל. וזהו בחי' גפן. אבל שורקה הוא בחי' נקודת השורק והשור\"ק יש בו ג\"כ ג' נקודות שבסגו\"ל אלא שהם זה למטה מזה. כך הנה שכשהאדם הוא בבחי' התקרבות והתלהבות בכח ג' נקודות ממטה למעלה ומלמעלה למטה והממוצע וכו' וכמ\"ש במ\"א אזי נקרא בחי' סגו\"ל. אבל כשהוא בבחינת ריחוק מקום אלא שהוא בבחי' הודאה כלומר שיודע שהוא רחוק מה' ונעשה כפוף ומודה ואין ערב לבו לגשת מפני ביטולו נקרא בחינת שור\"ק ושלש נקודות זו למטה מזו. כלומר שמשפיל עצמו מטה מטה להיות רחוק בעיניו להגיע לזה באומרו מי אנכי וכו' וע\"י זה נעשה מבחי' אתונו בחי' בני בחי' בן וכמ\"ש בנים אתם וגו' להיות כמו ברא כרעא דאבוה."],[65,"והנה התהפכות בחינות אלו נעשו ע\"י כבס ביין וגו' כבס לשון עבר שתכלית השלימות של ימות המשיח ושלימות בחינת אדם להיות בחי' עירה ובחי' בן הוא ע\"י שכבר כבס ביין הגלות שע\"י עבודתנו בזמן הגלות לעורר את האהבה ושמחה של מצוה אתהפכא חשוכא לנהורא והוא תכלית של ימות המשיח כנ\"ל:"],[66,"<b>חכלילי עינים מיין ולבן שנים מחלב.<\/b> הנה גבי יין כתיב תירושי המשמח אלקים כו'. ולהבין מהו בחי' יין המשמח אלקים ואיך יהיה כחו גדול כ\"כ לשמח אלקים. הנה אמרו נכנס יין יצא סוד."],[66,"והענין כי בתורה יש ב' בחי' יין וחלב וכדכתיב לכו שברו ואכלו כו' בלוא כסף ובלוא מחיר יין וחלב. וביאור הדבר כי הנה יש ב' אהבות אה\"ע ואה\"ר. אהבת עולם היא האהבה הגלויה."],[66,"ואה\"ר היא אהבה המסותרת. ולהבין למה נק' האהבה המסותרת בשם אה\"ר. אך הנה אה\"ע היא האהבה שנלקחה מעולמות דהיינו מחמת התבוננות איך שהוא ית' מחדש בטובו כו'. ומהווה מאין ליש בכל יום מבחי' מל' ית' כי מלכותך מכ\"ע כתיב שכל עולמים עליונים ותחתונים הם חיים וקיימים מבחי' מלכותו ית' ממכ\"ע וסוכ\"ע ואתה מחיה את כולם."],[66,"ואינו כדמיון הנשמה שמחיה את הגוף. שהחיות מתפשט ומתלבש ⟦מז,ב⟧בגוף ממש להחיותו. כי הוא ית' קדוש ומובדל כו'. רק התפשטות בחי' שם בלבד. דהיינו מחמת כי מלך שמו נק' עליהם."],[66,"וכמאמר ישתבח שמך לעד פי' לעד עד אין קץ כו'. וע\"ז אנו אומרים איש\"ר מברך לעלם ולעלמי עלמיא יתברך. פי' שאנו מתפללים ומבקשים שיהיה שם זה בבחי' ברכה והמשכה מההעלם אל הגילוי. דהיינו שלא יהי' בבחי' העלם והסתר פנים אצלינו בידיעת אנשים מלומדה בלבד שאין זה אלא בבחי' הודאה. אבל בחי' ברכה היא בחי' גילוי ממש במוחו ולבו באמת לאמתו."],[66,"ושיהי' גילוי זה נמשך לעלם ולעלמי עלמיא אפי' בעולמות התחתונים כמו בעוה\"ז הגשמי וכענין שנאמר ברוך ה' אלקי ישראל מן העולם ועד העולם. ועד\"ז תקנו כל פסוד\"ז מב\"ש עד ק\"ש להאריך ולהרחיב הדבור בשבחו של מקום איך שמלכותו הוא מכ\"ע."],[66,"ואיך שהוא קדוש ומובדל כו' עד שיהיה נקבע בקרב איש ולב עמוק. ועי\"ז יגיע לקיום הק\"ש שמע ישראל. שמע לשון הבנה להתבונן כי ה' אחד פי' אחד ז' רקיעים וארץ וד' רוחות העולם בטלים אל האל\"ף הוא אלופו של עולם."],[66,"וכמו שיש בגשמיות ז' רקיעים כו'. כך ברוחניות יש כמה מדרגות זו למעלה מזו וכולם בטלים אליו ית' רק שברוך שם כו'. שמבחי' דלי\"ת רבתי דאחד נמשך בחי' ברכה והמשכה להיות בחי' שם כבוד מלכותו כו'. ועי\"ז יגיע למדרגת ואהבת. פי' ואהבת הוא מלשון רצון. דהיינו שיהי' רצונך שהוי' יהיה אלקיך בכל לבבך בשני יצריך יצ\"ט ויצה\"ר לאהפכא חשוכא כו' שיעקור רצונו מהבלי עולם להיות לו שינוי רצון ולהפך רצונו לה' אחד וכמ\"ש מי לי בשמים ועמך לא חפצתי בארץ:"],[66,"<b>והנה<\/b> כ\"ז הוא בחי' אה\"ע שאומרים אהבת עולם אהבתנו. פי' אהבתנו שאהבה זו היא מתלבשת בתוך נפשנו. שהנפש יכולה להיות כלי להגביל ולהלביש את האהבה זו בתוכה ממש להיות תוכה רצוף אהבה זו. אבל אה\"ר היא בשרש הנפש במקור חוצבה כי חלק הוי' ממש עמו."],[66,"ואני הוי\"ה לא שניתי כתיב שהוא ית' למעלה מגדר עלמין ואין ערוך אליו ית' כלל אפי' כמשל טפה מים אוקיינוס. שעם היות שהוא חלק קטן מאלף אלפי אלפים ורבי רבבות. עכ\"ז שייך איזה ערך ויחוס במהותו הדומה לו שגם מהות הטפה היא מים כמו הים הגדול ממש. משא\"כ אליו ית' אין ההשתלשלות ערוך כלל ולכך האהבה שנלקחה מבחי' זו אינה מתלבשת ממש תוך הנפש ואין הנפש יכולה להגבילה אלא היא בבחי' מסותרת והיא באה לידי גילוי בבחי' בכל מאדך כו'. (וע' בתניא ס\"פ מ\"ג ועי' ג\"כ פ' י\"ט):"],[66,"<b>והנה<\/b> ההפרש שבין אה\"ע לאה\"ר הוא כי אה\"ע הבאה מחמת התבוננות ועומק מחשבתו יש לה הפסק שאם לבבו פונה לדברים אחרים וטרוד במחשבתו בעסקי עולם אזי חולפת ועוברת ממנו כו' משא\"כ האה\"ר שבשרש נפשו ממקור חוצבה אין לה הפסק שגם אם לבבו פונה לדברים אחרים הרי אין בזה לעומת זה להיות לעומת האהבה הזאת להטרידה ולהפסיקה."],[66,"ולזאת תשאר אהבה זו בבחי' רשימו להיות זכרונה תקועה בלב בל תמוט עולם ועד. אך כיצד תהיה אה\"ר זו בבחי' גילוי שיעלה ויגיע למדרגת בכל מאדך ע\"ז אמרו נכנס יין יצא סוד היא התורה שנק' בשם יין."],[66,"וכמארז\"ל ערבים עלי ד\"ס יותר מיינה של תורה כי על האהבה נאמר וירא אלקים את האור כי טוב ואמרו רז\"ל כי טוב לגנוז בתורה. וכשנכנס יינה ש\"ת יצא סוד הוא אור האהבה הגנוז ⟦מז,ג⟧מההעלם אל הגילוי להיות אצלו גילוי האה\"ר המושרשת בשרש נפשו במקור חוצבה בבחי' בכל מאדך וע\"ז נא' פותח את ידיך. יודי\"ך הן הם בחי' הצמצומים רבים ועצומים מאא\"ס ב\"ה להיות השתלשלות המדרגות מעילה לעלול כו'."],[66,"ומקור התהוות העולמות מאין ליש מרצה\"ע ב\"ה וע\"י התורה שהיא חכמתו ורצונו ית' פותח את היודי\"ן והצמצומים להיות גילוי רצה\"ע ב\"ה. ומשביע לכל חי דהיינו בכל חיות ואור המתפשט בעולמות מריש כל דרגין כו'. להיות בהם בחי' רצון שיהי' שורה ומתגלה בהם בחי' רצה\"ע ב\"ה ונמשך לנפש האדם ג\"כ שיהי' מתגלה בו רצה\"ע שבנפשו דהיינו האה\"ר המושרשת בשרש נפשו למעלה מכדי שתוכל הנפש שאת מאחר שהרצ\"ע בא אצלו לידי גילוי למטה בלבושי הנפש דבור ומעשה ע\"י דבור בת\"ת ומעשה המצות ולכן אמרו רז\"ל ששואלים את האדם קבעת עתים לתורה. שעי\"ז יעורר את האהבה מלמעלה בשרש נפשו שאינה מתלבשת בשום כלי המעלים ומסתיר שאין כמוה ולא דוגמתה בזלעו\"ז הנ\"ל ואין לה הפסק שאפי' בעסקו בשאר ענינים תהיה אהבה זו תקועה בלבו. ומזה יבא לידי ודברת בם כו' (וע' באגה\"ק ד\"ה איתא רפ\"ד דמגלה ודאשתמש בתגא כו' במי ששונה הלכות כו' יעו\"ש):"],[66,"<b>ובזה<\/b> יובן הכתוב חכלילי עינים מיין. פי' עינים הוא מ\"ש עיני תמיד אל ה'. הנה עין ה' אל יראיו. והוא בחי' לאסתכלא ביקרא דמלכא דהיינו שיאיר בלבו אור האהבה לה' בבחי' ראיה היא בחי' אהבה בתענוגים שהיא מדרגה העולה על כולנה למעלה מאה\"ר ואה\"ע (וצ\"ע בתניא פמ\"ג משמע דאה\"ר היא אהבה בתענוגים. וצ\"ל שיש ב' בחינות אה\"ר הא' האהבה הנז' בתניא פי\"ט כשבאה לידי גילוי כשאינה בבחינת גילוי התענוג. וגדולה ממנה היא אה\"ר בתענוגים. ועיין במ\"א ע\"פ אחותי רעיתי יונתי כו'. שם נתבאר אחותי היא מצד אהבה טבעית ויונתי היא אהבה בתענוגים) וכענין שכתוב עיניך יונים כמו זוג יונים שמסתכלים תמיד זע\"ז ומתענגים כו'. כך יהיה קשר האהבה בדביקות נפלא ועצום עד שיהיו עיניו ולבו כל הימים רק לאסתכלא ביקרא דמלכא. וכמ\"ש בזהר ע\"פ הסבי עיניך כו' דמוקדין ליה בשלהובין דרחימותא. שתהא האהבה מתלהבת ומתלהטת בלב איש להתענג על ה' מרוב כל עד שאין כח בנפשו להגביל את האהבה בלב רק בבחינת ראיה מבחוץ (ועיין במ\"א ע\"פ עיניך יונים וע\"פ הראיני את מראיך):"],[66,"<b>וזהו<\/b> ענין חכלילי עינים. פירוש אדמומית העינים שאודם העינים הוא מחמת תוקף רשפי אש דמוקדין ליה בשלהוביתא כו'. והוא בחינת מעלת ומדרגת השבת אז תתענג כו' וקראת לשבת ענג. אך מי שטרח בע\"ש כו'. ולכן צריך כל ימות החול ליגע את נפשו. לעורר את האה\"ר ואה\"ע. וע\"י זה יגיע לבחינת האהבה בתענוגים המתגלית בשבת."],[66,"והנה כ\"ז בא מבחינת ומדרגת יין. יינה ש\"ת. וזהו חכלילי כל חיך הטועם אומר לי לי. לפי שיתגלה בחי' חיך הטועם את היין דהיינו בחי' חכמה וטעמי מצות שהם בחי' תענוג העליון. וע\"י כן נתעלה בעילוי אחר עילוי לי לי עד רום המעלות (פי' חיך הטועם זהו בחי' אהבה בתענוגים המתגלה בשבת שהוא בחי' שם ע\"ב דחכמה ואזי אומר לי לי ב\"פ דהיינו שנכללו בו ב' אהבות הנ\"ל אה\"ר ואה\"ע שהם מ\"ה וב\"ן דמ\"ה מברר ב\"ן וע\"י יחוד מ\"ה וב\"ן מתגלה בשבת בחי' הגבוה משניהם והוא בחי' שם ע\"ב אהבה בתענוגים):"],[66,"⟦מז,ד⟧<b>ולבן<\/b> שינים מחלב. פירוש כי שינים הם הטוחנות את המאכל להיות מתעכל במעיו שעי\"ז יהי' מזון לגוף משא\"כ כשלא ילעוס ויטחון המאכל בשיניו לא יבא לידי עכול כלל ולא יהיה לו למזון ולשובע."],[66,"וכך עד\"מ כדי שיהי' מזון לרמ\"ח אברין דמלכא שתהא נפשו מרכבה אליהם שיתאחד ממש עם הנפש צ\"ל בבחי' שינים הטוחנות ומפררות דהיינו לפרר ולברר כל מעשיו ודבוריו ומחשבותיו ולדקדק ולפשפש בהן ולהיות ממארי דחושבנא לשקול כל דרכיו ולפלס מעגלותיו."],[66,"ונק' בלשון הגמ' מדקדק במעשיו שעי\"כ יהיה בבחי' עכול בנפש שהטוב יקבל למזון ולשובע והפסולת המעורב תערובת זר ופסולת ידחה לחוץ. וכן בענין בירורי המדות אוי\"ר כל חד לפום מאי דמשער בלבי' ושוקל במאזני שכלו כיצד היא האהבה האמיתית לה'."],[66,"וכיצד היא בחי' אתהפכא חשוכא כו' באמת לאמתו להיות מייגע א\"ע ביגיעת הנפש לבא למדרגה זו שיהיה נקבע בלבו באמת לאמתו בלי דמיונות כו' וכיוצא בזה כמה דרכים הידועים למבקשי ה' יבינו כל מאליהם שצריך לדקדק ולפשפש כו' ולהיות מייגע עצמו כו'. אך אח\"כ יגיע לבחי' ומדרגת החלב. כמו שהחלב עד\"מ מגדל את הולד להיות אבריו נגדלים. כך בחי' החלב של תורה מגדל את מדותיו אהוי\"ר כו' להיות לו אוי\"ר היותר גדולים בגדלות המוחין (שהאברים הם המדות ועיקרם הם חג\"ת נה\"י ובחי' חב\"ד שבתוכן המקיימות אותן וכל א' מג' מיני בחינות אלו כלולה מכל הנ\"ל הרי פ\"א. וכל בחי' נחלקת לג' בחי' ראש תוך סוף הרי רמ\"ג. ושרשם ה\"ח המגדילים הרי רמ\"ח). וזהו רוחצות בחלב כו' שהחלב מרחיץ המדות ונהפכין ממהות למהות להיות נהפך לבו ונעשה כאיש אחר לגמרי בשינוי המדות כולן שוין לטובה. ומזה יומשך להיות לבן שינים שיהיה בהם בחי' לבנונית ובהירות בבירורי המדות בעילוי אחר עילוי עד רום המעלות בבחי' ראיה חושיית שלא ביגיעה יגיעת הנפש ויגיעת בשר רק מיד יגיע אליו כו'. וזה חכלילי כו' מיין כו' מחלב כו' ובחי' יין וחלב נעשה הכל בחי' חכלילי לי לי עד רום המעלות:"],[67,"ביאור על הנ\"ל"],[67,"<b>לבאר<\/b> הדברים הנאמרים למעלה ע\"פ חכלילי כו'. הנה התורה נק' יין וחלב וכמו שכתוב ולכו שברו בלוא כסף ובלוא מחיר יין וחלב. ולהבין זה הנה צריך להבין ענין ב' בחי' אה\"ר ואה\"ע. אה\"ר היא הבאה מלמעלה אשר מאליה וממילא נפשו בוערת כתנור אש ואה\"ע היא האהבה הבאה ע\"י ההתבוננות ויש אהבה ג' הגדולה משניהם והיא הנקראת אהבה בתענוגים כו'."],[67,"והנה ידוע שיש ד' שמות ע\"ב ס\"ג מ\"ה וב\"ן. והנה שם ב\"ן נפל בשבירה ושם מ\"ה הוא המברר. ואמנם תחלה מברר מל' דאצי' הנקראת שם ב\"ן את רפ\"ח נצוצין שבבי\"ע כו' ואח\"כ נמשך שם מ\"ה לברר שנית כו'."],[67,"וביאור הדברים הנה נודע דמל' דאצי' יורדת בכל לילה בבי\"ע לברר בירורים. וכמ\"ש בזוהר אלף טורין דאכלה בהמה רבה ושתית לון בגמיעא חדא כו'. פי' בהמה בגי' ב\"ן והיינו מל' דאצי' המבררת נצוצין דתהו. להיות שכאשר נפלו הנצוצין בבי\"ע ובנוגה הם מעורבים טו\"ר ואינם בבחי' אלהות ומל' דאצי' מבררת אותם שיתהפכו להיות אלהות."],[67,"ולכן שם ב\"ן נק' אה\"ע כי עולם מל' העלם והיינו האהבה שנתגלית מההעלם. שקודם התפלה היתה בהעלם ואחר כך ע\"י התפלה נתגלית ונמצא שאהבה זו היא ⟦מח,א⟧באה מההתבוננות כו' וגם פי' אהבת עולם שהתפעלות ואהבה זו נמשכת מבחינת העולם. היינו כמו עד\"מ האדם מתפעל להיות לו אהבה ע\"י שרואה מופתים הפך הטבע כמו להפוך ממים לאש או מאש למים שיתהפך מהות אחד למהות אחר עי\"ז רואה גדולת ה' ית' ויגיע לו מזה אהבה לה'."],[67,"ואהבה זו נק' אה\"ע שבאה ע\"י סבה מבחי' העולם וכמו\"כ למעלה הבירור נצוצות דשם ב\"ן שמברר בבי\"ע נק' אה\"ע מפני שמבחי' עולם נברר להיות אלקות כו'. משא\"כ שם מ\"ה נק' אה\"ר. להיות ששם מ\"ה הוא בחי' אלקות בעצם (לא ממה שנתברר מבחי' עולם כמו שם ב\"ן שמברר בי\"ע והם נכללים בו. והיינו ע\"י ההתהפכות מרע לטוב כנ\"ל שנכלל בשם ב\"ן ולכך נק' אה\"ע כמו שאדם מתהפך ע\"י מופתים כו' כנ\"ל). והוא המברר שם ב\"ן. וה\"ז כדוגמת אה\"ר. דהנה ענין האה\"ר היא עד\"מ האהבה אשר מאליו מתלהט שלכך נק' בלשון רבה. להיות שאה\"ע הנה יש גם בזה לעומת זה. ולכך אנו רואים שאעפ\"י שבעת התפלה הי' לו אהבה והיא אה\"ע מ\"מ אח\"כ עוסק במילי דעלמא מפני שיש זלעו\"ז ששניהם הם בחי' עולם זה עולם וזה עולם כו' משא\"כ בחי' אה\"ר להיותה מניצוץ אלקות עצמו אין שם זלעו\"ז כו'. וכמו\"כ למעלה שם מ\"ה הוא אלקות שלא ע\"י בירור. כמו האה\"ר שבאה מאיליה מלמעלה."],[67,"והנה עכ\"ז הרי האה\"ר שנק' מ\"ה מתלבשת באה\"ע הנק' ב\"ן לברר בירור שני כו' אבל אהבה ג' והיא הנק' אהבה בתענוגים שהוא ענין שם ע\"ב אינה מתלבשת כלל לא באה\"ר ולא באה\"ע כו':"],[67,"<b>אך<\/b> הנה המשכת שם ע\"ב אהבה בתענוגים. הוא כאשר נתחברו יחדיו אה\"ר ואה\"ע שם מ\"ה ושם ב\"ן אזי ממשיכים גם שם ע\"ב. הגם שהוא גבוה משניהם כו'. וביאור הדברים הנה ידוע שיש בכל עולם דאצי' בי\"ע ע\"ס ועולמות והיכלות."],[67,"והנה ע\"ס הם הם אלקות שאינו צריך להתברר והיינו כענין שם מ\"ה כידוע. ועולמות והיכלות הם צריכים להתברר בכדי להתכלל בע\"ס שהוא אלקות ממש. והיינו ע\"י הבירור דב\"ן שנכללים בו הבירורים דעולמות והיכלות ואחר כך נמשך שם מ\"ה להתלבש בב\"ן לברר שנית כו'. וזהו ענין יחוד הוי' אלהים שהם דו\"נ מ\"ה וב\"ן. והנה כתיב זכר ונקבה בראם ויברך אתם כו' ומבואר בזהר הטעם דקוב\"ה לא שרי באתר פגימא אלא באתר שלימא כו'. והענין מפני שכאשר מתכללים ב' בחינות דו\"נ ע\"כ מעוררים בחינת הגבוה מערך שניהם (וכענין החופה שנכנסי' בו חתן וכלה להיות שבאים שניהם דו\"נ ע\"כ בא שם הגילוי גם מבחי' מקיפים כו'). והיינו ע\"י שכאשר שם ב\"ן מברר בי\"ע ואז מעלה אותם מ\"ן לשם מ\"ה והוא נמשך לברר כו'. ואח\"כ כששניהם מתלבשים זה בזה בחי' יחוד הוי\"ה אלהים אזי נמשך גם שם ע\"ב הנק' אהבה בתענוגים. וזהו זכר ונקבה בראם. היינו דכר שם מ\"ה ונוק' שם ב\"ן ואזי ויברך אתם המשכת החכמה שם ע\"ב הנק' ברוך כו'."],[67,"והנה ידוע שגילוי אור א\"ס דעתיקא קדישא הוא בבחינת החכמה דאצי' להיותה בתכלית הבטול. והנה עתיק הוא על דרך משל בחינת תענוג כו'. וכמו שאנו רואים גם כן שגילוי התענוג הוא בחכמה כאשר יגיע לו השכלה חדשה מהמשכיל שזהו ענין גילוי החכמה ממקורה אז יתענג ענג נפלא כו' וכמו\"כ גלוי אא\"ס ע\"י וא\"א הוא בבחינת חכמה דאצי' ⟦מח,ב⟧שהוא שם ע\"ב. ולכך נק' שם ע\"ב אהבה בתענוגים להיות שהוא גלוי תענוג עליון וזהו אהבה בתענוגים דייקא כו':"],[67,"<b>וזהו<\/b> חכלילי עינים מיין. וארז\"ל חכלילי כל חיך הטועם אומר לי לי. וי\"ל כפל הלשון לי לי. אך הענין הוא שזהו ענין ב' עליות של ב' בחינות אה\"ר ואה\"ע מ\"ה וב\"ן בע\"י וא\"א כנ\"ל מפני שהן עולים בבחינת שם ע\"ב ששם גילוי עתיק ואריך כו'."],[67,"וזהו חיך הטועם אומר לי לי פירוש חיך הטועם הוא בחינת חכמה דאצי' שנק' חיך שם מ\"ה והוא בחינת טעמים שהם בשם ע\"ב כנודע שיש ד' בחי' טנת\"א כנגד ד' שמות ע\"ב ס\"ג מ\"ה ב\"ן וחכמה דאצי' היא בחינת חיך הטועם היינו בחינת טעמים. וכמו עד\"מ כאשר יטעום האדם איזה מאכל הנערב ומתוק מתענג מזה כמו\"כ בבחי' טעמים דחכמה יש שם גילוי עתיק כו'. וזהו חיך הטועם בחי' ע\"ב חכמה אומר לי לי הוא בחי' עליות אה\"ר ואה\"ע."],[67,"והנה חכלילי עינים הם מיין. כי הנה ע\"י שנכנס יין יינה של תורה יצא סוד. פי' סוד היינו אה\"ר המסותרת שתצא מההעלם אל הגילוי להיות התלבשות אה\"ר מ\"ה באה\"ע ב\"ן. ועי\"ז שניהם עולים ונכללים בחכמה. וזהו חכלילי כו' מיין. פי' מה שחיך הטועם אומר לי לי העלייה דמ\"ה וב\"ן בע\"ב זהו מיין שעי\"ז שנכנס יינה ש\"ת יצא סוד התלבשות מ\"ה בב\"ן ועי\"ז מעוררים שם ע\"ב להיות חיך הטועם כו'."],[67,"והנה בחי' גילוי זה דשם ע\"ב הוא בשבת שהוא ענין מוחין דאבא. והיינו גילוי והמשכת ענג העליון בחי' עתיקא קדישא בבחי' החכמה. וכמ\"ש וקראת לשבת ענג להמשיך ולקרוא הענג בחכמה כו'. וכמ\"ש במ\"א ע\"פ מארז\"ל כל האומר ויכלו בשבת כאלו נעשה שותף להקב\"ה במעשה בראשית כו'. וזהו ג\"כ כל כוונת האכילה בשבת להמשיך בחי' עתיק בחכמה כו'. אך הנה ארז\"ל מי שטרח בע\"ש יאכל בשבת. וזהו חכלילי עינים כו'. פי' כי יש ב' בחי' בעינים הא' האדמומית והזהרורית שבעינים. והב' חוורי דעינא."],[67,"והנה ענין האדמומית הוא בחי' ההתלהבו' ורשפי אש לאסתכלא ביקרא דמלכא כמ\"ש הסבי עיניך מנגדי כו' דאינון מוקדין ליה בשלהובין דרחימותא כנודע. וכמו\"כ הנה מבואר באדרא רבה כד ז\"א מסתכל במצחא דאריך מקבל ש\"ע נהורין ובפנים ק\"נ נהורין כמה שכתוב כי יקרא ק\"ן צפור לפניך כו'. והענין דהנה א\"א שהוא הכתר הוא בחי' התחתונה שבמאציל וז\"א הוא מקור לעלמין דבי\"ע שלכך ז\"א נק' עולם כמ\"ש עולם חסד יבנה כו'. ולכך הז\"א מתלהב ליכלל למעלה באוא\"ס בחי' א\"א כו' (וכן עבודת האדם למטה לאסתכלא ביקרא דמלכא עיני תמיד אל ה' והיינו ההתלהבות ממטלמ\"ע שהוא ע\"י העינים דוקא) והיינו האדמומית שבעינים שמורה על ענין ההתלהבות ורשפי אש כו'. וע\"י ההסתכלות ז\"א בבחי' התלהבות נמשך אח\"כ השפע מא\"א לז\"א. וכמ\"ש עין ה' אל יראיו כו' (והיינו מפני שהקדים תחלה עיני תמיד אל ה' והוא התלהבות ממטלמ\"ע. וזהו מי שטרח בערב שבת כו'. עי\"ז נמשך אח\"כ אור השפע מלמעלה למטה להיות עין ה' כו'). וזהו ענין ש\"ע נהורין או ק\"ן נהורין דמקבל ז\"א מא\"א היינו השפע מלמעלה כו' שהוא בחי' עינא דאיהו חוור כמ\"ש באד\"ר (דקכ\"ט ב' ובדף קל\"ו ב') ואתסחן בחד חוורא דעינא טבא כו'. והנה הראיה היא בחי' חיצוניות משא\"כ שארי כחות כמו כח החכמה או המדות כו' והענין כי להיות מסתכל במצחא דא\"א ולקבל אח\"כ גילוי האור משם א\"א לקבל רק ע\"י ראיה ⟦מח,ג⟧שהיא מבחוץ שאינה נכנסת לפנים."],[67,"ולבן שינים הנה השינים מבררים כו'. והוא בחי' עבור בבטן אימא כמשל מדות שבשכל לראות בעין השכל מהות המדות ולדקדק ולפשפש בהן אם יש בהן תערובת כו'. וזהו בבטן אימא כו'."],[67,"ולמעלה בז\"א תלת כלילן גו תלת כו' ומה שנתברר נעשה אצי' ואלקות והפסולת נדחה לחוץ כו' וכן עד רום המעלות כו' ואח\"כ נעשה הגדלה בחלב שלאחר הלידה והגדלה זו שנמשך אור וחיות שיהיו המדות מאירים וברורים כו'."],[67,"וזהו ולבן שינים שהשינים עצמם נעשים לבנים מכח החלב שבשעת הבירור עדיין אינם לבנים מאחר ⟦מח,ד⟧שעוסק לראות ולפשפש כו'. והוא בחינת קטנות משא\"כ לבן שינים שנעשו לבנים ומאירים כו'. שיש בירור אחר בירור כו' והכל הוא ע\"י פותח את ידיך הוא בחי' י\"ג ת\"ד שהם יודי\"ן ווי\"ן שערות וגומות שאבא יונק ממזל הח' נוצר אותיות רצון כו' ועי\"ז נעשה רצון גם לכל חי כו' והוא ע\"י התו' אבא שממשיך אור אבא על נפשו ואבא יונק ממזל הח' כנ\"ל ומתגלה בתוכה רצון שלמעלה מעלה כו' ומשל יודי\"ן ווי\"ן כי היו\"ד הוא צמצום האור בעור הפנים המכסה ואינו יוצא אלא דרך גומא. והוא\"ו הוא המשכת השערות כו' וד\"ל:"],[68,"⟦מט,א⟧<b>ואלה שמות בני ישראל הבאים מצרימה את יעקב איש וביתו באו.<\/b> הנה בפרשת ויגש נאמר גם כן ואלה שמות בני ישראל הבאים מצרימה יעקב ובניו. וצ\"ל למה הוכפל בתורה ענין בואם מצרימה. גם להבין השינויים מהתם להכא. דכאן נאמר הבאי' מצרימה את יעקב."],[68,"ובויגש נאמר הבאי' מצרימה יעקב. ועוד צ\"ל מ\"ש בפרשת ויגש בני ישראל כו' יעקב ובניו שכולל יעקב ג\"כ בכלל בני ישראל והרי יעקב הוא ישראל עצמו כמ\"ש לא יעקב יאמר עוד שמך כ\"א ישראל."],[68,"וא\"כ איך נק' בני ישראל. והענין דהנה כתיב ירד ירדנו כו' ירידה אחר ירידה וכן ביצ\"מ וגאולה כתיב ואנכי אעלך גם עלה כו' עלה נעלה כו'. היינו ב' עליות שהוא עילוי אחר עילוי ובאמת ביצ\"מ לא נתעלו רק פעם א' כמ\"ש אעלה אתכם מעני מצרים כו' אל ארץ זבת חלב ודבש. אך כי עלייה זו השנית היא רומזת על גאולה העתידה להיות בב\"א (וכן בשמות ג' פסוק י\"ד אמר לו ענין הגאולה האחרונה כדפירש רש\"י שם):"],[68,"<b>דהנה<\/b> כתיב כימי צאתך מארץ מצרים אראנו נפלאות שמקיש הכתוב ענין גאולה אחרונה ליציאת מצרים. והוא שכמו שכל עיקר תכלית המכוון בגלות מצרים והשעבוד רד\"ו שנה הי' בכדי לזכו' לקבלת התורה פנים בפנים דבר ה'."],[68,"וכמ\"ש וזה לך האות כו' בהוציאך את העם ממצרים תעבדון את האלקים על ההר הזה. כך כל אריכות הגלות הזה הוא כדי לזכות לגילוי פנימית התורה שיהי' לע\"ל כי במתן תורה הי' קבלת התורה הנגלית אבל פנימית טעמי התורה יהי' הגלוי שלהם לע\"ל."],[68,"וע\"ז נאמר אראנו נפלאות. וכמ\"ש עין בעין יראו. וכך בענין השעבוד והגלות שנאמר בגלות מצרים וימררו את חייהם בעבדה קשה בחומר ובלבנים ובכל עבדה בשדה. קאי גם על זמן האחרון וימררו את חייהם היא התורה כי היא חיינו. בעבדה קשה דא קושיא. בחומר דא קל וחומר."],[68,"ובכל עבדה בשדה דא ברייתא. ובלבנים דא לבון הלכתא. שאין בידינו הלכה ברורה ודין ברור כי כל דיני התורה במחלוק' שנויה הללו מכשירין ומטהרין והללו פוסלין ומטמאין. וא\"כ כמו שע\"י שעבוד מצרים בחומר ובלבנים זכו למתן תורה כך ג\"כ ע\"י לבון הלכתא שבזמננו זה. יזכו לגלוי פנימי' התורה לע\"ל להיות אראנו נפלאות:"],[68,"<b>והנה<\/b> להבין ענין לבון הלכתא (וגם ענין בכל עבודה בשדה) ואיך עי\"ז יהי' הגלוי לע\"ל. יש להקדים פי' וענין מלך משובח ומפואר עדי עד שמו הגדול. כי הנה תכלית ירידת הנשמה לעוה\"ז ירידה צורך עלייה היא כדי לחזות בנועם ה' בעוה\"ב ובג\"ע העליון וג\"ע התחתון שהוא השגת הנשמות נהנין מזיו השכינה שהוא תענוג נפלא עד אין קץ ותכלית בלי גבול."],[68,"והנה בספרים לא נזכר כ\"א ג\"ע עליון ותחתון אבל באמת יש כמה בחי' ג\"ע ותענוגים עד אין קץ וזהו משובח ומפואר עדי עד. וכמארז\"ל צדיקים אין להם מנוחה בעוה\"ב שנאמר ילכו מחיל אל חיל. ונועם ה' והתענוג ההוא הוא ⟦מט,ב⟧מבחי' גלוי משמו הגדול כו'. אשר כדאי כל יסורי גיהנם כדי לחזות בנועם ה' וכמארז\"ל מוטב דלידייני' כו':"],[68,"<b>והנה<\/b> ארז\"ל שאברהם בחר לו שעבוד גלות תחת יסורי גיהנם. כי הנה ענין הגיהנם הוא כדי לצרף הנפש מחולאת הרע אשר בקרבה כמו מצרף לכסף שהפסולת והסיגי' נשרפים תוך הכור ונשאר הכסף נקי מכל סיג כך כדי שתוכל הנפש לקבל אור ענג העליון להיות נהנים כו' צריכה להתברר תחלה באש של גיהנם להפריד הרע מן הטוב כי לא יגורך רע כתיב והנה אברהם בחר לו שעבוד גלות שהוא ג\"כ בחי' צירוף לנפש כמ\"ש מכור הברזל ממצרים. וגלות אדום נק' כור עוני כו':"],[68,"<b>אך<\/b> הנה הנשמה היא נברא' ובעל גבול וא\"א לנפש לקבל הארת תענוג העליון שהוא בלי גבול עדי עד. אלא ע\"י התלבשו' אור התענוג בכלי ולבוש כמ\"ש עוטה אור כשלמה שהוא אור תורה וכמ\"ש ונהר יוצא מעדן להשקות את הגן כי עדן הוא בחינת מקור התענוגים. (וכמ\"ש בפרדס בערכי הכינויים ערך עדן בשם התיקוני זוהר עדן עילאה הוא בחינת כתר עליון ולכן נאמר על בחי' עדן עין לא ראתה כו'). ונהר יצא מעדן זה להשקות את הגן היינו בחי' ג\"ן סדרים דאורייתא כי אורייתא מחכמה נפקת ואין התלבשות אור א\"ס ב\"ה אלא בחכמה כח מ\"ה בחי' בטול ונחנו מה כו' ולכן ע\"י התורה תוכל הנשמה להשיג שמו הגדול (שהוא בחי' כתר עליון מלכות דא\"ס שנקרא שמו הגדול שנמשך ומתלבש בחכמה כו') כי כל התורה היא שמותיו של הקב\"ה כו':"],[68,"<b>וז\"ש<\/b> רז\"ל ששים המה מלכות אלו ששים מסכתות ושמונים פלגשים אלו הברייתות ועלמות אין מספר אלו ההלכות. והנה דמיון ומשל המשניות למלכות וכמארז\"ל מתניתא מלכתא הוא ע\"פ מארז\"ל אשה מזרעת אודם שממנו בשר כו' נמצא שעיקר הזרעת הולד הוא מטפת נוקבא. וכמ\"ש אשה כי תזריע וילדה כו' וטפת דכר הוא רק כדי לברר טפת נוקבא שמהטוב ומובחר נוצר הולד וכמ\"ש ותזרני חיל מלשון זורה את גורן בחי' בירורי' (ובאמת זהו ענין בירור אחר בירור שהרי טפת נוקבא היא נמשכ' ג\"כ אחר הבירור שהרי התהוות טפה זו הוא מהמאכלים שאוכלת ונתבררי' עד שנהפכים לדם בכבד ועולה ללב ומשם למוח ואח\"כ נמשך מהמוחין שלה הזרעת הטפה כמ\"ש בע\"ח של\"ט. נמצא המשכה זו היא ממה שכבר נתברר בתכלית עד שנכלל במוחין דנוקבא אז משם נמשכה טפת נוקבא רק שאעפ\"כ כדי שיהיה מזה התהוות הולד אי אפשר עד שיתברר בירור שני ע\"י טפת הדכר כנ\"ל). וכך הנה המשניות הם בחינת בירורים בחכמה אתברירו טמא וטהור אסור ומותר. פי' מותר שאינו אסור וקשור בידי החיצונים ויוכל לעלות וליכלל בקדושה כי הדם הוא הנפש. והנה מכל מאכל אשר יאכל נהפך לדם כי תלת שליטין אינון כבדא ולבא ומוחא שנתברר הדם בירור אחר בירור ובכח האכילה הוא קורא ומתפלל בכל לבבו ובכל נפשו כו'. אבל מאכלות האסורות הגם שלומד ומתפלל בכח האכילה ההיא אינה עולה לה' להיות בכל לבבך כו' והוא בירורי המאכלים."],[68,"וכן בירורי לבושים ובתים בחינת מקיפים הנה הבירור הזה הוא ע\"י בחי' חכמה בחי' משניות אך להיות נמשך ח\"ע חכמתו ית' חכים ולא בחכמה ידיעא להיות בחינת הבירורים הוא על ידי התנאים בעלי המשנה וכמו שכתוב והאיתנים מוסדי ארץ. איתנים אותיות תנאים שהם המיסדים את הארץ בחינת תורה שבעל פה וכמו שכתוב משכיל לאיתן שממשיכים מבחינת משכיל וכתיב משכיל על דבר כו' ולכן נק' מלכתא שיחוד המלך עמה הוא תמידי ויחוד זה הוא המשכת מ\"ד דח\"ע לברר המ\"ן דב\"ן. והיינו ע\"י התנאים ⟦מט,ג⟧חכמי המשנה. כי תנאים אותיות איתנים שמקבלים מבחי' חכמה (יסוד אבא נק' איתן ע' באגה\"ק ע\"פ וצדקה כנחל איתן) ע\"ד משה קבל תורה מסיני כו' עד ונביאים מסרוה לאנשי כנה\"ג הרי קבלתם ממשה שהוא בחי' חכמה ולכן עיקר פסקי הלכות שלהם לא היה ע\"פ הכרעת שכלם רק ממה שקבלו איש מפי איש עד משה. וכמארז\"ל (סוכה דף כח.) גבי ר' אליעזר י\"ב אמר להם שמעתי י\"ח אמר להם לא שמעתי. וכן גבי עקביא בן מהללאל. אני שמעתי מפי המרובים כו'. והיינו לפי שהיו בבחי' אין ובטול ממש. ע\"כ האירה בהם בחי' משה שהוא בחי' בטול אמיתי ונחנו מה (בחי' מ\"ה דמ\"ד המברר ב\"ן שהוא בירור אחר בירור) מן המים משיתהו. משא\"כ אליהו בגימטריא ב\"ן הבטול בחיצוניות. ולכן עלה גופו כו'. ולכן ההלכות שאמרו התנאים במשנה הם בחי' אלהות ממש שהוא מה שנמשך אחר בירור ב' דמ\"ה דחכמה עלאה."],[68,"וכמארז\"ל אלו ואלו דא\"ח הן ולכן מותבינן תיובתא מנייהו. וזהו שארז\"ל אין הגליות מתכנסות אלא בזכות המשניות שנאמר גם כי יתנו בגוים עתה אקבצם. כי ענין קבוץ גליות הוא ענין בירור והבדלה כו' הוא בזכות המשניות בחי' בירורים כנ\"ל. גם אמרו אין ישראל נגאלין אלא בצדקה שהיא בחי' עלייה אחר ההבדלה. הוא ע\"י הצדקה כי צדקה תרומם כו' וימינו תחבקני דוקא וכמ\"ש ואתם תלקטו לאחד אחד כו'. למיהוי אחד באחד הוא ע\"י הצדקה תרומם כו':"],[68,"<b>ופלגשים<\/b> אלו ברייתות כמשל הפלגש שיחוד המלך עמה רק באקראי ובהצנע כו'. וכך הנה המשכת ח\"ע בברייתות הוא לפרקים. וכמארז\"ל כל מתניתא דלא מתניא בי ר' חייא ור' אושעיא לאו מתניתא (שאינן ודאים וברורים וע\"ד שנשתכחו שלשת אלפים הלכות בימי אבלו של משה. וכך ענין מתניתא דלא מיתני' בי ר\"ח ור\"א אינן ודאים כ\"כ כי לא נמשך בהם טפת מ\"ד מבחי' עדן העליון. והיינו לפי שהם מבריאה ולא מאצילות כי באצי' מאיר ח\"ע שהוא בחי' בירור השני בחכמה אתברירו. אבל במתניתא דלא מיתנו בי ר\"ח ור\"א לא נמשך מבחי' האצי' מבירור האמתי ע\"כ אינן ודאים כ\"כ רק מתניתא דר\"ח ור\"א הם נמשכים ע\"פ הבירור הב' דח\"ע שהוא בחי' יחוד עליון דמ\"ד ומ\"ן ואעפ\"כ נק' רק פילגשי' כמו הפלגש שהיחוד עמה באקראי ובהסתר כו'). משא\"כ מתניתין מותבינן מינה תיובתא ואין להשיב. ולמעלה היא ענין מארז\"ל מיכאל עומד ומקריב נשמות הצדיקים ע\"ג המזבח שהוא בחי' בירור בנשמות הראויים ליכלל באוא\"ס שהוא לפרקים כו' (וכמ\"ש במ\"א בפי' הזהר פ' חיי שרה ע\"פ והנה רבקה יוצאת כו'):"],[68,"<b>ועלמות<\/b> אין מספר אלו ההלכות שהן מימרות האמוראים דלא מותבינן מנייהו תיובתא כלל. וכמארז\"ל גברא אגברא קא רמית. שנק' עלמות לשון בתולות. עד לא קבילת דכר אקרי כו'. שאין השראת ח\"ע דאצי' בתוכו כי תלמוד בבריאה ונק' בורא חשך שאין מאיר שם ח\"ע בגילוי כו' רק שהן בחי' כלי מכון להשראת ח\"ע כדכתיב בתולות אחריה רעותיה מובאות לך תובלנה בשמחות וגיל תבואנה בהיכל מלך. וזהו ענין לבון הלכתא שצריך ללבן ההלכות ולהמשיך בתוכן ח\"ע חכים ולא בחכ' ידיעא כו' חכמתו ית' כו' (שבה מלובש בחי' עדן העליון ובחי' שמו הגדול כו' כנ\"ל. ולבון הלכתא הוא ע\"י קושיות ופירוקים כענין שמצינו ברשב\"י בפ' ב\"מ שעי\"ז ממשיך עומק החכמה וזהו בחי' לבון שממשיך מבחי' לובן העליון שהוא בחי' כתר וחכמה וזהו ענין עצי הלבנון וכנודע מענין בגדי לבן דכה\"ג ביוה\"כ וכל ענין העבודה גם עכשיו בלבון הלכתא זהו לברר בירורים הנ\"ל. ואז לע\"ל כתיב בתולות אחריה רעותיה מובאות לך:) <b>ובזה<\/b> יובן מ\"ש בזוהר דכל התורה ומצות הוא לאתקנא רזא דשמיה כי הנה יש ז' שמות שאין נמחקין והיינו שם אל בחסד כו' כי כדי שיהיה המשכת אור א\"ס ב\"ה דלאו מכל אינון מדות איהו כלל במדת החסד כדי להיות עולם חסד יבנה הוא רק מבחי' שם והארה בעלמא מא\"ס ב\"ה והוא בחי' שם אל."],[68,"וכידוע שאין ערוך השם של האדם עד\"מ לגבי עצמותו וכלא חשיבי. וכן שם אלקים בגבורה. ולכן כדי להמשיכו ית' להתלבש במדותיו להיות עולם חסד יבנה הוא ע\"י התומ\"צ ע\"י מצוה זו נמשך שם זה במדה זו כו' אך עיקר הפי' לאתקנא רזא דשמיה היינו להמשיך מבחי' שמו הגדול שהוא בחי' א\"ס."],[68,"וכנודע שיש יחוד שם הוי\"ה ואדני שהוא המשכה מבחי' שם הוי\"ה סוכ\"ע בשם אדני בחי' ממכ\"ע. וע\"י התומ\"צ הוא המשכה מבחי' שמו הגדול כנ\"ל בענין משובח ומפואר עדי עד שמו הגדול."],[68,"ועי\"ז לאתקנא רזא דשמיה שיהי' נמשך גלוי בחי' זו בשאר כל השמו' וז\"ש ר\"פ וארא אל אברהם כו' ושמי הוי' לא נודעתי להם לפי שלא ניתנה התורה להם כי גלוי שם הוי' שהיא בחי' שמו הגדול הוא ע\"י מתן תורה וכמ\"ש במ\"א."],[68,"וזהו ענין וקרבתנו מלכנו לשמך הגדול כי להיות המשכה זו מבחי' שמו הגדול הוא דוקא ע\"י נשמות ישראל. וז\"ש כי לא יטוש ה' את עמו בעבור שמו הגדול וכתיב ביהושע ומה תעשה לשמך הגדול כי תלת קשרין מתקשרין דא בדא ישראל מתקשרין באורייתא ואורייתא בקוב\"ה. וארז\"ל דהע\"ה היה מחבר תורה שלמעלה בהקב\"ה דהיינו להיות הקב\"ה יושב ונשפל בתורה שהוא התחברות והמשכת בחי' שמו הגדול בחכמה כו':"],[68,"<b>וזהו<\/b> פי' ואלה שמות בני ישראל וגו' שמות ממש ע\"ד מ\"ש ויעש דוד שם. ופי' בזוה\"ק דעביד שמא קדישא שהמשיך בחי' גלוי שם הוי\"ה למטה להמשיך אור א\"ס מבחי' חכמה עילאה יו\"ד של שם. וה' של שם בחי' הדבור ורוח פיו ית' כו' לעולם העשי' כמ\"ש באגה\"ק וכך הוא פי' שמות בנ\"י שבנ\"י ממשיכים ועושים בחי' גלוי שמות עליונים למטה. וכמש\"ל בפי' לאתקנא רזא דשמיה כו' ובפי' משובח ומפואר עדי עד שמו הגדול (ובפרטות יעקב וי\"ב בניו השבטים ששרשן ממש באצי' בע\"ס שהן הן השמות עליונים וכנודע ג\"כ בפע\"ח איך יחוד קוב\"ה ושכינתי' נק' יחוד יעקב ורחל או ישראל ורחל והיינו יחוד הוי\"ה באדני. כי שרש נשמת יעקב נמשך מבחי' שם הוי\"ה ושרש נשמת רחל נמשך מבחי' שם אדני ולכן כנס\"י נמשלה לרחל כמ\"ש כרחל לפני גוזזי' כו' וכן י\"ב שבטי' הם כנגד י\"ב צירופי הוי\"ה שבכל חדש מאיר צירוף אחד מי\"ב צירופי הוי\"ה באדני כו' כמ\"ש במ\"א. וז\"ש בשבטים הראובני השמעוני כו' שיש שם י\"ה בכל א' מהשבטים כו'. ופי' ואלה שמות היינו כי המשכת השמות הוא ע\"י התורה כנ\"ל בענין ס' מלכות כו' ושיתא סדרי משנה וכל א' כלול מו' זהו בגימט' אלה כמ\"ש במ\"א ע\"פ אלה פקודי המשכן והוא בחי' המשכה אך מקודם צ\"ל העלאה והיינו ע\"י שם מ\"ב וזהו ואלה גימט' מ\"ב ועמ\"ש במ\"א פ' תולדות ע\"פ ויקרא להן שמות כשמת שהא' בוי\"ו והב' בלא וי\"ו ע\"ש). אך פי' וענין ואלה שמות כו' הבאי' מצרימה קאי על זמן הגלות כי יש בחי' מצרים דקדושה למעלה כמ\"ש בלק\"ת בענין הגרון שנק' מצרים לשון מצר כו' והיינו כי מצרים לשון מצר בחי' העלם והסתר וידוע דבזמן הגלות כתיב אותותינו לא ראינו. ופי' שהאותיות ושמות עליונים שאנו ממשיכים ע\"י התורה ותפלה לא ראינו שאינן בבחי' גלוי אצלנו. והיינו לפי שהן מתעלמים בבחי' מצרים בחי' מקום צר המעלים ומסתיר כו' משא\"כ א\"י נק' ארץ טובה ורחבה שהיא בחי' גלוי כו':"],[68,"⟦נ,א⟧<b>וביאור<\/b> הענין הוא דהנה שמו הגדול הוא שם הוי' וידוע דיו\"ד הוא בחי' צמצום וה' התפשטות אורך ורוחב כו'. לפי שכך היא דרך המשכה מא\"ס ב\"ה בעולמות שצ\"ל תחלה צמצום ואח\"כ התפשטות כו'. (וכך הוא בענין הירידה והמשכת האור מתחלה בבחי' מצרים דקדושה ואח\"כ בחי' ארץ טובה ורחבה בחי' התפשטות וגלוי) והנה כתיב ירד ירדנו (מצרימה) כו' ירידה אחר ירידה וכן ביצ\"מ וגאולה כתיב ואנכי אעלך גם עלה כו' עלה נעלה כו' עילוי אחר עילוי. ולבאר כל זה בענין מצרים דקדושה וירידת בנ\"י ויעקב לשם יש להקדים משל א' והוא כי הנה אותיות המחשבה והדבור שניהם ממקור א' נובעים הוא אור השכל כי המדות חסד דין ורחמים נמשכים מן השכל והמחשבה נמשכת מן המדות (היינו ע\"פ רוב שהרי אין שום מחשבה אא\"כ יש תאוה לדבר זה אך לפעמים המחשבה מקבלת מהשכל עצמו וממדות שבשכל אף שלא נתפשט' עדיין המדה בלב וכנודע מענין ההפרש בין קפידא לכעס שהכעס הוא מדה בלב משא\"כ הקפידא היא רק במוח ועכ\"ז המחשבה מלא ממנה וכן עד\"ז בשארי מדות שבשכל יוכל להיות המחשבה מקבלת מהן עצמן שלא ע\"י המדות שבלב ותדע דאפי' הדבור מקבל לפעמי' מהשכל שלא ע\"י המדות. וזהו ענין ר\"ח כנז' ע\"פ והיה מדי חדש כו' ע\"ש. וכ\"ש בענין המחשבה רק לפעמים מקבלת המחשבה ג\"כ מהמדות וע' במאמר הזהר דפ' פנחס ע\"פ אנכי אשמח כו' ע\"ש. גם לפי הנמשל דלקמן בענין ירידת יעקב למצרים דפ' ויגש יובן כן) ומשתלשל' ויורד' מטה מטה להיות אותיות הדבור ועכ\"ז עודם קשורי' ומיוחדים באור השכל המאיר ומתלבש בהם שהרי מחשבתו של אדם היא לפ\"ע שכלו וכן מדבורו של אדם נודע חכמתו. וע\"ד דוגמת משל זה יובן למעלה הגם שאין לו דמות הגוף כו' עכ\"ז הרי דברה תורה כלשון בנ\"א. דהנה כתיב מה רבו מעשיך ה' כולם בחכמה עשית הרי שהתהוות העולמות הוא ע\"י בחי' חכמה."],[68,"והרי כתיב בדבר ה' שמים נעשו שהתהוותם הוא ע\"י בחי' דבור. אלא היינו שנשתלשל' חכמתו ית' חכים ולא בחכמה ידיעא בדבר ה' הן עשרה מאמרות יהי אור יהי רקיע תדשא הארץ בחי' עלמין דאתגליין. וכן בבחינת עלמין סתימין דלא אתגליין שהוא בחי' מחשבתו ית' כביכול יש ג\"כ בחי' אותיות ומאמרות יהי אור כו' כנודע למעייני' בס' הזהר בענין ההיכלות שיש למעלה ג\"כ בעלמין סתימין בחי' שמים וארץ וכוכבים ומזלות מלאכים ונשמות ומן העולם ועד העולם מאיר ומתלבש בהן חכמתו ית' חכים ולא בחכמה ידיעא (והארה והמשכה הנמשכת מבחי' חכמה זהו בחי' יעקב והתלבשותו במחשבה ודבור שהן בחי' אותיות המגבילים זהו ענין ב' בחי' הירידות למצרים דקדושה ירידה אחר ירידה ממחשבה לדבור כמשי\"ת). והנה עצם ח\"ע קודם התלבשותה בבחי' עלמין דהיינו קודם התלבשותה גם בעלמין סתימין נק' ישראל לי ראש כו' (וכמו שבהראש מלובש הנשמה כמ\"ש בתניא פנ\"ג כך בחי' הארה משמו הגדול מלובש' בבחי' ישראל לי ראש היא בחי' ח\"ע. כמאמר וקרבתנו מלכנו לשמך הגדול וכמש\"ל). והמשכת ח\"ע להתלבש תוך עלמין נק' יעקב יו\"ד עקב שנמשך הארה מבחי' ח\"ע הנקרא יו\"ד להתלבש בבחי' עלמין שהן רק בחי' עקביי' לגבי ח\"ע עצמה. וכמ\"ש והארץ הדום רגלי שבחי' ארץ שהיא בחי' מל' נק' הדום רגלי והוא בחי' אותיות הדבור. ועד\"ז ג\"כ באותיות המחשבה כו' (ועמ\"ש במ\"א ע\"פ הזוהר פ' קדושים ועבדי אשר בחרתי דא יעקב כו' מענין זה. וז\"ש מידי אביר יעקב משם רועה אבן ישראל שבחי' אבן הוא אותיות כנודע בס\"י שתי אבנים בונות כו' והם מקבלים מבחי' יעקב) וזהו שנק' יעקב בריח התיכון המבריח מן הקצה אל הקצה. וזהו ענין ירידה ⟦נ,ב⟧הא' שבפ' ויגש ואלה שמות בני ישראל הבאים מצרימה יעקב ובניו שהיא ירידה בבחי' מצר וגבול להתלבש בבחי' עלמין סתימין. ולכן נאמר כאן בנ\"י יעקב שבחי' יעקב בשם בנ\"י יכונה שהרי הוא מקבל מבחי' ח\"ע שהוא בחי' ישראל (הנז' שם בפ' ויגש) לי ראש כנ\"ל:"],[68,"<b>והנה<\/b> בגלות נאמר אותותינו לא ראינו. דהנה ענין אותות ומופתים הוא שינוי הטבע כמו ולקחת ממימי היאור כו' והיו לדם ביבשת והוא ע\"י הארת ח\"ע בחי' שם הוי\"ה (כנ\"ל שבחי' שם הגדול מאיר בח\"ע). וז\"ש פרעה לא ידעתי את הוי' כ\"א בחי' שם אלקים בחינת הצמצום בדבר ה' שא\"א לשנות סדרי בראשית. אבל ע\"י הארת ח\"ע משתנים הצירופים כי התהוות המים הוא ממאמ' יקוו המים שנמשך בדבר ה' מע\"מ. אבל הארת החכמה יכול לשנות הצירוף ממים לדם."],[68,"וכנראה בחוש שהשכל מנהיג ומשנה הדבור כרצונו. וזהו ג\"כ ענין המטה שהיה מעץ החיים שנהפך לנחש ומנחש למטה שהוא ענין השינוי מהעלם לגלוי ומגלוי להעלם וכן מ\"ש השב ידך אל חיקך כו' ויוציאה מחיקו והנה שבה כבשרו כו'. ולכן היו כל המופתים ע\"י משה שהוא בחי' הארת החכמה כמ\"ש כי מן המים משיתהו בחי' ח\"ע. וז\"ש אותותינו לא ראינו אותותינו דייקא כי ישראל עלו במחשבה. לפי שבגלות הוא בחי' הסתר והעלם עד שנראה העולם ליש ודבר בפ\"ע. וכמ\"ש אתה אל מסתתר:"],[68,"<b>ובחי'<\/b> ירידה הב' הוא מ\"ש כאן ואלה שמות בנ\"י הבאים מצרימה את יעקב שבחי' ישראל לי ראש יורד בבחי' מצר וצמצום עם בחי' יעקב והוא ענין הירידה בבחי' עלמין דאתגליין ודבר ה' שהוא צמצום וירידה ב' ומבשרי אחזה שהקול היוצא מהבל הלב הוא קול פשוט ומתצמצם להיות נחלק בה' מוצאות הפה אחה\"ע מהגרון כו' וזהו ענין משה שהי' כבד פה וכבד לשון כי משה הוא בחי' הארת עצם החכמה א\"א לבא לידי גילוי בדבור כ\"א ע\"י בחי' צמצום."],[68,"וכמ\"ש ואתה תהיה לו לאלקים דייקא. ועכ\"ז עודנה קשורה ומיוחדת במקורו ושרשו בחי' ישראל לי ראש שמאיר ומתגלה גם בעולם הדבור כמ\"ש לא יעקב יאמר עוד שמך כי אם ישראל. (היינו בחינת חכמה המתלבשת במדות ומשם נמשך בדבור ולכן לא נק' יעקב בחי' בן לישראל זה) כמ\"ש ואתם תלקטו לאחד אחד למהוי אחד באחד. איש וביתו באו ראובן ושמעון בחי' ראיה ושמיעה שנמשך גם בעלמין דאתגליין מבחי' ישראל וכמ\"ש ותקרא את שמו ראובן כי ראה כו'."],[68,"ותקרא את שמו שמעון כי שמע הוי'. לוי עתה הפעם ילוה אישי אלי בחי' התקשרות ויחוד כי ראיה ושמיעה היא בחי' השגחה פרטית על כל דרכי בנ\"א ובוחן כליות ולב לפניך נגלו כל תעלומות לב שלא כדעת הכופרים בהשגחה פרטית ויאמרו לא יראה יה ולא יבין אלקי יעקב מאחר שנמשך בסדר ההשתלשלות בדבר ה' ועלמין דאתגליין. אלא שעודנ' קשורו' במקורן ושרשן (וזהו פי' ואלה שמות כו' שגם במצרים נמשך בחי' השמות עליונים איש וביתו דכר ונוקבא יחוד מ\"ה וב\"ן רק שאותותינו לא ראינו אך העלם זה הוא סבת הגלוי העצום אח\"כ וכמ\"ש בסמוך):"],[68,"<b>והנה<\/b> להיות בחי' הגלוי א\"א להיות אלא ע\"י בחי' העלם תחלה בחינת יו\"ד צמצום ואח\"כ ה' התפשטות אורך ורוחב כברייתו של עולם ברישא חשוכא והדר נהורא והוא ענין הגלות שבמצרים שהי' צ\"ל גילוי מתן תורה הנגלות לנו ולבנינו פב\"פ דבר ה' היה די בגלות רד\"ו שנה ולע\"ל שיתגלה פנימית התורה כי עין בעין יראו כו' ונגלה כבוד ה' כו' צריך כל אריכות החשך הזה ברישא חשוכא וכמ\"ש וישכם אברהם בבקר שלהיות גלוי בחינת אברהם הוא בבקר אחר חשכת הלילה דוקא (כי הנה מ\"ת היה גלוי שם הוי\"ה וכמ\"ש ושמי הוי\"ה לא נודעתי להם רק במ\"ת נאמר אנכי הוי\"ה כו' אך לע\"ל כתיב והיה הוי' לי לאלקים שיהיה גלוי ממקום עליון יותר עד דשם הוי' יהיה חשוב רק כאלקים כמ\"ש במ\"א וזהו עיקר ענין גלוי שמו הגדול וכנודע דבי\"ג מדה\"ר נאמר הוי\"ה הוי\"ה ופסיק טעמא כו'. כי שם הוי\"ה הראשון הוא מה שלמעלה מהשתלשלות ומשם יהיה הגילוי כו' ע\"כ מתעכב זמן רב והחשך גדול יותר כי יהיה אח\"כ אור גדול יותר וזהו בית יעקב לכו ונלכה באור הוי\"ה פי' באור המאיר בשם הוי\"ה כמ\"ש באד\"ר )(דק\"ל) וזהו ענין שמע ישראל הוי\"ה כו' ישראל דייקא. בשכמל\"ו יעקב אמרו והוא ענין יחודא עילאה ויחודא תתאה למהוי אחד באחד כו':"],[68,"<b>וביאור<\/b> הענין דלכאורה אינו מובן דאם ירידת יעקב למצרים הוא ענין המשכת הארת ח\"ע בעלמין סתימין ועלמין דאתגליין כנ\"ל. א\"כ תמוה איך נק' זה בשם גלות מצרים והלא כך צ\"ל סדר השתלשלו' והתהוות העולמות כמ\"ש כלם בחכמה עשית והיינו ע\"י עשרה מאמרות כנ\"ל."],[68,"ואם כך הוא סדר הבריאה מה ענין זה לגלות ושעבוד. אך הענין כמ\"ש במ\"א ע\"פ אני ישנה שהגלות נמשל לשינה כי ענין השינה היא שסותם עיניו ואינו רואה כלום. כך בגלות כתי' אותותנו לא ראינו פי' אותותנו הוא בחי' אותיות התורה והתפלה שהם בחי' המשכות מסוכ\"ע בממכ\"ע אכן בגלות אין התגלות אור א\"ס לעינינו רק האותיות הם מסותרים נעלמים אבל ולבי ער כי למעלה יש כל התגלות האורות. משא\"כ בזמן בהמ\"ק הי' התגלות שכינה למטה ממש והי' יורד אש שלמעלה לאכול הקרבן כו'. אבל בגלות העלמין מסתירים."],[68,"וזהו הבאים מצרימה שמלובשים השמות בהעלמין בבחי' הסתר והעלם כו' ולכן נק' שינה שהגלוי אינו לעינינו. רק למעלה ולבי ער ולכן בגלות ג\"כ נראה עולם כמנהגו נוהג. אך באמת הוא עושה נפלאות גדולות לבדו שהוא לבדו מכיר בהן הגם שאין נראה לעינינו:"],[68,"<b>ועוי\"ל<\/b> דודאי אילו הי' הגלוי בהעלמין מבחי' ח\"ע לא היו העלמין מסתירין ומעלימין כ\"כ לעינינו. והראיה לזה בהתנוצצו' הגאולה ע\"י מרבע\"ה שהוא מבחי' הארת ח\"ע מיד נעשו אותות ומופתים לעין כל בשינוי הטבע כו' ומשום שהדבור בטל לגבי ח\"ע מקורו וע\"ד מאמר מי שאמר לשמן וידלוק כו'. אך היינו בגילוי הארת ח\"ע ממש שזהו הנק' בחי' ישראל משא\"כ בגלות אז אין הגלוי בהעלמין מבחי' הח\"ע ממש שהוא מבחי' הנק' ישראל לי ראש. רק שנמשך בקיעת איזה הארה דרך מסך ולבוש ובחי' זו נק' יעקב ומבחי' זו מאיר בהעלמין להחיותם מאין ליש ולכן העלמין הן מסתירין ומעלימין על הארה זו ולא נודעה כי באה אל קרבנה ועל כן אותותנו לא ראינו לא ראינו דייקא שבאמת גם עכשיו הכל בהשגחה פרטי' כמו בזמן ההוא."],[68,"והכל כמו אותות ומופתי' ההם רק שלא ראינו שאין ניכר שום שינוי. והוא ע\"ד לעושה נפלאות גדולות לבדו שאין בעל הנס מכיר בניסו מפני שהעלמין מעלימין וזהו בחי' הגלות ממש. והסיבה לזה הוא מפני שאין הגלוי בהעלמין רק מבחי' בני ישראל ובחי' יעקב ולא בחי' ישראל שהוא ח\"ע ממש."],[68,"והדוגמא לזה כמו עד\"מ באיזו השכלה הנה מי שמשיג עומק המושכל לאמתתו יוכל להלבישה בכמה מיני אותיו' אם באותיו' אלו או בדבורי' אחרים כפי שצריך לו כך יוכל לשנות הצירופי'. משא\"כ מי שאינו משיג לעומקה ממש אע\"פ שמשיג ענינה לא יוכל לשנות הצירופים כלל רק יגידה בצירופי' שקיבל."],[68,"וכמו עד\"מ היודע לשון המשנה אלו כשירות בבהמה כו' לא יוכל לומרה בצירופי' אחרים רק יחזיר הלשון כמו שהוא ממש בלי תוס' ומגרעת אבל מי שיודע ⟦נ,ד⟧פנימי' ותוך המכוון יוכל לומר דיני המשנה בלשונות ודבורים אחרים כו' וזהו שאנו אומרים יהא שמיה רבא מברך לעלם ולעלמי עלמיא. פי' שהבקשה שיהי' הגלוי בהעלמין מבחי' שמו הגדול ממש ועי\"ז לא יסתירו העלמין כלל. ועמ\"ש בפ' חקת ע\"פ על כן יאמרו המושלים כו' ונחשב חשבונו של עולם:"],[68,"<b>ושרש<\/b> הדברים הוא כי הנה יש ישראל סבא וישראל זוטא. פי' כי ישראל לי ראש הוא בחי' חכמה אך עצמיות ח\"ע חכים ולא בחכמה ידיעא א\"א להשיג כי הוא כמו שהוא ית' לבדו הוא גם אילו לא ברא העולמות. רק בחי' נה\"י דאבא מאירים להיות מקור לעולמות ונעשים מוחין לז\"א."],[68,"וענין נה\"י הוא עד\"מ כליות יועצות איך להשפיע. ע' באגה\"ק ד\"ה להבין משל ומליצה. ובחי' נה\"י דאבא נק' ישראל סבא. ופי' בני ישראל הבאים מצרימה היינו המשכות מבחי' חכמה הנ\"ל שנק' יש\"ס באותיות המחשבה ולכן יעקב שהוא מבחי' אחוריים דאבא המתלבש בתבונה נק' בן לישראל זה שהוא יש\"ס נה\"י דאבא."],[68,"וז\"ש בפ' ויגש ואלה שמות בנ\"י כו' יעקב ובניו שיעקב עצמו בכלל בני ישראל יכונה משום דהתם מיירי בענין ההמשכה מבחי' יש\"ס הנמשך באותיות המחשבה וע\"כ לגבי בחי' יש\"ס נקרא יעקב בני ישראל כו' והיא הירידה הראשונה דמצרימה היינו בבחי' אותיות המחשבה שנק' ג\"כ מצרימה שהם בחי' אותיות וכלים המגבילים האור כו' והירידה הב' הוא באותיות הדבור."],[68,"והוא מ\"ש בפ' שמות פעם ב' ואלה שמות בנ\"י הבאים מצרימה והדבור מקבל מבחי' ישראל זוטא. כי הנה ישראל זוטא היינו בחי' ז\"א כי הגם שז\"א היינו ו\"ק דאצי' חג\"ת נה\"י. אך כשהמוחין דאו\"א נתלבשו בו נק' ישראל לי ראש כי יש הפרש גדול בין כשהמוחין מאירים במדות או כשהם רק מדות לבד. עד\"מ למטה התינוק נוח לכעוס משא\"כ מי שמדותיו בהשכל קשה לכעוס. ולכך אומרים אב הרחמן שבחי' חכמה מקור הרחמים (ועמש\"ל ע\"פ השמים כסאי בפירוש צדקה תרומ' כו' וזהו מי כעמך ישראל גוי אחד כו') ולכן כשהמוחין מאירי' בז\"א נק' ישראל אך מ\"מ ישראל זוטא כי הוא רק המשכ' מוחין במדו'. משא\"כ ישראל סבא זהו נה\"י דאבא עצמו עד\"מ השכל עצמו. והנה מבחי' ישראל זוטא שהוא ז\"א נמשך בבחי' אותיות הדבור כמשל הדבור שמקבל מהבל הלב שבו משכן המדות."],[68,"וזהו ענין ואלה שמות בנ\"י הנאמר בפ' שמות דקאי על ירידה הב' שהיא המשכת ז\"א באותיות הדבור וע\"כ בחי' יעקב לא נק' בני ישראל כי יעקב שהוא בחי' אחוריים דאבא אינו בן לישראל זוטא אלא אח עד\"מ. וז\"ש בנ\"י הבאים מצרימה את יעקב שהדבור מקבל מבחי' בני ישראל זוטא וגם מבחי' יעקב כו':"],[69,"<b>קול דודי הנה זה בא מדלג על ההרים מקפץ על הגבעות.<\/b> שדילג קץ הישועה מת\"ל לרד\"ו שנה. ולהבין ענין הגאולה ברוחניות כענין שכתוב הושיעה לו ימינו. וכתיב צדיק ונושע. וצריך להבין תחלה ענין הגלות וירידה צורך עלייה כמ\"ש אנכי ארד עמך מצרימה ואנכי אעלך גם עלה."],[69,"וכתיב וזה לך האות כי אנכי שלחתיך בהוציאך את העם ממצרים תעבדון את האלקים על ההר הזה דהיינו על הר סיני בשעת מ\"ת שהי' גילוי אלהותו ית' פנים אל פנים. ולהבין זה צריך להבין פי' הפסוק אנכי ארד עמך מצרימה שלכאורה אינו מובן שלשון זה לא שייך כ\"א בלשון בנ\"א שמתחלה לא היה במקום ההוא ועכשיו יורד לשם משא\"כ אצלו ית' הלא כתיב את השמים ואת הארץ אני מלא וגו'. אך הענין דהנה ארז\"ל מזכירין יצי\"מ בלילות ⟦נא,א⟧פי' בכל הגליות ושעבוד הדומות ללילות שכל בחי' הגלות הוא בחי' גלות מצרים."],[69,"וכן ענין הגאולה כתיב כימי צאתך מאמ\"צ אראנו נפלאות וכמו שהיה גלות מצרים בעבודה קשה בחומר ובלבנים וגו'. כך בכל בחי' גלות אף שאין דוגמתן ממש בגשמיות מ\"מ יש בחי' עבודה קשה בחומר ובלבנים ברוחניות. וכמ\"ש בר\"מ בחומר דא קל וחומר. ובלבנים דא לבון הלכתא. ובכל עבודה בשדה דא ברייתא:"],[69,"<b>ולהבין<\/b> זה הנה דרשו בהגדה שמררו חיי אבותינו במצרים. פי' כי האבות הן המדות אהוי\"ר ורחמנות וחיותם הם המוחין שהן החו\"ב בגדלות ה' לדעת כי אין עוד מלבדו בשמים ממעל ועל הארץ מתחת למעלה עד אין קץ ולמטה [עד] אין תכלית ולד' סטרין. שבהשכלה והבנה זו נולדה ונתעוררה מדת האהבה בקרב כל א' ואחד."],[69,"וכן היראה כי כל ניצוץ מישראל יש בו בחי' אהבה ויראה והן הן עצמות הנשמה כמ\"ש במ\"א. וכן כנס\"י חבור כל הנשמות נק' בת נדיב בתו של אברהם אבינו שנק' נדיב מפני שהוא איש חסד המתנדב חסד לכל העולמות עליונים ותחתונים ונק' אבינו וירושתנו ממנו. רק מפני שהבחירה ביד אדם ויכול' בידו להפוך האהבה מאהבת ה' אל ההפוך לגמרי ע\"כ צריך הוא לעורר את האהבה לה'."],[69,"וע\"ז מיוסד כל ענין שיר השירים אם תעירו ואם תעוררו כו'. והתעוררות האהבה היא ע\"י קול דודי דופק וגו'. וזהו שארז\"ל אנשי יריחו היו כורכין את שמע ולא היו מפסיקין בין אחד לואהבת כי מן התבוננות באחד אמת כי אין עוד מלבדו ממילא נמשך התעוררות אהבה לה' בלי הפסק וע\"כ מסיימין בק\"ש אמת ויציב יציב הוא תרגומו של אמת אלא שאומרים גם בלשון תרגום לומר שהוא אחד אמת בין בגשמיות בין ברוחניות כי אין עוד מלבדו כתיב. אך כ\"ז הוא בהיות החו\"ב בגדולת ה' בהתבוננות גדול במוחו ומחשבתו ועי\"כ יכול הוא לעורר מדותיו אוי\"ר בהתגלות לבו ע\"י עומק המחשבה בלבד. אבל מי שמוחו קטן מהכיל התגלות אלהותו במחשבתו לעורר את האהבה הנה זאת עצתו אמונה לצעוק אל ה' בתפלה וכמ\"ש צעק לבם כי הקול מעורר הכונה והתגלות לעורר את האהבה בהתגלות לבו ונק' בחי' זו בחי' מצרים מצר ים החכמה שירדה ונתלבשה במצר הגרון."],[69,"וזהו ענין ויצא יעקב מבאר שבע וילך חרנה. כי בחי' גרון וחרון הכל אחד כידוע לי\"ח. וזהו ענין המרירות שמררו חיי אבותינו במצרים שחיות המדות ירדו ונתלבשו במצר הגרון. ועי\"ז נעשו מרים כי אלו היו בבחי' באר שבע היו מתוקים ויותר טובים."],[69,"וזהו אנכי ארד עמך וכו'. פי' אנכי מי שאנכי בחי' סוכ\"ע בחי' אחד אמת ארד עמך שהוא בחי' ירידה כביכול מחמת שאין גלוי אלהותו ית' מתגלה כ\"כ כ\"א בבחי' מצרים והיינו ע\"י שהוא עמך כמ\"ש גלו לאדום שכינה עמהם ולא נשאר כ\"א בחי' האמונה הנטועה בלב כל ישראל שהם מאמינים בני מאמינים אפי' בגלות כמ\"ש ויאמן העם אבל אינו דומה שמיעה לראיה שהיא בחי' גלוי אלהותו כמו שהיה בשעת מתן תורה בבחי' ראיה ממש ובזמן הגלות אין בחי' ראיה ממש בהתגלות זו אלא בבחי' מצרים שהוא ע\"י הקול בחי' גרון הנ\"ל:"],[69,"<b>והנה<\/b> גם לזה יש רבות מחשבות הטורדות ומבלבלות התפלה. והן המה עונותיו המבדילין. ועצה היעוצה לזה הוא לעורר רחמים רבים ולא על עצמו כי אדרבה בזה הוא מעורר עליו את הדין שדנין אותו אם הוא ראוי להתפלל לפני ה' ולעבוד אותו אלא שישוב אל ה' וירחמהו ברחמים רבים על גלות השכינה שהיא ניצוץ אלהותו המתלבש במחשבתו."],[69,"והמ\"ז הם נקראו לבושים צואים. וע\"ז יתמרמר מאד במר נפשו ועי\"ז יסורו הבגדים הצואים מעליו ונגלה ⟦נא,ב⟧כבוד ה' כמ\"ש זרח בחשך אור לישרים. וכתיב וכבוד ה' עליך זרח. לעורר את האהבה."],[69,"וזה שכתוב כה אמר ה' ליעקב אשר פדה את אברהם כי ע\"י מדת יעקב בחי' רחמנות הוא מעורר את האהבה בחי' אברהם. וז\"ש וימררו את חייהם. פי' וביאור הכתוב כי הנה הכתוב אומר איך שע\"י גלות מצרים צריך הוא לשית עצות בנפשו לצעוק אל ה' בתפלה ולהתמרמר במר נפשו על חייו דהיינו על חיות אלהות שבתוכו שהוא חיות העיקרית של האדם. משא\"כ חיי עוה\"ז אינם נקראים חיים כלל."],[69,"וזהו בעבודה קשה. כי עבודה שבלב זו תפלה לצעוק אל ה' בבחי' צעק לבם בשביל גילוי אלהותו ית' כמ\"ש רוממות אל בגרונם שהוא התגלותו ית' ע\"י בחי' הגרון הנ\"ל. ועי\"ז וחרב פיפיות בידם להכרית כל הקליפות ותאוות שיש לאדם."],[69,"והנה כמו למשל חרב שהיא של ברזל קשה יכולה לעמוד אפי' בפני דבר קשה כאבנים ולא תפגום בהכאתו בהם. משא\"כ אם היה הברזל רך. כך התפלה צריכה להיות קשה. ולכן נק' עבודה קשה דהיינו לקרוא לה' לעמוד נגד כל מונע מבית ומבחוץ ולשבר כל הקליפות ותאוות החזקות להיות לבו נשבר בקרבו. ואפילו אם הוא כלב האבן ימוס. והנה כ\"ז הטורח הוא בשביל הגלות משא\"כ כשהיה בית המקדש קיים שלא היו צריכין לתפלה כי אז היה התגלות אלהותו במוחו ומחשבתו של אדם בהתרחבות (להאיר) [להעיר] את האהבה מקרב איש ולב עמוק בעומק המחשבה בלבד:"],[69,"<b>וכן<\/b> בענין התורה בזמן הגלות הוא בחומר ולבנים וגו'. וכמ\"ש בר\"מ. והענין הוא דכתיב ששים המה מלכות ושמונים פלגשים ועלמות אין מספר אחת היא יונתי תמתי. ופי' בזוהר ששים המה מלכות אלו ששים מסכתות."],[69,"ושמונים פלגשים אלו ברייתות. ועלמות אין מספר אלו ההלכות. אחת היא יונתי תמתי וגו'. ופי' תמתי שלימתי שאין שלימות אצלו כביכול זולת כנס\"י כמ\"ש והארץ הדום רגלי. וכתיב בנים אתם להוי' אלקיכם וברא כרעא דאבוה הוא."],[69,"והיינו מפני גילוי יחודו ית' בעולמות עליונים הוא בכל צבא מעלה כמ\"ש וצבא השמים לך משתחוים שבטלים אליו במציאות בפועל ממש. אך בעולמות התחתונים הנה עכו\"ם המורדים ופושעים בו רק מי כעמך ישראל גוי אחד בארץ ליחד לבבם לאחד ולבטל רצונם מפני רצונו."],[69,"והוא כמו למשל אברי האדם שבטלים אליו ואפילו הרגלים שהוא לבר מן גופא ואפי' צפורני רגלו והיינו כל זמן שדבוקים בו. אבל כשנפרד אחד מאבריו. וכן צפורן הפורש מן האדם שוב אינו נחשב מכלל האדם מפני שאינו בטל אליו."],[69,"וכך בנפש האדם כתיב לתאוה יבקש נפרד שנפרד מיחודו ית' והוא כמו אבר הפורש מן האדם והרי זה כאלו נקטע אחד מאבריו או נקצץ צפורן אחד מן הקומה שלימה של יוצר בראשית כביכול. אבל הבא לדבקה בו באמת הוא בטל לגמרי אליו ואין לו רצונות אחרים כלל כמו שכתוב מי לי בשמים ועמך לא חפצתי בארץ כו'. צור לבבי וחלקי וגו'. ועושה הקומה שלימה כביכול ולכן נק' תמתי."],[69,"והנה באתדל\"ת אתדל\"ע כמ\"ש אני לדודי ועלי תשוקתו כי כמו שמעורר התשוקה בחדות ה' לעשות נחת רוח ליוצרו בשמחה כמ\"ש ישמח ישראל בעשיו כך חדות ה' היא מעוזו וישמח ה' במעשיו."],[69,"וזהו ובלבנים דא לבון הלכתא כי הנה כתיב שחורה אני ונאוה פי' כי התורה שבע\"פ היא נראית לעין כל בבחי' שחורה שאין נראה בה שום אור כלל לפי שמדברת בעניני עולם הגשמי בעניני זרעים ובדבר שבממון בין איש לרעהו. אבל באמת ונאוה שכל הדברים שבה יסודתם בהררי קדש מחכמה עלאה שכך עלה ברצונו וחכמתו ⟦נא,ג⟧ית' חכים ולא בחכמה ידיעא כו'."],[69,"וזהו לבון הלכתא שההלכות הנראות כשחורות צריך ללבנם בלובן העליון ע\"י חדות ה' היא השמחה אמתית בה' אחד ולהבטל ברצונו ולא יבקש רצון אחר זולת רצונו ית' המלובש בתורתו. וזהו קומי לך רעיתי יפתי ולכי לך. פי' לך לעצמך כי ישראל עלו במחשבה תחלה וע\"כ קומי לך להתכלל באחד."],[69,"והנה עד\"ז מתעורר למעלה בחינת לובן העליון בהתגלות בבחי' הארת פנים. דהיינו התעוררות השמחה וחדות ה' צהבו פניו. כמ\"ש יאר פניו אתנו סלה שהארת פניו היא אתנו ועל ידינו כפי מה שאנו מעוררים בחי' התגלות אלהותו כמ\"ש כמים הפנים לפנים כו'."],[69,"והנה תכלית ושלימות הגילוי הזה יהיה לעתיד לבא לימות המשיח שאז עין בעין יראו כבשעת מ\"ת ויותר מזה שאילו בשעת מ\"ת לא היה רק לפי שעה משא\"כ לימות המשיח יהיה גילוי אלהותו לעד ולעולמי עולמים בלי הפסק. וזהו סלה שהוא לשון נצח. והנה בזמן הגלות צריך עמל ויגיעה רבה לקבוע בלבו השמחה אמתית בה' שהוא לבון הלכתא משא\"כ לימות המשיח אז וראו כל בשר יחדו:"],[69,"<b>וכן<\/b> בענין ובכל עבודה בשדה דא ברייתא. כי ברייתא בחי' לבר מן גופא שהם אברים החצוניים. והמשנה נק' אברים הפנימיים. וכל דבר שהוא שנוי בברייתא הוא מרומז במשנה כמו שאמר אילפא מאן דשאיל לי בברייתא ולא פשטינא ליה ממתניתין. פי' פשטינא מלשון פשט את ידו שהוא לשון הושטת יד ואמר שיושיט את ידו ממתניתין לבאר הדין השנוי בברייתא ולא היה צריך ללמוד הברייתא בפ\"ע כיון שהיא נכללת במתניתין. אך לא כל אדם זוכה לזה ושמו מוכיח עליו שלכן נק' אילפא מלשון אאלפך חכמה אאלפך בינה ולכן היה מבין דין הברייתא מתוך המשנה. אבל אנחנו צריכין ג\"כ לעסוק בדין הברייתא מתוך המשנה."],[69,"וזהו ובכל עבודה בשדה. וזהו כמו למשל שמביא חטים מתוך הבית וזורעי' בשדה מחוץ לעיר כך העוסקים בברייתא בדין השנוי במתניתין. והנה תכלית ירידה והגלות היא צורך עלייה גדולה שיאיר אור ה' בגילוי רב לימות המשיח:"],[69,"<b>וזהו<\/b> קול דודי הנה זה בא מדלג על כו'. פי' מלמעלמ\"ט. על ההרים. פי' כאדם שקופץ מהר להר ועי\"כ הולך הרבה ביחד כך הנה ההרים העליונים הם בחי' חסד דאצי' שהוא חסד ה' ממש בגילוי רב ועצום ואתעדל\"ע הוא ע\"י אתעדל\"ת אע\"פ שיש הרבה מדרגות בנתיים. מקפץ על הגבעות. פי' גבעות הם האמהות בחי' מקבלים מן ההרים. דהיינו אפי' מי שאין לו בחי' האהבה מצד עצמו אך מפני שרואה ושומע תפלות אחרים מתעורר בו ג\"כ. והנה ארז\"ל על ג' דברים העולם עומד על התורה ועל העבודה (זו תפלה) ועל גמ\"ח שהם עצמן תקוני המדות שבין אדם למקום ושבין אדם לחבירו. והנה בענין תורה ותפלה כבר נתבאר בפסוק איך שהוא בחי' הגלות וכמ\"ש לעיל. ובא ג\"כ לפרש בענין תקוני המדות וזה נק' את כל עבודתם אשר עבדו בהם. כי העבודה היא מהם ובהם עצמן לתקן מדותיהם. ולזה צריך טורח עמל ויגיעה גדולה להפך מן ההפוך אל ההפוך ולשנות דרכו וטבעו ונק' עבודה מלשון עורות עבודים שצריך לעבד את המדות שיהיו מתוקנים לה' לבדו:"],[69,"<b>ועצה<\/b> היעוצה לזה מ\"ש בפרך ויש בו ב' פירושים. אחד לשון טורח ומלאכה כבידה. ולא מפני כבדות המלאכה מחמת עצמה אלא כעין שדרשו רז\"ל גבי פרעה בפרך נתן מלאכת נשים לאנשים שהגם שבאמת מלאכת נשים קלה ממלאכת האנשים אעפ\"כ היתה כבידה עליהם מפני שהוצרכו לשנות טבעם ורגילותם."],[69,"וכן ⟦נא,ד⟧בענין תקוני המדות אהוי\"ר שבין אדם למקום. הן בבחי' סור מרע הן בבחי' וע\"ט צריך הוא לשנות רגילותו וטבעו. ופי' הב' הוא לשון פה רך. וזה ישים האדם ללבו כמו כעס וקנאה וגדלות והתרוממות אחד על חבירו. זה הכלל מענה רך ישיב חימה. ולא חימה של חבירו בלבד אלא אף חימה שבו. דהיינו כל המדות רעות שבין אדם לחבירו שיסודם היא בחי' גבורות. והמ\"י:"],[70,"<b>ויאמר ה' אליו מי שם פה לאדם וגו'.<\/b> להבין זה מ\"ש משה לא איש דברים אנכי כי כבד פה כו' ומה שהשיב לו הקב\"ה מי שם פה כו' שהוא כולו מקשה וכי לא ידע משה זאת בתחלה מי השם פה לאדם. הענין יובן ע\"פ הקדמה דהנה איתא בס' התמונה (בהקדמה לתמונה ג' דכ\"ז כ\"ט ל\"א) שזה העולם הוא שמיטה שניה ולפניה הי' ג\"כ שמיטה אחת שהיתה נמשכת ממדת החסד והשמיטה דעכשיו (ר\"ל שית אלפי שני דהוי עלמא וחד חרוב) הוא ממדת הפחד ולכן דרכיה חזקים וקשים ורעים כו'. דהיינו שהי' בה חורבן בית ראשון ושני כו'. משא\"כ בשמיטה הראשונה שהיתה ממדת חסד היתה העבודה באופן אחר וגם התורה הי' באופן אחר יעו\"ש והיו רק טוב וחסד כו' כך דעת ס' התמונה ואחריו נמשכו המקובלים האחרונים לדון מזה שמוכרח להיות עוד חמש שמיטות אחר שמיטה זו כי צ\"ל ז' שמיטות כנגד ז' מדות עליונות כו' (וכמ\"ש שם בסה\"ת) אבל האריז\"ל פליג ע\"ז במה שלמדו שצ\"ל עוד ה' שמיטות וגם בענין מה שעוה\"ז הוא שמיטה שניה עם היות דס\"ל ג\"כ כן. ולכן פתחה התורה בבי\"ת בראשית לומר שכבר היתה שמיטה א' ועכשיו היא שמיטה שני'. אבל פי' האריז\"ל דאין הכונה לומר שהי' עולם גשמי כמו עוה\"ז דעכשיו עם שמים וארץ גשמיים ודצח\"מ כי זה לא הי' רק בשמיטה זו דוקא לבד וענין השמיטה שהיתה לפני זו הוא ענין עולם התהו דהיינו ענין ז' מלכין קדמאין דתהו שמתו שהוא ענין ספירות רוחניי' כנודע וענין שמיטה דעכשיו הוא ענין עולם התקון שנעשה אח\"כ (ועיין בלק\"ת פ' קדושים ובעמ\"ה שער עולם התהו פמ\"ו ד' כ\"ה ע\"א) וכנודע בכהאריז\"ל:"],[70,"<b>והנה<\/b> שתי נשמות משמיטה הראשונה דהיינו מבחי' עולם התהו שלפני עולם התיקון ירדו ונמשכו למטה לשמטה שניה שהוא בחי' התקון והם חנוך ומשה דבחנוך כתי' ויתהלך חנוך את האלקי' לומר שכבר התהלך את האלקי' בשמטה הא' וכן במשה כתי' מן המים משיתהו. דהיינו משמטה ראשונה שהיא היתה מבחי' חסד הנק' מים."],[70,"ומשם משיתהו לשמיטה דעכשיו כו' ועיקר ירידתם לזו השמיטה הוא כדי לתקן העולמות כי הם שרשם גבוהים מאד יען היותם למעלה מבחי' נשמות דשמטה זו דהיינו ששם נמצא הביטול הרבה יותר מאשר נמצא בשמיטה זו ולכן נאמר במשה ונחנו מה."],[70,"והאיש משה ענו מאד כו' וגם ראה שם נשמות גבוהות שלמעלה ממנו כמו חנוך למך כו'. ולכן ירדו לשמטה זו לתקנה ג\"כ. שחנוך הי' קודם דור המבול שהיה העולם בתכלית השפלות כמ\"ש קץ כל בשר בא לפני כו'. ולכן ירד חנוך לזה העולם לתקן אותו שלא יחזור לגמרי לתהו ובהו. רק שיהי' מבול על הארץ לטהר הארץ וישארו נח ובניו קיימי' בתיבה. אבל אם לא הי' חנוך הי' העולם חרב לגמרי ולא הי' נשאר אף נח ובניו. וכן משה ירד לגאול את ישראל ושיהי' מתן תורה על ידו כו':"],[70,"<b>והנה<\/b> ההפרש בין תהו לתקון ידוע בע\"ח שהתהו לא הי' בחי' פרצופים רק העשר ספירות היו בבחי' נקודות ר\"ל נקודת החסד נקודת הגבורה כו'. דהיינו שלא נתחלקה הספי' לפרטי פרטיות ⟦נב,א⟧באורך ורוחב כ\"א היתה נקודה א' בדרך כללי וקיצור מופלג זו חסד וזו גבורה כו' וגם היו הע\"ס זה תחת זה שהיו מפורדים זה מזה שחסד הי' בפ\"ע וגבורה בפ\"ע ולא היו מתכללי' זה מזה (ולכן היו רק נקודות כו' דהא בהא תליא). משא\"כ עולם התקון הוא שנעשו הספי' בבחי' פרצופי' מחכמה נבנה פרצוף אבא ומו\"ק פרצוף ז\"א שהוא שנתחלק' הספי' בהתפשטו' לפרטי פרטיו' טפ\"ט ובכל א' ראש תוך סוף וה\"ח המגדילי' עד שנעשה רמ\"ח איברים כו' וגם נעשה התכללות הספי' זו מזו והמשל לשני בחי' אלו יובן ג\"כ בכחות הנפש שבגוף. שרמ\"ח כחות הנפש מתלבשים ברמ\"ח איברי הגוף. כח הראי' מתלבשת בעין."],[70,"וכח השמיעה באזן. וכח המעשה בידים. וכח ההילוך ברגלים כו'. ובחי' זו הוא ענין התפשטות והתלבשות כחות הנפש בכלים שהן האיברים. ועוד נמצא בחי' אחת הכוללת את כל פרטי הכחות המתחלקי' באיברים הנ\"ל ומקפת עליהם מכל צד מראשו עד רגלו."],[70,"והיינו בחי' המחשבה של האדם כנראה בעליל שכאשר יכוה בצפורן רגלו תרגיש תיכף המחשבה את הכאב וכן כשירצה לנענע רגלו תתנענע תיכף ומיד שיעלה במחשבתו לנענע רגלו שמזה ראי' שהמחשבה ישנה ברגל ג\"כ והיא שם בבחי' מקיף כו'. והנה ענין התלבשות הכחות באיברים הוא משל לבחי' פרצופים דיושר שמתלבשי' בכלים כדוגמת פרצוף מוחין וזרועות כו'. (ובחי' התהו הוא בחי' עיגולים שהם בחי' מקיפים וזהו כמשל המחשבה כו') (ועיין ע\"פ ויאמר מלך מצרים למילדות כו' שנתבאר ענין זה באריכות מענין עגולים ויושר) והנה לפי שביושר דתקון נתחלקו הספירות בפרטיות בבחי' פרצופים לכך נמצא בהם דבר חדש מעלה יתירה אשר לא היתה בעולם התהו בהיותן בבחי' נקודות זת\"ז. והיינו מ\"ש בס\"י נעוץ תחלתן בסופן וסופן בתחלתן. שיש מעלה בסוף מה שאין בראש. שזה לא נמצא בעולם התהו רק בעולם התקון מפני שנעשו בבחי' פרצופים."],[70,"והוא עד\"מ מכחות הנפש שבגוף שהשכל מלובש במוח שבראש שהוא המעולה וראש לכל כחות הנפש ואח\"כ בידים מתלבש כח המעשה לכתוב ולצייר ולעשות כל מלאכת אומן שהוא כח פחות בערך לגבי כח השכל שבמוח ואח\"כ ברגלי' מתלבש הכח היותר נמוך שבמעשה כח ההילוך לבד וכאשר נעריך הכחות בעצמן זה לזה מצד עצם מהותן כמו שהם קודם התלבשות באיברים ודאי ימצא שכח השכל הוא מרומם ונעלה לגמרי בכל מכל כל מכח המעשה שבידים ורגלים כו' כי הוא כח מפנימי' הנפש ונעלה מעלה מן כח ההלוך שהוא רק מחיצונית הנפש. אמנם כשנתלבשו בכלים כח השכל בראש וכח ההילוך ברגלים אזי ימצא מעלה ברגל שאינו בראש שהרי הרגלים מעמידים את הראש ומוליכים אותו ממקום למקום ואין נמצא כח זה בראש כלל. הרי נעוץ תחלתן בסופן וסופן בתחלתן שיש מעלה בהסוף שאינו בהראש כו'. וזה בא דוקא מצד התלבשות הכח בכלי הרגל דוקא:"],[70,"<b>והנמשל<\/b> יובן ההפרש בין עגולים דתהו ליושר דתקון. דשם בתהו היו זה תחת זה ולא היו בבחי' פרצוף. ע\"כ לא הי' נמצא בחי' זו דנעוץ סופן כו'. אבל בתקון שנתלבשו בכלים רבים בבחי' פרצוף אזי נעשה בחי' זו מצד הכלים שיש ברגל מה שאין בראש כו'. וכדוגמא זו דנעוץ סופן בתחלתן שהוא ענין מבלי אשר ימצא ראש וסוף שיש מעלה בסוף מה שאינו בראש יובן ג\"כ במצות (שהם ג\"כ בחי' תקון כמ\"ש זאת התורה אדם) שיש מעלה במצות מעשיות שהם גבוהים בבחי' א' יותר מן התורה (עם היות שהתורה היא בחי' פנימיות והמצות הם בחי' חיצוניות מעשה לבד) שהרי מבטלים מת\"ת לצורך הלויית המת גם מצינו ⟦נב,ב⟧שבשביל הכנסת כלה ביטלו מק\"ש כנז' בינוקא דבלק בריחא דלבושייכו כו' (אף שבק\"ש יש יחודי' עליונים כו') גם ארז\"ל עשה דוחה ל\"ת כמו מילה בצרעת. ושעטנז בציצית. אשר כ\"ז הוא מפני שיש מעלה במעשה שהוא בחי' נה\"י בחי' רגלין מה שלמעלה גם מח\"ע. ולכן גם הדיוט שבישראל המקיים איזו מצוה מעשיית בלי כוונות וסודות רק מפני שכך צוה הקב\"ה יוכל להיות שיהי' זה יקר בעיני השם בבחי' אחת מכמה כוונות והשגות שבצדיקי' כו'. כי יש בחי' מעלה יתירה בבחי' תמכין דאורייתא יותר מעיני העדה כנ\"ל במשל הרגל לגבי הראש כו' (ועד\"ז ארז\"ל גדול העושה צדקה בסתר יותר ממשה רבינו וכמ\"ש במ\"א) וזהו דוקא מצד עולם התקון ששם נעשה בחי' זו דנעוץ סופן כו' והיינו לפי שבתקון הוא רבוי הכלים ומצד הכלים דוקא נמצא בחי' זו כנ\"ל משא\"כ בתהו היו האורות מרובים והכלים מועטים לא הי' בחי' זו כו':"],[70,"<b>והנה<\/b> כבר נתבאר שנשמת משה הי' משמטה א' ונמשכה לעולם התקון והוא הי' מבחי' חכ' שהוא בחי' ראיה. כמ\"ש בו וירא ראשית לו. לכך כשראה משה בבחי' ראי' ממש בכל עולם התקון דאצילות שירד ונמשך בו. מה שנעוץ תחלתן בסופן וסופן בתחלתן שזה הי' בעיניו דבר חדש ממש שהרי לא נמצא זה בעולם התהו כו'. נתפלא מאד ע\"ז ולכן השפיל עצמו נגד הנשמו' דעולם התקון ואמר שלח נא ביד תשלח כו'. כי יש בהם מעלה יתירה יותר ממנו מצד הכלים דתקון שנעוץ סופן כו'. משא\"כ אצלו ששרשו מתהו."],[70,"וז\"ש כי כבד פה וכבד לשון אנכי ר\"ל ששרשו מתהו ששם היו האורות גדולים ולא היו יכולים להתלבש בכלים. וזהו ענין כבד פה שלא הי' יכול להשפיע אור שכלו לתוך כלי הפה."],[70,"וזה הי' בעיניו חסרון גדול ומעלת התקון שהכלים מרובים להכיל האורות נפלאה ויקרה בעיניו ע\"כ אמר שלח נא ביד תשלח דהיינו מי שהוא מעולם התקון כי בתקון נמצא מעלה יתירה מצד דבר שנתחדש שם דנעוץ סופן כו' והיינו דוקא מצד הכלים דתקון כנ\"ל ואין זאת אצלו שהרי הוא כבד פה כו'. זה הי' טענת מרע\"ה שהשפיל א\"ע מאד להיותו עניו מכל האדם כו'. (ובאמת היא מעלה אצלנו מה שהי' כבד פה שהרי סיבה זו הוא מצד רבוי האורות שלכך לא יכלה הכלי להכיל. משא\"כ בתקון הוא מיעוט האורות ורבוי הכלים. וגם זה אמת אלא שעכ\"ז יש מעלה יתירה בתקון מצד הכלים כנ\"ל בענין נעוץ סופן כו'):"],[70,"<b>והנה<\/b> השי\"ת השיב לו מי שם פה לאדם הלא אנכי הוי\"ה. פי' אמת אתה אומר שאתה כבד פה שאין לך כלים כאלו הנמצאים בתקון שנעוץ תחלתן בסופן ומצד שרש נשמתך אתה כבד פה שאין השכל יוכל להתלבש בכלי הפה כו'. אך מי שם פה ל(אדם בניקוד קמ\"ץ רומז על האדם הידוע היינו בחי' אדם דאצי' שעל הכסא שהוא שם מ\"ה בגימט' אדם שהוא כללות התקון כנודע וענין כלי הפה הוא הממשיך אור מקיף כמ\"ש בפע\"ח שע\"י הברכה של המצוה נמשך בחי' המקיף וע\"י המצוה עצמה נמשך האור פנימי )(כי הבל הפה נעשה בחי' או\"מ וע' בתניא פ\"ה) ולכן בתש\"ר נחלקו הספרדים והאשכנזים אם יברכו עלי' ברכה מיוחדת מפני שהמקיף דתש\"ר גבוה מאד ע\"כ מנהג ספרד שלא לברך דס\"ל שא\"א להמשיך המקיף ההוא כו'. והאשכנזים ס\"ל דיכולים להמשיך. עכ\"פ למדנו דכלי הפה הוא הממשיך הא\"מ כו'."],[70,"וז\"ש מי שם פה לאדם כלומר מי האציל כלי הפה שהוא כלי שממשיך או\"מ מי האצילו לאדם דתקון. הלא אנכי הוי\"ה בחי' עצמות אא\"ס שרש הקו וחוט דאור א\"ס ב\"ה המקור לכל או\"פ ומקיפים כו'."],[70,"וא\"כ ⟦נב,ג⟧ממני לא יבצר מאומה ואנכי אהיה עם פיך ג\"כ פי' אף שמצד שרשך מתהו אין לך כלים כאלו אבל אנכי הוי\"ה שעשיתי את הכלים דתקון ואת עולם התהו אני יכול להפך הדבר להתערב בחי' תהו ותיקון יחד היינו המעלות דשניהם שיהיו האורות מרובים כמו בתהו כו'."],[70,"וגם בחי' המעלה דתקון שיהיו הכלים מרובים מאד. ואז יהיה נעוץ תחלתן כו' וזהו ואנכי אהיה עם פיך שהגם ששרשך מתהו עכ\"ז יהיו לך כלים דתקון ובפרט כלי הפה שע\"י נמשכו האורות מקיפים כו'. ויהיה א\"כ בך שני המעלות. והיינו מפני שכמו שנעוץ תחלתן בסופן כך נעוץ סופן בתחלתן לכך יוכל להיות נמצא מעלת התקון אף בתהו כו' לכך יתחברו יחד כו'. (ועמ\"ש במ\"א ע\"פ ארוממך כי דליתני איך דוד שהוא בחי' דבור היה כלול באדה\"ר בחי' חכמה כו' והוא כענין כבד פה וגילוי בחינת הדבור בחינת דוד זהו ענין מי שם פה לאדם הלא אנכי זהו בחינת ארוממך עומק רום כו' ע\"ש וכדוגמא זו היא מ\"ש במ\"א מעלת מצות דרבנן כי הנה רמ\"ח מ\"ע רמ\"ח איברים היינו המשכת אורות בכלים משא\"כ שס\"ה ל\"ת שס\"ה גידים הם בחינת אורות שלמעלה מהתלבשות בכלים ואיברים לכן אין בל\"ת קום ועשה והיינו כענין אורות דתהו שלמעלה מאורות דתקון לכן אי אפשר לכלים להכילם אבל במצות דרבנן שהם ג\"כ מבחי' זו דל\"ת ומ\"מ מתלבשים בקום ועשה בכלים לפי שבינה יתירה כו' וכך נאמר למשה אנכי אהיה עם פיך שגם אורות שמבחי' תהו יתלבשו בכלים דתקון כנ\"ל. וע' לקמן ע\"פ זה שמי):"],[71,"<b>זה שמי לעולם וזה זכרי לדר דר.<\/b> איתא בת\"ז שמי עם י\"ה שס\"ה זכרי עם ו\"ה רמ\"ח. וצ\"ל מפני מה שרש מל\"ת גבוה יותר משרש המ\"ע שהל\"ת נמשכי' מבחי' י\"ה דהוי' והמ\"ע נמשכים מבחי' ו\"ה דהוי\"ה. גם י\"ל מפני מה לא ניתנה תושבע\"פ ג\"כ בכתב. הענין הוא דכתיב איה סופר וגו'. ונת' במ\"א הפי' דבחי' אי\"ה עצמו הוא הסופר (והוא בחי' איה מקום כבודו) כי איתא בס\"י בג' דברים ברא הקב\"ה את העולם בסופר וספר וספור. והנה תושב\"כ נק' ספר ובחי' סופר שלמעלה מבחי' ספר הוא בחי' אי\"ה שהוא א' י\"ה כי מקור ושרש י\"ה דשם הוי\"ה נמשך מבחי' האל\"ף שהוא בחי' חכמה דאצילות (ר\"ל מקור ושרש החכמה כמ\"ש במ\"א בכוונת א' דאחד דק\"ש שהוא בחי' מזל נוצר דמשם יונק אבא או ר\"ל חכמה סתימאה) כמ\"ש אאלפך חכמה. ועוד שבאות אל\"ף נכללו בו ג' אותיות דשם הוי' ב\"ה כנודע מהאריז\"ל שתמונת האל\"ף בתושב\"כ הוא י' ו' י' ובתפילין י' ו' ד'. מפני שבתושב\"כ מלובש אור אבא דאצי' כי אורייתא מח\"ע נפקת והיינו מבחי' יסוד אבא לכך נכתב גם הקוץ התחתון של האל\"ף כתמונת י' רמז לחכמה דאצי' שהוא בחי' י' דשם הוי' כנודע. אבל בתפילין נכתב קוץ התחתון של האל\"ף בתמונת ד' שהוא בחי' מחשבה עילאה שהוא בחי' לאה שהוא עד\"מ כמו הד' שיש בו התפשטות לאורך ורוחב."],[71,"וזהו איה סופר. דהיינו שמקור של התושב\"כ שנק' ספר עילאה כמ\"ש בזהר אית ספר ואית ספר. הוא בחי' אי\"ה א' עם י\"ה שהאל\"ף הוא מקור לי\"ה כנ\"ל שהוא הסופר את הספר דהיינו שהוא מקור התושב\"כ שנמשכי' הימנו:"],[71,"<b>דהנה<\/b> כללות התושב\"כ הוא מדבר בענין קיום מצות עשה. שנמשכים מבחי' ו\"ה שהוא בחי' ז\"א דאצי' שהאורות מחולקים בתוך הכלים שהן רמ\"ח אברים דז\"א שמשם נמשכים רמ\"ח מ\"ע ולכך המקיים מ\"ע ממשיך עליו אור עליון דז\"א ולכך ניתנה התורה בכתב להיות האורות דז\"א מתלבשים בכלים ממש ⟦נב,ד⟧לכך נתלבשה חכמת התורה ג\"כ בכתב כו' באותיות ותגין כו' אמנם שרש הל\"ת אף שהן ג\"כ בתושב\"כ מ\"מ הן למעלה ממדרגת המ\"ע אלא שהם נמשכים מבחי' י\"ה. מפני ששרש הל\"ת הוא מבחי' ומדרגה גבוה שאינו יכול להתלבש בתוך כלים כמו המ\"ע שהתפילין והאתרוג הם כלים להאור כו' משא\"כ הל\"ת שאין לאותו האור כלי שיוכל לשכון בו בבחי' הן ע\"י מעשה רק ע\"י לאו ושלילה הוא מושג שאין יכולים להכיר מהותו רק לשלול ההפוך כמו לא תאכל חלב ודם לפי שזהו מנגד לקדושת האור לפי שהיא מבחי' סט\"א."],[71,"וע\"י שלילת ההפוך נמשך גלוי האור אבל א\"א להמשיכו ע\"י מעשה כמו ע\"י תפילין וציצית ע\"ד האורות הנמשכים ע\"י מ\"ע לפי שמעלת האורות הנמשכים ע\"י ל\"ת גדולים וגבוהים יותר מהנמשכים ע\"י מ\"ע וא\"א לעשות להם כלים בבחי' הן רק ע\"י לאו שקדם להן דהיינו ע\"י שלילת ההפוך. וזהו בארץ לא זרועה וזהו שהל\"ת נמשכים מבחינת י\"ה שלמעלה מו\"ה:"],[71,"<b>והנה<\/b> כל דברי סופרים הוא הכל עד\"ז של הל\"ת שהרי ד\"ס הם לעשות סייג לתורה עשו משמרת למשמרתי כו' לכך נקרא דברי סופרים ששרשם מבחי' סופר שהוא בחי' אי\"ה סופר שהוא ענין א' י\"ה כנ\"ל שהל\"ת נמשכים מי\"ה. וכמו\"כ כל ד\"ס נמשכים משם לכן הם למעלה מתושב\"כ שנק' ספר דרמ\"ח מ\"ע נמשכים מו\"ה שהם מתלבשים בכלים. משא\"כ ד\"ס הם מבחי' שלמעלה מזו לכן לא היה באפשר להתלבש במעשה הכתב אלא בעל פה דוקא כי אבא יסד ברתא שבחי' הדבור נמשך מן הח\"ע שהוא בחי' איה סופר כנ\"ל (וע' מ\"ש ע\"פ שחורה אני ונאוה מענין זה):"],[71,"<b>והנה<\/b> גם בתושב\"כ עצמה ימצאו ענינים אשר לא נכתבו מצד מעלתן הרמה. דהיינו שלפעמים נאמר וידבר ה' אל משה לאמר כך וכך. שנתפרש ונכתב בתורה הצווי והאמירה של הקב\"ה למשה בענין מצוה ההיא."],[71,"ולפעמים לא נכתב רק הצווי של משה לישראל בענין מצוה ההיא ולא נכתב הצווי של הקב\"ה אליו וכמו כל משנה תורה שאמר משה לישראל כמה מצות אשר לא נתפרשו היכן צוהו הש\"י ע\"ז."],[71,"וכה\"ג נמצא הרבה בתורה. וצריך להבין למה לא נכתב הצווי של הקב\"ה. אך הענין כי משה הוא בחי' יסוד אבא ולכן זכה שתנתן התורה על ידו דאורייתא מח\"ע נפקת. ופי' ויאמר או וידבר ה' אל משה. הוא בחי' הדבור וההמשכה מן המאציל אור א\"ס ב\"ה ליסוד אבא ח\"ע בענין המצוה ההיא או ההגדה ההיא."],[71,"וענין וידבר משה אל בנ\"י הוא ההמשכה שנמשך מיסוד אבא גילוי ענין ההוא לישראל. ולכך יש איזו ענינים גבוהים מאד. שלא היה יכול להתלבש בכתב ענין ההמשכה מאור א\"ס ב\"ה בח\"ע בענין ההוא רק נכתב ההמשכה והגלוי מיסוד אבא למטה שזהו ענין וידבר משה כו'. וכמו בענין הארבה שהתרה משה את פרעה כי אם מאן אתה כו' הנני מביא מחר ארבה כו' ולא נאמר הצווי של הקב\"ה בענין ההתראה. והיינו להיות ששרש הארבה גבוה מאד כידוע בענין וארבה את זרעו ואתן לו את יצחק כו' (צ\"ע דאח\"כ נכתב הצווי של הקב\"ה בענין הארבה נטה את ידך וצ\"ל דבענין ההתראה לפרעה לא היה יכול להיות נכתב) ויש ענינים שיוכל להיות נכתב הצווי של הקב\"ה למשה ולא נכתב הצווי של משה לישראל בענין ההוא רק שממילא מובן שמסתמא אמר משה לישראל מאחר שנכתב שאמר השי\"ת למשה כו':"],[71,"<b>להבין<\/b> מארז\"ל ע\"פ כי טובים דודיך מיין. ערבים עלי דברי סופרים יותר מיינה של תורה. וי\"ל לשון עלי והל\"ל לי. הנה כתיב לאהבה את ה' אלקיך כי הוא חייך. פי' כי הוא חייך. ⟦נג,א⟧היינו נתינת טעם."],[71,"וכנודע דכי משמש בארבע לשונות. וכאן הוא משמש בלשון דהא. שהוא נתינת טעם לאהבה את ה' אלקיך מפני שהוא חייך. שהמאציל העליון ב\"ה הוא מקור החיים ומקור התענוגים כמ\"ש כי עמך מקור חיים וגו' וממך הכל כתיב שממנו נמשכו כל החיים והתענוגים הנמצאים בארבעה עולמות אבי\"ע והוא ית' הוא חיי החיים."],[71,"ואי לזאת כשיתבונן האדם בזה יומשך מזה לאהבה את ה' שכמו שאוהב האדם לחיי נפשו כך יאהוב את ה' שהוא חיי החיים כולם וחיי נפשו בפרט. אך אהבה זו שנמשכה מן הטעם כי הוא חייך לא נק' עדיין מס\"נ הנא' בפסוק בכל נפשך ובכל מאדך מאחר שנמשכ' מן הטעם כי הוא חייך ונודע שבחי' טנת\"א הוא בבחי' הנאצלי' טעמים בחכמה כו'. אבל המאציל א\"ס ב\"ה מרומם ונשגב אף מגדר החכמה כמ\"ש כולם בחכמה עשית שהחכמה נחשבת לעשיי' גשמית קמיה ית'. ומזה נמשך בחי' מסירת נפש (שיש בכח בכל א' מישראל מחמת שמלובש בנשמתו הארה מבחי' א\"ס ב\"ה שלמעלה מן החכמה והטעם כו') למסור נפשו באחד בלי טעם ודעת כלל רק מצד אהבה הפשוטה לה' המרומם לבדו ואין ערוך אליו כלל וכמ\"ש אני הוי\"ה לא שניתי כו' בין קודם שנברא העולם ובין אחר שנברא העולם אין בו שום שינוי והתפעלות כלל וענין אהבה זו היינו שאינו רוצה להיות נפרד מיחודו ית' אלא למהוי אחד באחד ממש והיינו ענין בכל נפשך ובכל מאדך למסור נפשו ממש למעלה מן הטעם והדעת והוא ההתקשרות במהותו ועצמותו ית' שלמעלה מעלה מבחי' טנת\"א כנ\"ל:"],[71,"<b>והנה<\/b> אהבה ומס\"נ זו יש בכל א' מישראל בכח אלא שהיא בבחי' העלם והסתר. וכדי להוציאה מההעלם אל הגלוי הוא ע\"י בחינת יינה של תורה דוקא. כמארז\"ל נכנס יין יצא סוד והסוד הגנוז בנפש היא האהבה מסותרת הנ\"ל וע\"י שיכנס בנפשו בחי' יינה של תורה שהוא בחי' קיום התומ\"צ שעי\"ז נמשך התגלות האהבה המסותרת שתצא האהבה אל הגלוי בלב כנס\"י שיהיו בוערים באהבה פשוטה למהוי אחד באחד."],[71,"והנה בשבת מתגלה ג\"כ בחי' האהבה מסותרת בבחי' גלוי. והענין דהנה כתיב ששת ימים עשה ה' את השמים וכו' וביום השביעי שבת. כי בעשרה מאמרות שהם ע\"ס נברא העולם. ובראשית נמי מאמר הוא דהיינו שגם החכמה דאצי' ראשית האצי' הוא ג\"כ בחי' מאמר לבד לגבי מהו\"ע ית' וכנ\"ל בענין כלם בחכמה עשית."],[71,"ובשי\"ב נשפלו החכמה והמדות עליונות שהם הע\"מ לברוא העולם כמו עד\"מ האדם העושה איזה מלאכה שכותב או מצייר איזה ציור אזי משפיל שכלו ומחשבתו לעיין באותו הציור והכתב וכשגמר מחשבתו חוזרים שכלו ומחשבתו למהותן ועצמותן. כך עד\"מ למעלה בשי\"ב נשפלו הע\"ס עליונות להיות בריאת העולם על ידיהן ובשבת שבת וינפש שנתעלו החכמה ומדות למהו\"ע ית' המרומם ונשגב לבדו בבחי' אין ערוך כו' מקור התענוגים."],[71,"ולכן מתגלה בשבת בחי' אהבה מסותרת שהיא מבחי' זו למעלה מבחי' חכמה ובחי' טעמים כו' כנ\"ל. וכ\"ז בא ע\"י שנכנס בנפש האדם בחי' יינה של תורה היינו קיום המצות שבהם מלובש רצון העליון שהוא למעלה מבחי' חכמה כנודע וע\"י גילוי רצה\"ע יתעורר באדם גלוי האהבה מסותרת שהיא בחי' אהבה ורצון שלמעלה מן החכמה והטעם וזהו ענין נכנס יין יצא סוד:"],[71,"<b>ועתה<\/b> יובן ענין ערבים עלי ד\"ס יותר מיינה של תורה. עלי דוקא והיינו כי המצות עצמן נק' יינה של תורה כנ\"ל. ⟦נג,ב⟧והנה הברכות שמברכים על המצות הם מד\"ס."],[71,"והם למעלה מקיום המצות עצמן כמ\"ש בע\"ח שע\"י עצם המצוה נמשך בחי' האו\"פ המתלבש בתוך הכלים ממש וע\"י הברכה שעל המצוה ממשיכים בחי' האור מקיף שהוא למעלה מבחי' האו\"פ שלכך א\"י להתלבש בתוך הכלי וז\"ש רז\"ל כל המצות מברך עליהן עובר לעשייתן לשון עובר הוא ענין מקיף כמו עובר לסוחר."],[71,"וזהו ענין ערבים עלי ד\"ס ולא אמר לי. כי פי' עלי היינו לומר שההמשכה ע\"י הברכה הוא בבחי' מקיף וזהו עלי ולכך ערבים יותר מיינה של תורה שהם רק בחי' או\"פ כו' ונועם ה' והעריבות הנמשך ע\"י הברכה שהוא מד\"ס הוא מבחי' מקיף וזהו ערבים עלי."],[71,"ופי' וענין ל' הברכה בא\"י אמ\"ה אקב\"ו היינו ברוך הוא המשכ' מבחי' ראש ומקור כל ברכה מקור החיים שלמעלה מהשתלשלות. ונמשך ברכה והמשכה זו אל בחי' אתה הוא בחי' עלמא דאתגליא שיהיה בחי' הוי\"ה שהוא כללות ההשתלשלות יו\"ד צמצום ה\"א התפשטות ו' המשכה ה' התפשטות."],[71,"וז\"ש ברכת הוי\"ה היא תעשיר ובאברהם כתיב והיה ברכה שהברכה היא בחי' הוי\"ה ואח\"כ אומרים אמ\"ה שיומשך השפע למטה עד גם בבחי' מלך העולם שהיא בחי' מל' דאצי' שהיא בחי' תחתונה שבאצי' כנודע. אשר הוא בחי' תענוג העליון כמה שכתוב באשרי כי אשרוני בנות. בכדי לקדשנו במצותיו הקב\"ה מניח תפילין כו' שהם מבחי' מהו\"ע ית'."],[71,"ונמצא יש בהברכה בחי' רו\"ש תחלה הוא השוב להמשיך השפע למטה עד בחי' מלך העולם ואח\"כ הרצוא קדשנו במצותיו במהו\"ע להמשיך משם למטה. וז\"ש אשרי איש ירא את ה'. מתחלה בחי' ריחוק שירא לגשת אל הקדש מי אנכי כי באתי עד הלום."],[71,"ואח\"כ במצותיו חפץ מאד. דהיינו אמת שאיני ראוי לכך אך מ\"מ במצותיו חפץ מאד. והטעם שצ\"ל רו\"ש כי כל המשכה מלמעלה צ\"ל ע\"י מטי ולא מטי תחלה בחי' הסתלקות שהוא ענין לא מטי ואח\"כ התפשטות בחי' מטי. ולכן צ\"ל אתעדל\"ת ג\"כ בחי' רו\"ש וזהו ענין ערבים עלי ד\"ס ששרש דברי חז\"ל נמשך מבחי' סופר בחי' איה סופר שהוא למעלה מבחי' יינה של תורה שתושב\"כ נק' ספר כו' וכמש\"ל. ועמ\"ש מענין ברכת המצות בפסוק ועשית בגדי קדש ע\"ש:"],[72,"<b>לבך יהגה אימה איה סופר איה שוקל וגו'.<\/b> איתא בזהר ספרא דצניעותא תקיל במתקלא. והוא ענין קו המדה שהוא המודד ושוקל כל הע\"ס דאצי' בשיעור ומדה כמה יהיה המשכת והתפשטות מדת החסד וכמה יהיה המשכת מדת הגבורה ואיך שיתחלקו בבחי' קוין ימין ושמאל בד' רוחות ומעומ\"ט שהם ו\"ק דז\"א כו' (ולפיכך נקראו הספי' לשון מדות ע\"ש שנמדדו כמ\"ש במ\"א) ומדה זו היא בחי' גבורה וצמצום לצמצם שיהיה ההמשכה בשיעור ומדה כו'. וכ\"ז נעשה ע\"י בחי' קו המדה שהוא הנק' בזהר בוצינא דקרדוניתא דנקיב כו' שהוא ענין גבורה דע\"י המתלבשת במו\"ס וע\"ז אמר הכתוב איה סופר איה שוקל. פי' דהוה ס\"ד כיון שמדה ומשקל זה הוא בחי' גבורה וצמצום לגבי עצמות א\"ס ב\"ה המופשט מגדר גבול ומדה ומגדר התחלקות קוין וספי' כו' אלא סובב הכל בסקירה אחת וקמיה כחשיכה כאורה שוין כנודע. א\"כ הוה ס\"ד דבחי' זו דקו המדה הוא מהות נפרד כו' ע\"כ אמר איה סופר איה שוקל כו' פי' איה הוא בחי' העיגול הגדול בחי' סובב דקמיה כחשיכה כאור' שוין הנה הוא עצמו ממש הוא הסופר והשוקל בבחי' מתקלא וקו המדה הנ\"ל ואין זה מהות בפ\"ע ח\"ו כי ממך הכל כתיב והוא כל יכול להשפיל ⟦נג,ג⟧א\"ע כ\"כ למדוד הספי' בצמצום והתחלקות כו' שמדה וצמצום זה נמשך דוקא מן הסובב העיגול הגדול שנק' אי\"ה (שלהיותו מגביה לשבת לכך יכול להשפיל א\"ע כ\"כ למדוד כל פרטי הבחי' שבהעולמות כו'. וכמ\"ש כי רם ה' ושפל יראה) וכעין מ\"ש ועברתי בארץ מצרים אני ולא מלאך שבבחי' מצרים לא הי' יכול לירד שום מלאך זולת הקב\"ה בכבודו ובעצמו כביכול כמ\"ש במ\"א:"],[72,"<b>והנה<\/b> גם התורה הוא בכלל בחי' הצמצום דקו המדה שהתורה לא קדמה לעולם רק אלפים שנה היינו ב' אלפין אאלפך חכמה אאלפך בינה. אבל א\"ס ב\"ה עצמו רם ונשא לבדו מופשט מגדר צמצום והתחלקו' אין לו תחלה ותכלה לכך התורה שלא קדמה לעולם רק אלפים שנה היא מכלל בחי' הצמצומי' דקו המדה (וכמו שנודע שכל המצות הם בחי' שיעור וצמצום סוכה רק עד כ' אמה. ותפילין מרובעו' דוקא כו' וכה\"ג בכל המצות). אלא שבאמת אי\"ה עצמו הוא הסופר והשוקל כו'. ונא' כאן ג\"פ איה נגד ג\"פ קדוש שקדוש גי' ת\"י שהן ת\"י נימין דאריך ולזאת אומרים המלאכים איה מקום כבודו שאינו מושג שזהו בחי' קדוש שהוא מובדל דלית מחשבה תפיסא ביה (ופי' איה סופר את המגדלי' נת' במ\"א ע\"פ ושדי כמגדלות) וזהו ענין לבך יהגה אימה. דהיינו כשיתבונן המשכיל בענין זה איך שאיה סופר איה שוקל כו' שבחי' איה עצמו הוא הסופר והשוקל ומודד החיות וההתפשטות בכל פרטי פרטיות הנמצאים אזי תפול עליו אימה ופחד בבחי' יראה גדולה עד מאד וזהו לבך יהגה אימה. ואזי לא יהי' עליו יראה חיצוניות פן יחסר לחמו וכה\"ג וכתיב סוף דבר הכל נשמע את האלקי' ירא וגו':"],[73,"<b>הבאים ישרש יעקב יציץ ופרח ישראל.<\/b> הנה צ\"ל השייכות בחי' השרשה לביאת מצרים. הנה כתיב כה אמר ה' בוראך יעקב ויוצרך ישראל כו'. אמר הקב\"ה לעולם מי בראך יעקב בראך וישראל יצרך. שנאמר בוראך יעקב ויוצרך ישראל."],[73,"וצ\"ל מה שביעקב נא' בריאה ובישראל נאמר יצירה. והלא בחי' ישראל הוא גדול מבחי' יעקב כו'. הנה ידוע שיריד' הנשמה לעוה\"ז הוא בשביל היום לעשותם. ותכלית בריאת העולמות נאמר בראשית בשביל ישראל שנקראו ראשי' כמ\"ש קדש ישראל לה' ראשית תבואתה."],[73,"ולהבין מהו השייכות לישראל להיו' ראשית תבואת' וגם מה הוא ענין התבואה למעלה כו'. הנה על המצות נאמר בזהר שהם בחי' לבושין שכ\"א מישראל צריך לקיים כל התרי\"ג מצות לבד מצות המלך שהמלך הוא מוציא כל ישראל וכל המצות מחוייב כ\"א לקיים וצריך להיות בגלגול או בבחי' עיבור בכדי שיהיה לבוש מן כל התרי\"ג מצות וכשחיסר מצוה אחת חיסר לבוש כו'."],[73,"וע\"י מעשה המצות נעשה לבוש בג\"ע התחתון וע\"י כוונת המצות נעשה לבוש בגן עדן העליון ולכן בקש משה ליכנס לארץ לקיים המצות התלויין בה כו'. ובגמ' המשילו מעשה המצות לפירות גבי עגלה ערופה כו' שלא הניחוהו לעשות פירות."],[73,"ופריך בגמ' מאי פירות אילימא בנים א\"ה זקן וסריס לא לבעי עגלה ערופה והתורה לא חילקה. אלא מאי פירות מצות כו'. וכן בלשון הפסוק נאמר זרעו לכם לצדקה כו' אשריכם זורעי על כל מים כו' זורע צדקות כו' הרי נק' מעשה המצות בשם זריעה. ולהבין זאת הנה ארז\"ל נתאוה הקב\"ה להיות לו דירה בתחתונים."],[73,"והנה לכאורה אינו מובן ענין דירה זו דהלא לית אתר פנוי מיניה. וכתיב הלא את השמים ואת הארץ אני מלא כו'. אך הנה יש שני בחי' בחי' ממכ\"ע ובחי' סוכ\"ע. בחי' ממכ\"ע נק' הבחי' המתלבש' בנבראים בגילוי להחיותם ואתה מחיה את כולם ע\"י בחי' אתה אותיות כו'."],[73,"ובחי' סוכ\"ע הוא ג\"כ בכל הנבראים אך הוא בבחי' העלם שאינו מתלבש בבחי' גילוי כו'. ולכן ארז\"ל שחייב אדם לברך מאה ברכות בכל יום. ⟦נג,ד⟧להמשיך מההעלם אל הגילוי."],[73,"וזהו בחי' ברוך בחי' בריכה שהיא מההעלם אל הגילוי ולהיות הבריכה מבחי' העלם להיות הוי' בבחי' גלוי שהוא אותיות הוי\"ה יו\"ד צמצום ה' התפשטות כו'. אך ההמשכה מההעלם אל הגלוי הוא דוקא ע\"י ישראל וכמ\"ש בית ישראל ברכו את ה'. והיינו לפי שיש בכאו\"א מישראל בכח למסור נפשו כו' ולכן נאמר דוקא בית ישראל ברכו כו' וזהו אלקינו דוקא וימי שנותינו שבעים שנה כל שנה שס\"ה ימים הכל הוא בכדי להמשיך ע\"י מאה ברכות הנ\"ל מההעלם אל הגלוי ולעתיד יהיה תכלית הגלוי כי עין בעין יראו כו':"],[73,"<b>והנה<\/b> המאה ברכות הנ\"ל הוא בדבור אך ע\"י מה יהיה ההמשכה מההעלם אל הגלוי הנה הוא ע\"י מעשה המצות וכמשל הזריעה שרוב מיני זריעה הוא זרעוני גינה שאינן נאכלין שהוא רק גרעין שאין בו שום טעם מאכל וכשנזרע הגרעין בארץ ומתלבש בו כח הצומח שבארץ נצמח מזה פרי מאכל הגם שלא היה עצם הגרעין בחי' מאכל כלל."],[73,"וגם זרעוני תבואה הנאכלין אעפ\"כ ע\"י הזריעה נתוסף התבואה כהנה וכהנה וכו'. וכמו\"כ הוא מעשה המצות שירדו ונתלבשו בדברים גשמיים כמו תפלין על קלף גשמי וציצית מצמר גשמי וכדומה בשאר המצות וכשאיש ישראל מניח אותם על ראשו נתהוה בחי' גלוי אלקותו קדש בחכמה והיה כי יביאך בבינה כו' וכמאמר הזוהר טלית פריסו דמלכא כו'."],[73,"וזהו דוקא כשאיש ישראל מניח אותם על ראשו משא\"כ כשמונחים על השולחן לא נתהווה מזה שום גלוי כלל הגם שמצח האדם הוא ג\"כ דבר גשם כמו השולחן וגם כשעכו\"ם מניח אותם לא יצמח מזה ג\"כ שום גלוי כלל והיינו כמשל כח הצומח שבארץ שלא בכל מקום נצמח הפרי ובמדבר אינו נגדל צמחים כלל כמו\"כ דוקא לישראל נאמר כי תהיו אתם לי ארץ חפץ."],[73,"והיינו כידוע שבחי' א\"ס נק' קדוש ומובדל אני הוי' לא שניתי. ואתה הוא קודם שנברא העולם ואתה הוא לאחר שנברא העולם כו'. והכל ירוממוך סלה. ושיוכל להתהוות עולמות הוא רק ע\"י מלכותך מכ\"ע אין מלך בלא עם כו'. ישתבח שמך לעד כו'."],[73,"וכמשל ענין המלך שמהפך מיש לאין להיות הכל בטלים נגדו. וכמו\"כ למעלה אין מלך בלא עם מלשון עוממות שהוא בחי' יש ונפרד להתהוות בבחי' בטול ואין וכמו במלאכים כתיב וצבא השמים לך משתחוים. אך מלאכים הם אינם בבחי' נפרד כ\"כ ודוקא ישראל למטה שהם בתכלית בחי' עוממות ונפרד ושם הוא עיקר בחי' גלוי המלוכה ע\"י בחי' הביטול מיש לאין כו'. (משא\"כ ברא כרעא דאבוה ולא בבחי' מלך) ולכן דוקא תהיו אתם ארץ חפץ ששם עיקר גלוי הרצון והחפץ כו'. וע\"י ישראל דוקא במעשה המצות הגשמיים יוכל להתהוות בחי' צמיחה הנ\"ל. וזהו אשה יראת ה' היא תתהלל שהקב\"ה נק' חתן. וכנס\"י נק' בשם בחי' כלה בחי' אשה יראת ה' שהוא בחי' יראה ובטול. ועי\"ז היא תתהלל שנעשה בחי' הארה וגלוי מלשון בהלו נרו כו':"],[73,"<b>וזהו<\/b> הבאים ישרש יעקב היינו השרשה למטה הוא בחי' המצות שירדו מבחי' רצה\"ע להתלבש בדברים גשמיים הוא בחי' יעקב יו\"ד עקב. בחי' יו\"ד שירדה בבחי' עקב למטה. ועי\"ז יציץ ופרח ישראל להיות בחי' צמיחה מההעלם אל הגילוי כו'."],[73,"וזהו זורע צדקות מצמיח ישועות. ע\"י הזריעה בחי' המצות וצדקה שכ\"א נותן הוא רק לזכותנו כי בודאי הקב\"ה בעצמו היה יכול לפרנסם ואינו אלא רק לזכותנו להיות מצמיח ישועות בחי' צמיחה מההעלם אל הגלוי ע\"י מעשה המצות כנ\"ל."],[73,"וזהו כוונת מאמר דהע\"ה לכל תכלה ראיתי קץ רחבה מצותך מאד. שאין כוונתו על תאוות גשמיים רק על בחי' השגות וכלות הנפש ל' כלתה נפשי כו' שהוא בבחי' קץ וגבול שלכל נשמה יש גבול להשגתה משא\"כ מצותך היא רחבה מאד היינו שבחי' מצותך היא רחבה בבחי' כלי קבול לקבל בחי' מאד בלי גבול שע\"י מעשה המצו' יוכל לצמוח בבחי' ⟦נד,א⟧גלוי בלי גבול."],[73,"וזהו רחבה מצותך מאד. וזהו אשריכם זורעי על כל מים שכל בחי' השגות שבג\"ע העליון וג\"ע התחתון נק' בשם מים כמ\"ש ונהר יצא מעדן כו' משא\"כ מעשה המצות נעשה זריעה על כל מים למעלה מעלה מבחי' מים כנ\"ל."],[73,"וכמו\"כ ע\"י לימוד התורה שירדה ג\"כ להתלבש בענינים גשמיים נעשה ג\"כ מזה בחי' צמיחה ולכן ארז\"ל אשרי מי שבא לכאן ותלמודו בידו. ולכאורה הוא תמוה והלא למעלה אין נצרך שם כלל הדבור גשמי אלו מציאות וכדומה. רק שלהיות בחי' צמיחה הנ\"ל צריך להיות דוקא נשרש ונקלט בארץ ואז יוכל לצמוח. כמו\"כ כשנקלט אצלו בחי' התורה בבחי' קליטה ממש להיות תלמודו בידו דוקא אזי נעשה מזה בחי' צמיחה גלוי רב למעלה הרבה מבחי' ההשגות שבג\"ע ששם הוא רק נהנין מזיו השכינה כו'."],[73,"וזהו ישרש יעקב שהיא ע\"י בחינת שרישה וקליטה בחי' יעקב שהוא בחי' תורה ויקם עדות ביעקב כו' תתן אמת ליעקב כו' ואין אמת אלא תורה כו'. הנה עי\"ז יציץ ופרח ישראל בבחי' גלוי בחי' לי ראש כו' כנודע. וזהו ומלאו פני תבל תנובה. תנובה הוא ענין הפרי גם תנ\"ו ב\"ה (להיות נקלט) בבחי' תבל שהוא בחי' כנ\"י הנק' ארץ חפץ להיות נקלט ונשרש בה בבחי' גלוי הוא ע\"י בחי' יעקב וישראל הנ\"ל:"],[73,"<b>אך<\/b> כדי שיומשך בחי' יעקב וישראל הנ\"ל צ\"ל ג' בחי' שהוא בחי' אברהם יצחק ויעקב כי תפלות אבות תקנום. וזהו ענין התפלה שמבקשים ברוך אתה הוי' מההעלם אל הגילוי כו' כנודע. אך צריך להיות מקודם בחי' מרירות על הריחוק מאלקות בתכלית."],[73,"וכמאמר מים תחתונים בוכין כו'. להתבונן בגדולת ה' ברוך שאמר כו' שבאמירה אחת נתהוו כל העולמות וכו' ושכדאי כל יסורי גיהנם כו' וכמארז\"ל מוטב דלידייניה וליתי לעלמא דאתי להיות נהנין מזיו השכינה."],[73,"ועי\"ז יתמרמר נפשו מאד על ריחוקו בתכלית. אך בכי' תקיעא בלבאי מסטרא דא וחדוה מסטרא דא. היינו שבאמת מצד הגוף הוא רחוק בתכלית. אך מצד נש\"י יש בחי' שמחה רבה לשמוח בה' בשמחה של מצוה שהוא מבחי' מהותו ועצמותו כביכול למעלה מבחי' סוכ\"ע כו'. אך ע\"י מה נתחברו בחי' שני הפכים האלו בתכלית בכיה וחדוה כו'. הנה הוא ע\"י בחי' יעקב שהוא בחי' רחמנות וכמאמר ברחמיך הרבים רחם עלינו וע\"י בחי' רחמנות כנ\"ל יוכל להיות בחי' שמחה של מצוה שהוא בחי' גילוי כו' כנ\"ל."],[73,"וזהו הקל קול יעקב וכמשל הקול שהוא ג\"כ גילוי ההעלם והקול נעשה ע\"י ג' בחי' אש ומים שהם דברים הפכיים ובחי' הרוח הוא הממוצע ומחברו כמו\"כ להיות בחי' גילוי מעשה המצות למטה הוא ג\"כ ע\"י בחי' יעקב בחי' רחמנות כנ\"ל ולכן נק' יעקב בריח התיכון שמבריח מן הקצה העליון אל הקצה התחתון כו' לחבר הקרשים שלא יתפרדו והיו לאחדים כו':"],[73,"<b>וזהו<\/b> הבאים ישרש יעקב. היינו שבכדי שיקבלו ישראל התומ\"צ שהוא בחי' יעקב וישראל כו' ולהיות פב\"פ דבר ה' כו' באו מקודם למצרים שהוא בחי' המרירות כו' בחומר ובלבנים כו'. ואח\"כ קבלו התורה להיות ישרש יעקב יציץ ופרח כו' וזה היה במצרים בכדי לקבל את התורה בגשמיות בבחי' חיצוניות."],[73,"וגם עתה בגלות ושעבוד פרנסה הוא ג\"כ בכדי שלעתיד יוכלו לקבל בחי' פנימיות התורה להיות עין בעין יראו כו'. וזהו בוראך יעקב ויוצרך ישראל כמ\"ש יוצר אור ובורא חשך. היינו שבכל דבר יש בחי' חומר וצורה. ובחי' בריאת החומר שירדה למטה הוא בחי' יעקב ויוצרך הוא בחי' הצורה וגילוי הוא בחי' ישראל כנ\"ל. וזהו ענין מארז\"ל כל שיראת חטאו קודמת לחכמתו חכמתו מתקיימת היינו להיות חכמתו מתקיימת בבחי' צמיחה כנ\"ל צ\"ל מקודם בחי' יראת חטאו כו' וכמבואר למעלה אשה יראת ה' דוקא היא תתהלל כו':"],[74,"⟦נד,ב⟧ביאור על הנ\"ל"],[74,"<b>להבין<\/b> שרש הדברים. הנה ג' קשרי' מתקשרין ישראל באורייתא כו' שמדרגת התורה היא למעלה מישראל והרי התורה נקראת בשם בחי' כלה כמארז\"ל אל תקרי מורשה אלא מאורשה כו' ונק' העוסק בתורה בעל תורה מארי דאורייתא כו' וכתיב קדש ישראל לה' ראשית תבואתה כו' כי התורה נק' בשם בחי' לחם כמ\"ש לכו לחמו בלחמי וגם נקראת בשם יין תבואת הכרם ונק' שמן דזית נמי אקרי תבואה כו'."],[74,"והענין הוא דארז\"ל מן שמיא מיהב יהבי מישקל לא שקלי וגדול הנס האחרון כו'. כי הנס הראשון שנתנו לו זהב מן השמים אינו גדול כ\"כ שכך הוא סדר ההשתלשלות להיות יורד למטה עד שיורד מרוחניות לגשמיות כי אין לך עשב שאין לו מזל והמזל הוא רוחני ונמשך מאין ליש. משא\"כ הנס האחרון להתעלות מיש לאין הוא נפלא ביותר נגד הדרגת ההשתלשלות."],[74,"ובחי' זו אינה אלא בישראל דוקא וכמ\"ש כי תהיו אתם לי ארץ חפץ. פי' חפץ ורצון שלמעלה שיהיה ביטול היש לאין וחפץ זה תהיו אתם לי כו'. דהנה כנס\"י מקור נש\"י נקרא' בשם ארץ שיש בה כח הצומח להצמיח כל פרי למינהו ע\"י אשר זרעו בו על הארץ והנה בהגרעין אין בו טעם ומתיקות אלא הוא כעץ בעלמא וגם בכח הצומח אין בו תמונת הפרי שהרי נצמח ממנו כל פרי לפי הגרעין הנזרע חטה ושעורה וגפן וא\"כ מוכרח שאין בו בחי' חטה דא\"כ לא היה נצרך להזריע אלא שע\"י התאחדות הגרעין שיש בו בהעלם תמונת הפרי עם הארץ עי\"ז מתלבש בו כח הצומח להצמיח בדומה לגרעין."],[74,"וכך הוא הענין המצות שנשתלשלו וירדו למטה עד שנעשה כדמות הגרעין שאין בו טעם כמו ציצית מצמר ותפילין מקלף כו' אך מ\"מ יש בהם ענג העליון וע\"י ישראל העושים ומקיימים המצות נצמח ונגדל ענג העליון להיות בגילוי."],[74,"והיינו לפי שישראל הם בבחי' ארץ בחי' מלכות שכל הי\"ס נמשכים בה שהוא בחי' בטול בחי' אתכפייא ואתהפכא כו'. ואין פי' אתכפייא על רע גמור כי האומר אחטא כו' אין מספיקין בידו כו'. אלא במותר לך כו' שהוא בחי' בטול היש לאין שהוא נעלה מבחי' יש מאין."],[74,"וזהו שרש ומקור נשמות ישראל. ולכן ע\"י קליטת הגרעין דתורה ומצות בנשמות ישראל שיש בהם כח הצומח בחי' נעוץ סופן בתחלתן מלכות דא\"ס נצמח ונגלה הענג העליון שבמצות להיות בגילוי. ולכן נקראת כנ\"י בשם אשה יראת ה' כי בחי' הבטול הוא בחי' היראה ופחד ה' לנגד עיניו."],[74,"והנה עיקר יצירת והתהוות הולד הוא מטפת האב מזריע לובן שממנו עצמות וגידין כו'. אלא שע\"י שהייה בבטן אמו אוכל ממה שאמו אוכלת כו' יוצא מההעלם אל הגילוי בכל אבריו מה שהי' בתחלה בהעלם בטפת האב."],[74,"וכמו\"כ הוא ענין המצות שרשם למעלה הוא רצון העליון וירדו למטה ברבוי ההשתלשלות להיות בבחי' גרעין תר\"ך עמודי אור כמו העמוד שמחבר מעלה ומטה וע\"י הקליטה שנקלטו בישראל שיש בהם כח הצומח נצמח גילוי המצות כמו שהן למעלה."],[74,"וזהו אשה יראת היא תתהלל לשון בהלו נרו כו' הללו י\"ה שטעם אמירת פסוקי דזמרה קודם ק\"ש כי ק\"ש ואהבת הוא מחמת התבוננות בפסוקי דזמרה שהוא ספור שבחיו של מקום יוצר משרתים ואשר משרתיו כו' וצריך להאיר ולהלל התבוננו' בחי' י\"ה מלמעלה."],[74,"וזהו הללו יה ועשרה הללויה להלל מלמעלה מעלה עד רום המעלו' וכך הוא בענין ישראל שנק' אשה יראת ה' שצריכה להתהלל ולהאיר מלמעלה בכדי להיות בהן בחי' קליטה, וכן בענין התורה אשרי מי שבא לכאן ותלמודו בידו הוא ג\"כ על דרך זה כי התורה ג\"כ ירדה מלמעלה למטה להיות בחי' ⟦נד,ג⟧גרעין וכדי להיות בחי' קליטה צריך להיות תלמודו בידו דוקא כנ\"ל:"],[74,"<b>והנה<\/b> כתיב אור זרוע לצדיק שאור תורה ומצות הוא כעת בבחי' זריעה ולעתיד יהי' בבחי' גילוי בבחי' פרי ומלאו פני תבל תנובה כו'. דהנה תחית המתים שיהיה לעתיד הוא ע\"י גילוי בחי' סובב כל עלמין וקמי' כחשיכה כאורה כו'. אך הנה גם כעת הוא בחינת סוכ\"ע. וא\"כ מהו זה התוספת והעילוי שיהי' לעתיד. והענין כי ממלא כל עלמין וסוכ\"ע הם בחי' מקיפים ובחי' פנימיי'."],[74,"והנה יש ב' בחי' מקיפים הא' הוא מה ששייך לפנימי ומאיר בו שהארה זו הוא מחי' אותו והב' הוא מקיף הכללי שמקיף בהשוואה אחת ואינו מאיר בפנימי כלל. וכמארז\"ל אכל בי עשרה שכינתא שריא בבחי' מקיף כו'."],[74,"והנה יש מתפעל כשמתפלל בעשרה או כשרואה שחבירו מתפלל בכוונה מתפעל גם הוא להתפלל יותר מרגילותו שכוונת חבירו בתפלתו אצלו הוא בחי' מקיף ואינו נכנס בו בבחינת פנימית עכ\"ז הוא מתפעל והוא בחי' מקיף המאיר בפנימי."],[74,"ויש שאינו מתפעל כלל והיינו שאין מאיר בו בפנימיות ונשאר בחי' מקיף הכללי שאינו מאיר כלל. וכך יובן הדבר בבחי' סוכ\"ע דעכשיו הוא בחי' מקיף וסובב השייך לפנימי סובב כל עלמין דייקא משא\"כ לעתיד לבא כתיב ונגולו כספר השמים."],[74,"וגם נאמר כאשר השמים החדשים והארץ החדשה וגו' ששמים בחינת מקיפים דכעת יגולו כספר להתלבש בבחי' פנימי ויתגלו מקיפי' ושמים חדשים ואז ע\"י אור הגדול ההוא גם המתים שוכני עפר יחיו לפי שלפניו כחשיכה כאורה וכמשל האור והשלהבת היותר גדולה מאירה למרחוק ביותר. וגילוי ההוא שלעתיד הוא ע\"י המצות שיעשו פרי למעלה וכמשל הוולד הגם שגידולו מן האשה. כמארז\"ל אוכל ממה שאמו אוכלת כו' עכ\"ז אפשר שהולד יהי' גדול במעלה מן האשה שהולד זכר הוא בחי' משפיע ואמו בחי' מקבל בחי' נוקבא כו':"],[74,"<b>וזהו<\/b> שהמצות נקראים לבושים ובחי' פירות שהמצות כעת הם בבחינת גרעין והם בחינת לבושים המעלימים עד שנראה כאלו אין בהם טעם כלל ציצית מצמר כו'. משא\"כ גילוי המצות כמו שיהיו לעתיד יהיו בבחי' פרי גילוי טעם ותענוג וכדפי' רש\"י על פסוק ישקני מנשיקות פיהו שלע\"ל יתגלה לנו טעמי התורה."],[74,"וזהו לכל תכלה ראיתי קץ רחבה מצותך מאד פי' לכל תכלה הוא בחי' השגות נשמות ומלאכים דבריאה יצירה עשייה יש קץ וגבול להשגתם לפי שהן בחי' נבראים ובע\"ג משא\"כ מצותך כמו שהן למעלה היא רחבה מאד רחבה הוא בחי' כלי קבול רחב לקבל בתוכו אור א\"ס בלי גבול ולכן נאמר רחבה ולא אמר ארוכה כמו שנאמר בהתורה ארוכה מארץ מדה והיינו לפי ששם מדבר בענין המשכות וירידות השתלשלות התורה למטה מטה והוא בחי' אורך שמשתלשל ויורד מטה מטה באורך וכאן מדבר במצות כמו שהן למעלה ומצותך דייקא קאמר רחבה כו':"],[74,"<b>וזהו<\/b> קדש ישראל לה' ראשית תבואתה היינו מצד התלבשות התורה למטה בבחי' גרעין הרי מעלת ישראל הוא למעלה מן התורה שהרי בישראל יש כח הצומח ונקראים ראשית תבואתה שהן הראשית שממנו נצמח ונגדל התבואה להיות בגילוי הטעם ותוספת ברבוי כו'. משא\"כ מצד התורה ומצות כמו שהן למעלה התורה מאד נעלה ממדרגת ישראל שישראל מתקשראן באורייתא כו'."],[74,"וזהו הבאים ישרש יעקב יציץ ופרח ישראל שהשרשה והצמיחה הוא בבחינת יעקב יו\"ד עקב בריח התיכון כו'. ועי\"ז יציץ ופרח ישראל לי ראש כו'. דהנה כתיב הקל קול יעקב שהקול מחבר ומביא הרוחניו' להתגשם. דהנה ארז\"ל עינא ולבא תרין סרסורי דחטאה הן כי העין רואה והלב חומד כו' לפי שבעין יש גידין ועורקי המוח ועי\"ז מתפעל במוחו ומשם יורד ג\"כ ⟦נד,ד⟧ע\"י גידים ועורקים ללב ועדיין הוא רוחני חמדת הלב ואח\"כ מהבל הלב יורד ע\"י קנה הלב לקנה הריאה ולריאה ומשם מתחלק ההבל ויוצא דרך ה' מוצאות הפה להיות בגילוי בדבור גשמי ונמצא שהקול הוא מחבר גשמית ברוחנית וגם הנה בקול עצמו יש ג' בחינות אש ומים שהם ב' הפכים ובחינת רוח הוא המחברם."],[74,"וזהו תפלות אבות תקנום כו' ויעקב כלול משניהם כו'. וכמשל הרב המשפיע לתלמידו הנה כשמשפיע השכל כמו שהוא אצלו לא יבין התלמיד כלל. וכן אם ימנע מלהשפיע. ולכך מוכרח להיות בחי' ממוצע הכלול משניהם. וזהו תתן אמת ליעקב ואין אמת אלא תורה שהתורה היא ג\"כ עד\"ז יש בה מצות בבחי' העלאות ובבחי' המשכות. וזהו כה אמר ה' בוראך יעקב כו'. יעקב בראך ישראל יצרך כו'. דהנה כתיב יוצר אור ובורא חשך כו'."],[74,"והנה ידוע שבכל דבר יש חומר וצורה שהחומר הוא עצם הדבר כמו שהוא הוא בחי' יעקב יו\"ד עקב סדר השתלשלות הבריאה יש מאין. והצורה שהוא גילוי האור הוא בחינת ישראל ל\"י רא\"ש וכמשל האבוקה הגדולה שמאירה למרחוק ביותר. וזהו מאמר רז\"ל כל שיראת חטאו קודמת לחכמתו חכמתו מתקיימת שע\"י יראת חטאו שהוא בחי' אתכפיא בחי' ארץ חפץ. הנה ע\"י זה חכמתו מתקיימת שהוא בחי' גילוי כו' וד\"ל:"],[75,"תוספת ביאור"],[75,"<b>וביאור<\/b> הענין דהנה הגרעין אע\"פ שאין בו טעם וריח מ\"מ יש בו כל תמונת וכח הפרי ממש אלא שהוא בקיצור נמרץ ובבחי' העלם כאלו הוא עץ בעלמא. וכן עד\"ז טפת האב יש בה כללות כל הרמ\"ח אברים ממש וכמארז\"ל אב מזריע לובן שממנו עצמות וגידים כו' וכנודע ג\"כ בספרי הטבע רק שירדה בגשמיות מאד בדילוג הערך כגרעין לגבי ערך הפרי אך ע\"י שנזרע הגרעין בארץ ונכלל כחו בכח הצומח וכח הצומח שבארץ זאת פעולתו להוציא לאור כח הפרי שכלול בהגרעין מההעלם אל הגילוי להיות ממנו פרי בטעם וריח ומראה יפה מה שכשהי' זה בהגרעין הי' בהעלם עצום עד שלא היה ניכר ונרגש כלל שום טעם וריח רק עץ בעלמא וגם עוד זאת שיצמיח מגרעין א' פירות הרבה מאד בתוספת ברכה מרובה לאין שיעור נגד פרי הא' שממנו נלקח הגרעין. אבל מ\"מ מובן שעיקר טעם וריח ומראה של הפירות הצומחים נלקחו מן הגרעין הנזרע שהיו כלולים בו ממש."],[75,"ובלעדו לא הי' כלל צמיחת פירות אלו המשובחים כ\"א ממנו דוקא צמחו ובאו. אלא שלפי שבעוד שהיו בחי' אלו בהגרעין הנה נתגשמו וירדו והיו כעץ בעלמא ולולי כח הצומח שבארץ לא הי' מהם שום צמיחה והי' נשאר הכח בהעלם ולא הי' יוצא אל הגילוי כלל וזה שיצא מההעלם אל הגילוי הוא ע\"י כח הצומח וגם עי\"ז נמשך הגילוי בתוספת ברכה מרובה יותר אפילו מהפרי שממנו נלקח הגרעין כנ\"ל."],[75,"ועד\"ז ממש הוא במשל התהוות הולד מהטפה ע\"י האשה שאע\"פ שעיקר מהות הולד הוא כלול בהטפה מ\"מ כיון שכבר ירד בדילוג הערך מבחינת מהות אדם למהות טפה גשמית לכן לולי שהי' נקלט בבטן הנקבה לא הי' מזה שום התהוות והית' נשאר' טפה גשמית. רק שע\"י שנקלט ברחם הנוק' נעשה צמיחה וגידול זה להיות ולד ברמ\"ח איברי' כו' שבה דוקא יש הכח הזה. ומ\"מ עיקר ושרש הולד נמשך מהטפה ועל כן אנו רואים שהאשה יולדת ולד שהוא גדול המעלה ממנה שהרי יולדת זכר והיא עצמה מעלמא דנוקבא:"],[75,"<b>והנמשל<\/b> מזה הוא כי התומ\"צ נק' בשם זריעה זורע צדקות כו'. וכמ\"ש במ\"א ע\"פ שש שנים תזרע שדך שהם שיתא סדרי משנה כו'. כי הנה לכאורה אינו מובן איך ע\"י מצות מעשיות ⟦נה,א⟧יומשך לע\"ל גלוי אור א\"ס ב\"ה שאין לו קץ ותכלית. אך הענין כי שרש המצות גבוה מאד שהם בחי' תר\"ך עמודי אור הנמשך מכתר עליון בחי' סוכ\"ע ממש אלא שירדו ונתלבשו בגשמיות ציצית בצמר תפילין בקלף וה\"ז כמו הגרעין שאע\"פ שיש בו כח ותמונת הפרי. אבל הוא בהסתר והעלם עד שאינו ניכר כלל כ\"א הוא כעץ בעלמא."],[75,"וע\"י נש\"י שמקיים המצוה ומתעטף בציצית ומניח תפילין הם בחי' ארץ חפץ המצמיחי' גלוי הפרי מהגרעין בטעם ומראה וריח הוא שיהי' גלוי תר\"ך עמודי אור כו' ממש. ולכן נק' כנס\"י אשה יראת כו' כמו באשה יש הכח להצמיח ולהיות בה ועל ידה התהוות הולד מהטפה כנ\"ל."],[75,"והיינו לפי שהיא בחי' יראת ה' שיש בהם בחי' הביטול להפך יש לאין וממרירו למיתקו שזהו בחי' ארץ חפץ היינו בחי' מלכות דאצי' ששרשה מבחי' מלכות דא\"ס שהיא מלכות דא\"ק ולכן יש בה הכח להצמיח כו' שהוא בחי' א\"ס."],[75,"ולכן הם ראשית תבואתה ומארי דאורייתא שהתומ\"צ כמו שירדו למטה הם בחי' גרעין כו'. אך לאחר שתצמח הפרי ומלאו פני תבל תנובה הוא בחי' אור שלמעלה מנש\"י והיינו בחי' ⟦נה,ב⟧יסוד דא\"ק שלמעלה מעלה מבחי' מלכות דא\"ק כו' שמבחי' יסוד דא\"ק הוא שרש המצות."],[75,"וזהו כמשל שהאשה יולדת זכר שהוא למעלה ממנה כנ\"ל. וענין ב' בחי' מקיפים הענין הוא כי הנה המקיף הוא ג\"כ מחי' ונק' אור מקיף וזהו בחי' מקיף הקרוב וכמו אבל חרדה גדולה נפלה עליהם משום דמזלייהו חזי. הרי הגיע להם התפעלות בפנימיותם מחמת האור מקיף שהוא בחינת מזלייהו כו' ויש עוד בחינת מקיף המובדל לגמרי מגדר העולמות ואינו מאיר בהם כלל לגודל אורו."],[75,"וזהו שהמשכת סוכ\"ע כעת ע\"י המצות הוא בחי' מקיף הקרוב הנ\"ל משא\"כ מקיף המובדל כו' אינו מאיר כעת כ\"א לע\"ל שיקויים ונגולו כספר השמים שמקיף הקרוב יומשך להיות בגלוי ממש ע\"ד אור פנימי ואז יומשך מקיף הגדול ההוא המובדל וכו' להיות מאיר ומחיה ג\"כ ועי\"ז יהי' תח\"ה ועמ\"ש ע\"פ יתקע בשופר גדול כו' שב' בחי' מקיפים אלו הוא כי רצון העליון זהו בחי' כתר וסוכ\"ע והוא מקיף הקרוב ויש עוד בחי' הנק' רעוא דכל רעוין שלמעלה מעלה מבחי' רצון כו'. וזהו הללוהו כרב גודלו שיש בחי' אין קץ בבחי' גודלו כו' ע\"ש:"],[76,"⟦נה,א⟧<b>וארא אל אברהם אל יצחק ואל יעקב באל שדי ושמי הוי\"ה לא נודעתי להם.<\/b> הנה וארא יש בו ב' פירושים א' לשון עבר שנתגלה לאבות והב' לשון עתיד שהוא לשון הוה שתמיד יש בחינה זו בכל זמן בכל אדם כי הנה אין קורין אבות אלא לשלשה."],[76,"והענין שבחי' האבות היא ירושה לבניהם אחריהם בכל דור ודור לכל חד לפום שיעורא דיליה. ולכן אומרים אלהי אבותינו אלהי אברהם וכו' אבל שאר בחינות ומעלת הצדיקים כגון השבטים ראובן שמעון לוי שהם ודאי בחינות אורות עליונים יש לך אדם שאין בו כלל בחי' ומדרגות אלו משא\"כ בחי' האבות צריך להיות בכל אדם שהם שרש ומקור כל נשמות ישראל."],[76,"ולהבין ענין גילוי זה שבכל דור ודור בבחי' ומדריגת האבות שבכל אדם מישראל. הנה הגלות נמשל לעבור. וגאולת ימי המשיח שיהיה במהרה בימינו נמשל ללידה כמ\"ש כי חלה גם ילדה ציון את בניה וכשישראל נתונים בצרה ח\"ו כתיב כי באו בנים עד משבר וכח אין ללידה וכן חבלי ימות המשיח נקראים בשם חבלי לידה כמ\"ש כי חבלי לידה יבאו לך."],[76,"וכן בגאולת מצרים המשיל בנבואת יחזקאל כל הענין לולד ביום הלידה כמ\"ש ומולדותיך ביום הולדת אותך לא כרת שרך וגו'. ולהבין משל ומליצה צריך להבין מהו ענין העיבור. כי הנה אמרו רז\"ל דרש ר' שמלאי למה הולד דומה במעי אמו לפינקס מקופל ראשו בין ברכיו ועקבותיו על עגבותיו ואוכל ממה שאמו אוכלת וכו' ופיו סתום וטבורו פתוח וכשיצא לאויר העולם נפתח הסתום ונסתם הפתוח כו' דהיינו שיש להעובר כל חתוך האברי' ראש ועינים ואזנים כו' אלא שראשו מקופל ומונח בין ברכיו שאינו משמש כלום שאינו מחשב ומהרהר וכן עינים לו ולא ירא' ואזנים ולא ישמע וגם המאכל שלו אף שאוכל ממה שאמו אוכלת אינו הולך לו דרך הפה רק דרך הטבור לבני מעיים בלבד להגדיל הגוף כמו שנראה בחוש שבתשעה ירחי לידה נגדל גופו אבל להיות המאכל עובר דרך הפה דהיינו לשלוח חיות ללב ומשם למוח שהם אברי הנשימה אף שנגמרו כל אבריו ויש בו אברי הנשימה ג\"כ מכל מקום הרי אין לו נשמת רוח חיים עד שיצא לאויר העולם שאז מוציא הקול כמ\"ש רז\"ל שהוא סימן הלידה דשמעי לולד דצויץ משום שהוציא ראשו ולכן אינו שולח חיות לאברי הנשימה ⟦נה,ב⟧אלא לאברי המזון בלבד דרך טבורו ששם הוא משכן הבני מעיים אברי המזון משא\"כ ראשו עם כל אברי הנשימה אין משמשין כלום והרי הם כמתים ולכן ראשו מוטל בין ברכיו מפני שאין לו חיות."],[76,"והנה ככל הדברים האלה וככל המשל הזה כך נמשלו בני ישראל בעת הגלות דכתיב ה' ממרום ישאג פי' כמ\"ש בזהר דסליק קוב\"ה לעילא וכתי' רחל מבכה על בניה כו' כי איננו ופי' בזהר דקאי על הקב\"ה כי איננו בגו בנהא דסליק כו' פי' שסילק שכינתו וגילוי אלהותו מהתחתונים ודומה לעיני בשר כאלו העולם דבר בפני עצמו והשמן לב העם ועיניו השע עינים להם ולא יראו אור ה' כי בשמים ממעל ועל הארץ מתחת אין עוד ואפי' השפעת מצות ומעשים טובים שהם מזון לנפש אינו עובר להם דרך הנשימה לשלוח חיות ללב ולמוח למען דעת ה' ולאהבה אותו ולעבדו בכל לבבם בלב שלם ונפש חפצה ותשוקה מורגשת בלב כרשפי אש שלהבת וצמאון כו' כי אם כענין שנאמר ותהי יראתם אותי מצות אנשים מלומדה דהיינו בבחי' עשיה גשמית בלבד ובקרירות כו'. וזהו עיקר הגלות ברוחניות."],[76,"והנה תכלית השלימות של ימות המשיח שהוא בחי' לידה והתגלות אור ה' בקרב איש ולב עמוק כמ\"ש ונגלה כבוד ה' וראו כל בשר וגו'. וכתיב כי עין בעין יראו וגו' הוא תלוי במעשינו ובעבודתנו בימי הגלות ע\"י התעוררות אהבה המסותרת ודאי בלבו של אדם עד שתחפוץ בחפצה ותשוקה ונפש שוקקה ולהיו' אהבת ה' בהתגלות לבו."],[76,"וזהו שמע ישראל ה' אלהינו ה' אחד. ואהבת וגו'. כי הנה צריך להבין מלת אחד שאינו מורה לכאורה על אמתית יחודו ית' שהוא לבדו הוא ואפס זולתו ואין מלת אחד מורה על זה שהרי יש אחד המנוי ג\"כ ע\"ד משל יעקב היה לו י\"ב שבטים ואעפ\"כ נק' ראובן אחד. אך יצחק נק' בנך יחידך וגם כאן הוי ליה למימר ה' יחיד. אך הענין שבאמת לגבי קוב\"ה מצד עצמותו ומהותו ית' לא שייך עליו מלת אחד כלל שהרי הוא יחיד ומיוחד והוא לבדו הוא אלא כמאמר רז\"ל שהוא אחד בשבעה רקיעים ובארץ ובד' רוחות העולם ר\"ל שגם בשמים ובארץ ובד' רוחות העולם שהם בחי' ו\"ק העולם בחי' התחלקות ופירוד אעפ\"כ שורה ומתגלה יחודו ואחדותו ית' ואינון מתיחדין באחד שכולם בטלים לגבי אור ה' השורה ומתגלה בהם וכמ\"ש וצבא השמים לך משתחוים והם ⟦נה,ג⟧ו\"ק גשמיים וששה קצוות רוחניים דהיינו בחי' מעלה ומטה שיש בכל העולמות למעלה עד אין קץ ולמטה עד אין תכלית כי גבוה מעל גבוה וגו' דהיינו מה שהוא נתפס ומושג בשכל והשגת הנבראים שבכל העולמות נק' מטה לגבי העליון שאינו נתפס ומושג בשכל והשגת הנבראים שלמטה ממנו ולית מחשבה דלהון תפיסא ביה וכן ד' רוחות העולם כי חסד דרועא ימינא שהוא דרום וגבורה דרועא שמאלא שהוא צפון כו' וכולם מתייחדים ונעשים אחד ליחודו ית' השוכן בתוכם משא\"כ לגבי קוב\"ה בכבודו ובעצמו שהוא יחיד ומיוחד הרי הוא רם ונשא רבבות מדרגות עד אין קץ וסוף מגדר הקצוות גשמיות ורוחניות וכמ\"ש לך ה' הגדולה והגבורה וכו' פי' שבחי' גדולה וגבורה וכו' בטלים לו ית' שאינם נקראים בשם גדולה וגבורה כלל כי כל בשמים ובארץ פי' שהכל בטלים אליו ית' ולפניו כחשיכה כאורה ומעלה מטה שוין כי מהותו ועצמותו נמצא למטה כמו שנמצא למעלה ממש בלי שום חילוק ושינוי כלל ולא שייך לפניו ית' בחינת מעלה ומטה כלל ובחי' שמים וארץ כלל לא בבחינת ממלא כל עלמין ולא בבחי' סובב כל עלמין כי אינו בבחי' וגדר עלמין כלל וכדכתיב כי נשגב שמו לבדו רק הודו על ארץ ושמים הודו בלבד בחי' זיו והתפשטות והארה ממנו בלבד ואף גם בבחי' זו ארץ קדמה לשמים כו' כמ\"ש במ\"א ולכן אומרים מלא כל הארץ כבודו והמלאכים אומרים איה מקום כבודו להעריצו כו'."],[76,"והנה בחי' עיבור דהיינו בימי הגלות סליק קוב\"ה לעילא לעילא דהיינו לגבי בחי' מהותו ועצמותו בחינת יחיד ומיוחד שאינו בגדר עלמין כלל ואינו שורה ומתגלה יחודו ואחדותו בתחתונים וכדכתיב ביום ההוא (דהיינו לעתיד) יהיה ה' אחד ושמו אחד כדאמרי' בגמ' אטו האידנא לאו אחד כו' והיינו משום שבזמן הגלות אינו נראה יחודו ית' בהתגלות ונראה כאלו העולם הוא דבר ויש בפני עצמו אלא שאף בגלותנו לא עזבנו ה' אחד ונותן לנו הכח להיותנו בני ישראל עם קרובו להיות יכולים להמשיך בחינת יחודו ואחדותו ית' למטה בתחתונים להיות שם ה' אחד בגילוי גם בבחי' התחלקות הקצוות מעלה ומטה כו' בגשמיות ורוחניות (וכן להמשיך על נפש האדם בבחי' ששה קצוות שלו שהם המדות אהבה ויראה כו' שיהיו בהתגלות לבו) וזהו שמע ישראל פי' שישראל עם קרובו לכן ניתן להם הכח להמשיך בחי' הוי\"ה למטה שיהא אחד ומתיחד בתחתונים וזהו תכלית כל העבודה מפני שנתאוה הקב\"ה להיות לו דירה בתחתונים דייקא לאתכפיא סט\"א ואסתלק יקרא דקוב\"ה כו' וזהו וידעו מצרים כי אני ה' ולכן במקום שבעלי תשובה עומדים צדיקים גמורים כו'."],[76,"וזהו ישמח ישראל בעשיו לשון רבים כי עושיו הם המשכותיו בבחי' רבוי והתחלקות כדי לקשרם וליחדם אליו ית' ועי\"ז ממילא בא לבחי' ומעלת ואהבת את ה' וגו' בכל לבבך בשני יצריך דהיינו שתהיה אהבת ה' תקועה בלבו בהתגלות כרשפי אש שלהבת כל כך עד שירגיז יצר טוב על יצר הרע כאדם שהוא ברוגז על הפוך רצונו התקוע לו בלבו ונוגע לעצמותו ומהותו כך כשתהיה אהבת ה' בקרב איש ולב עמוק ונגעה עד הנפש עד עצמותה ומהותה ממילא יהיה ברוגז מאד על ההפוך."],[76,"והנה עיקר העבודה מאהבה היא שמחת הנפש בה' עושה וקיום המצות בשמחה וכמ\"ש עבדו את ה' בשמחה וכתיב תחת אשר לא עבדת את ה' אלהיך בשמחה ובטוב לבב מרוב כל וכמ\"ש האריז\"ל פי' פסוק זה."],[76,"והנה השמחה נמשלה לחלב וכמ\"ש דבש וחלב תחת לשונך וכדכתיב כאיש אשר אמו תנחמנו כו' דהיינו כשם שהאם רוצה לשעשע את הילד מניקתו בחלב וזהו שעשועים שלו כי ע\"י זה מתגדלים אבריו עד שיכול להלך והנה החלב מתהוה מדם כי ⟦נה,ד⟧דם נעכר ונעשה חלב והדם הוא נעשה מן אכילה ושתיה שאוכלת האם שנהפך בקרבה ונעשה דם:"],[76,"<b>ולהבין<\/b> ענין זה בעבודת ה'. הנה כתיב את קרבני לחמי לאשי שהקרבן נעשה לו ית' בחינת לחם ומזון כביכול שעולה ריח ניחח לה' ע\"ד ישראל מפרנסין לאביהם שבשמים. וענין הקרבן להקריב גם נפש הבהמי' שבאדם בשעת הבאת קרבנו מן הבהמה בכוונה וברעותא דלבא למסור נפשו לה' להעביר רוח הטומאה מן הארץ וכל מחשבות והרהורין בישין יבטלון והיו לשרפת אש כליל על מזבח ה'."],[76,"ועכשיו שאין בהמ\"ק קיים בטלו הקרבנות ואין אנו יכולים לבטל ולהעביר ממשלת הנפש הבהמית מכל וכל לכן תקנו לנו תפלות כנגד תמידין. וזהו שאומרים ברוך אתה ה' כו'. כלומר שאף שאין אנחנו יכולים לעשות חובותינו באתערותא דלתתא שלנו אעפ\"כ יהא אתערותא דלעילא מחמת כי חפץ חסד הוא ויוברך ויומשך מלעילא ברכת ה' להיות שמו נקרא עלינו בבחינת אלהינו שנהיה בטלים אליו למשוך אחריו בכל לב ונפש כו' כמ\"ש במ\"א ועד\"ז הוא ענין כל רמ\"ח מצות עשה רמ\"ח המשכות גילוי אלהותו ית' להיות שורה בתחתונים והוא נחשב לו ית' עד\"מ כמו אכילה שע\"י מאכל האדם תחזק נפשו בגופו להיות משכן לנפש בתוך הגוף וכן ע\"י מצות ומע\"ט נעשה כסא ומכון לשבתו להיות לו דירה בתחתונים כשיומשך ויתגלה בהם בחי' ה' אחד וגם ישראל למטה מקבלים הארה מבחי' אכילה זו לשלוח חיות ללב ולמוח כדי לאהבה את ה' ולעבדו בכל לב ונפש ואח\"כ יעלו ויבאו מזה לקבל הארת והשפעת בחי' הדם הוא הנפש כמו המזון שנהפך בקרבו ונעשה דמו וזהו חיותו וקיומו כך ע\"י המשכת אור ה' על נפשו בקיום המצות בסור מרע ועשה טוב נעשה כסא ומכון לשבתו עד שאור ה' אחד שורה ומתגלה בו בתוך נקודת לבבו ונגעה עד הנפש ממש להיות כמו עצמיות אחד ממש וממילא ירגז על הרע שבקרבו כמו רוגז האדם על הפוך בדבר שנוגע לעצמותו ומהותו שבא מרתיחת הדמים כי הדם הוא הנפש וזהו בחי' יצחק ובחי' זבחי אלקים רוח נשברה וגו' דהיינו רוח הס\"א כו' ומזה יבא לבחי' ומדרגת יעקב מדת הרחמנות על נפשו כאשר יראה בה שהיא בתוך ההפכה ואזי ויצעק אל ה' בצר לו שממדת הרוגז על הרע בא למדת הרחמנות משא\"כ כשיש דרך ישר לפני איש לא שייך ונופל עליו לשון רחמנות והרחמנות הוא התחלה והכנה לשמחה שתבוא אח\"כ כאשר ישיב ללבו הן אמת כו'. כמ\"ש בתניא ועי\"ז תהיה השמחה גדולה לאלהים אשר קדשנו במצותיו בקדש העליון כו' כיתרון האור הבא מחשך כמ\"ש במ\"א וזהו בבכי יבאו ובתחנונים אובילם וכתיב הלוך ובכה ילכו ואת ה' אלהיהם יבקשו כי הבכיה לעתיד תתעורר מחמת בחי' ראיה וראו כל בשר וגו' ואז יתעורר הרחמנות במאד על העבר והיא התחלת השמחה לשמוח באלהים חיים וקרבת ה' יחפץ כמ\"ש ואת ה' אלהיהם יבקשו ולכן אומרים בתפלת שמונה עשרה סלח לנו כי חטאנו ולא קודם התפלה לפי שעדיין לא קבל עליו מלכות שמים בק\"ש משא\"כ כשאומר בק\"ש ה' אחד דהיינו שיחודו ואחדותו ית' מתגלה בתחתונים ואזי רואה בנפשו חטאו וחסרונו שחסר לו אור ה' ובהבל בא ובחשך ילך ע\"כ המו מעיו לו רחם ירחמנו ואח\"כ יוכל לבא לידי שמחה אמיתית ואין לך שמחה אמיתית יותר מזה שכאשר לא נולדה תחלה הרחמנות בנפשו אין זו שמחה אמיתית וכמשל התינוק הנולד שבצאתו לאויר העולם הוא צועק תחלה ואח\"כ נותנים לו החלב. והנה עיקר השמחה והתענוג הוא מהתבוננות בגדולת ה' ואשר בחר בנו מכל העמים וקרבנו לעבודתו ולכן ארז\"ל שהדדים הם במקום בינה:"],[76,"⟦נו,א⟧<b>וזהו<\/b> וארא אל אברהם אל יצחק ואל יעקב באל שדי. פי' בבחי' והמשכות בחי' שדי מל' ברכות שדים שהם בחי' דדים וחלב להגדיל המדות אהבה ויראה כו' שהן הם בחי' האבות אחר שה' אחד בהתגלות לבו בבחי' לידה והתגלות לשמח נפשם בתוספת אורה ושמחה להתענג על ה' בשמחה ובטוב לבב מרוב כל:"],[76,"<b>אך<\/b> ושמי ה' לא נודעתי להם. כי הנה אמרו רז\"ל שקיים אברהם אבינו ע\"ה את כל התורה עד שלא נתנה והיינו שקיים מעשה המצות מאהבה וכמאמר רז\"ל אברהם תיקן תפלת שחרית והיינו בחינת המשכת אור ה' להיות ה' אחד שורה ומתגלה בתחתונים לאהבה את ה' אהבה בתענוגים ולעבדו בלב ונפש אבל מ\"מ כל זה נק' עדיין בשם עבודת עבד ששומע בקול רבו ועושה ציוויו מאהבה ובשמחה ובטוב לבב וכן יצחק מיראה ופחד יצחק כו'. אבל משה רבינו ע\"ה מדה אחרת היתה בו שאמר ונחנו מה בחי' בטול לגמרי לפיכך זכה שנתנה תורה על ידו בבחי' דבור ואמרו רז\"ל שהיתה שכינה מדברת מתוך גרונו של משה כי לא שייך בחי' אהבה ותענוג רק בבחי' התגלות נגלות אור ה' להיות השראתו בתחתונים שהם בגדר עלמין מעלה ומטה כו' אבל דבר ה' זו הלכה ואורייתא וקוב\"ה כולא חד שהוא יחיד ומיוחד ולית מחשבה תפיסא ביה לא שייך בזה שום הרגשת אהבה או תענוג שאינו מרגיש את עצמו כלל רק הוא בטל במציאות ואינו תופס מקום לעצמו כלל אלא שהוא נמשך אחריו לדבר מה שהוא מדבר וכמ\"ש ואשים דברי בפיך ובזה הוא ממשיך המשכת יחודו ואחדותו ית' בכבודו ובעצמו כמו קודם שנברא העולם שיתגלה למטה שגם עכשיו העולם כאין ואפס והי' כלא היה ואין כאן לא מעלה ולא מטה כו'."],[76,"ומזה אינו נמשך על נפש האדם בחי' אהבה או תענוג רק בחי' בטול לגמרי וזהו לשון דבור מלשון ידבר עמים תחתנו שהוא ל' הנהגה והמשכ' דהיינו שממשיך שיתגלה למטה בבחי' היותו יחיד שהוא בחי' עצמותו ומהותו כביכול ולא בבחי' אחד בלבד והיינו ע\"י התורה דכתיב בה וידבר ה' אל משה וגם אינה נקראת בשם עבודת עבד כי כשלומד הדין זה ומדבר דין זה הוא כמלך שמצוה לעשות משפט עמו."],[76,"ולכן אמרו מאן מלכי רבנן ואמרו מתניתא מלכתא שהרי הוא כאומר דבר המלך בלבד ואינו עושה כלום ואינו מדבר דברי עצמו כלל כמו העבד העושה צווי רבו שהרי הוא העושה והמקיים דבר המלך ודתו ואפילו עושה מאהבה בתענוגים אעפ\"כ יש מי שאוהב כו' ולפי שלא נתנה תורה להאבות עדיין לכן כתיב ושמי ה' לא נודעתי להם לא הודעתי אין כתיב כאן אלא נודעתי שאלו כתיב הודעתי היה משמע דקאי על שמי ה' אבל עכשיו דכתיב לא נודעתי פי' שאני בעצמי לא נודעתי להם דהיינו בבחי' אני בעצמי בחי' יחיד."],[76,"וזהו והיו הדברים האלה אשר אנכי מצוך היום פי' אנכי מי שאנכי דהיינו בחי' יחיד משא\"כ אצל ואהבת כתיב ואהבת את ה' אלקיך אבל התורה היא נמשכה למעלה מבחי' הוי\"ה דהיינו בחינת לפני ה' וכו' הוא בחינת אנכי מי שאנכי כמ\"ש במ\"א:"],[77,"<b>וידבר אלקים אל משה ויאמר אליו אני ה' וארא אל אברהם כו'.<\/b> הנה פרשה זו נאמרה תשובה על מ\"ש למעלה וישב משה ויאמר למה הרעות כו'. והשיב לו הקב\"ה וארא אל וגו'."],[77,"וצריך להבין מה תשובה היא זו על למה הרעות. גם להבין ענין החטא שבעבורו בא הגלות בחומר ובלבנים כו'. וכבר נגזר כן בברית בין הבתרים ועבדום וענו אתם כו'. וכ\"כ למה. אך הנה כתיב ביום עשות ה' אלקים ארץ ושמים שלבריאת שמים וארץ שיתף שם הוי' בשם אלקים."],[77,"וביאור שני שמות אלו הוי' ⟦נו,ב⟧ואלקים הנה אלקים לשון רבים. כמ\"ש כי אלקים קדושים הוא. והוי' הוא אחד. והענין דהנה כתיב גדול ה' ומהולל מאד ולגדולתו אין חקר ואימתי גדול כשהוא בעיר אלקינו כו'. כי מהיות לגדולתו ית' אין חקר ולית מחשבה תפיסא ביה כלל לא שייך לומר עליו לשון גדולה כי אם בהתפשטות זיו והארה מבחינת מלכותו ית' וכדכתיב מלכותך מלכות כל עולמים והתפשטות והמשכה זו אינה אלא זיו והארה בעלמא ונק' אור א\"ס ב\"ה וזיו השכינה שהוא רק כמשל אור המאיר מהשמש וכדכתיב כי שמש ומגן הוי\"ה אלקים שכמו שהאור הזה שמתפשט מהשמש להאיר על הארץ אינו אלא זיו ואין לו ערך ויחוס לגבי עצמיות השמש שאינו ממהותו כלל אף שנמשך ומתפשט מהשמש עצמו כך החיות המתפשט לקיום והתהוות עולמות עליונים ותחתונים מריש כל דרגין כו'. אין זה אלא בחי' זיו שאין תופסים מקום וכולא קמיה כלא חשיב."],[77,"והנה כתיב מה רבו מעשיך וכתיב מה גדלו מעשיך. מה רבו מעשיך קאי על עולמות התחתונים וכל הברואים שבעוה\"ז המתחלקים למיניהם בכמה מיני התחלקות רבי רבבות מדרגות בדצ\"ח שכמה מיני דומם וכמה מיני צומח כו'."],[77,"וכל מין ומין יש לו טעם בפ\"ע כמו תפוחים ואגוזים ושקדים. וכיוצא בהם בצומח שכל א' יש לו טעם בפ\"ע שאין הא' דומה לחבירו. וכן בכל מיני עשבים כל עשב יש לו טעם בפ\"ע."],[77,"והטעם הוא רוחני ממזל השופע עליו. שאין לך כל עשב מלמטה כו'. וכל זה הוא מפסולת עולמות עליונים וכמ\"ש וכל קרבי את שם קדשו שיש בחי' קרביים עליונים שמבררים הפסולת להשפיע לעוה\"ז הגשמי."],[77,"וכמארז\"ל נטה שמאלו וברא ארץ. ונטה ימינו וברא שמים [וע' מזה בזהר ח\"ב ד\"כ ע\"א. ל\"ז ע\"א. פ\"ה סע\"ב. ח\"א ד' למ\"ד ע\"א] שהארץ מקבלת מבחי' שמאל וע\"ז נאמר מה רבו מעשיך. אך מה גדלו מעשיך קאי על העולמות עליונים מלאכים ונשמות שמתענגים על ה' ואין תענוג א' דומה לחבירו."],[77,"וכמארז\"ל עתיד הקב\"ה להנחיל לכל צדיק וצדיק ש\"י עולמות. שנאמר להנחיל אוהבי יש כו'. ולכאורה אינו מובן למה צריך כל צדיק כ\"כ עולמותוכי לנכסים הוא צריך. אך הענין כי שכר מצוה מצוה היא המשכת ענג העליון להיות נהנים מזיו השכינה וכל מצוה ומצוה יש לה ענג בפ\"ע גם אין מהות צדיק אחד דומה לחבירו בעבודתו בהתפעלות אהוי\"ר. כי יש מתפעל כו' ויש מתפעל כו'."],[77,"ולכן עתיד הקב\"ה להנחיל לכל צדיק וצדיק כו'. כי כל א' הוא מדור בפ\"ע בבחינת זיו והשגה פרטית מיוחדת אשר משיג ונהנה ומתענג על ה' תענוג פרטי מיוחד ונבדל מתענוג והשגת צדיק חבירו כי כל חד לפום שיעורא דיליה. וזיו השכינה כולל רבי רבבות מדרגות ומיני תענוג לנשמות עד אין קץ ותכלית ממש שהרי נמשך מאור א\"ס ב\"ה."],[77,"והנה התחלקות החיות מאור א\"ס לכל העולמות ברבוי התחלקות המדרגות בהרבה מיני תענוג לכל חד וחד לפום שיעורא דיליה היא הנקרא בשם אלקים לשון רבים ע\"ש רבוי התחלקות בהתפשטות החיות מלמעלה והיא היא התפשטות גדולתו ית' בבחי' גילוי שיכירו וידעו גדלו ותפארתו שע\"כ הם מתענגים לחזות בנועם ה'."],[77,"וזהו אימתי גדול כשהוא בעיר אלקינו. עיר נק' מה שמקובץ מכמה בתים. ובתים הם צירופי אותיות וכמ\"ש בס\"י שתי אבנים בונות שני בתים. דהיינו בחי' אותיות והמשכות התחלקות החיות בכמה בתים ומדרגות כמו השכל שמתחלק באותיות המחשבה עד\"מ. כך התפשטות גדולתו ית' מתחלק בכמה בחי' התחלקות ורבוי התענוגים בכל עולמות לכל חד לפום שיעורא דיליה ואז נק' אלקים לשון רבים ע\"ש רבוי התחלקות בהתפשטות החיות בבחי' ⟦נו,ג⟧גילוי לעולמות ונבראים. משא\"כ הוי\"ה נק' אחד שהוי\"ה הוא בחי' מקור כל הויות ושרשא דכולא קודם שבא לידי המשכה בבחי' גילוי בעיר אלקינו כו':"],[77,"<b>והנה<\/b> מבחי' אלקים נמשך למטה בחי' היראה. וכמ\"ש והאלקי' עשה שייראו מלפניו. וכתיב את האלקים ירא. וכתיב את ה' אלקיך תירא כי בבחי' הוי' לית מחשבה תפיסא ביה. רק בבחי' אלקים הוא התפשטות גדולתו ית' תפול על האדם אימה ויראת בושת כו'."],[77,"וכן האהבה נמשכת ע\"י בחי' אלקים דייקא. וכמ\"ש הללוהו בגבורותיו הללוהו כרוב גודלו. וכתיב ואהבת את ה' אלהיך כו' להיות האהבה להוי' בבחי' בטול במציאות לבחי' דלית מחשבה כו' צ\"ל תחלה ע\"י בחי' אלקים שיתבונן בגדולת א\"ס ב\"ה והתפשטותו בנבראים."],[77,"ומזה ישוב לאהבה את ה' דלית מחשבה כו'. והיינו ע\"י בחי' יחוד הוי' באלקים. וזהו וידבר אלקים אל משה ויאמר אליו אני הוי' שע\"י בחי' אלקים הוא גילוי שם הוי'. ועי\"ז וארא אל אברהם ויצחק כו' הם המדות אהוי\"ר כו' שנולדו מזה."],[77,"וע\"ז נאמר ביום עשות ה' אלקים ארץ ושמים שהוא יחוד הוי' באלקים להיות גילוי שם הוי' למטה. אך הנה נודע כי האהבה שממטה למעלה עיקרה כדי להגיע שתהא באה על האדם מלמעלה האהבה העליונה שהיא העיקרית. והאבות הן הן בחי' המרכבה. פי' כי אברהם מרכבה להאהבה העליונה. וכדכתיב ויסע אברם הלוך ונסוע ממטה למעלה עד הנגבה שהיא האהבה העליונה שתשרה עליו מלמעלה בבחי' רוכב והוא יהי' מרכבה אליה."],[77,"והנה ע\"י אתערותא דלתתא אתערותא דלעילא. אך מי הגורם ומחבר אהבה העליונה שמאתערותא דלעילא שהיא בבחי' א\"ס להיות שורה ומתגלה באתערותא דלתתא בנפש האדם שהוא גבול ונברא יש מאין. הנה ע\"ז נאמר באל שדי. פי' שאמר לעולמו די עולמו הוא מ\"ש עולם חסד יבנה."],[77,"ופי' יבנה בבנין. וכמ\"ש בחכמה יבנה בית כאדם שבונה בית לשבת בו כך צריך החסד להיות נבנה בבית להיות בו ישיבת הנשמה כי חסד עליון ואהבה העליונה היא בחי' א\"ס. וא\"א להיות בו משכן הנשמה ומכון שבתה כי אם ע\"י כמה צמצומים להיות בחי' עולם והעלם אוא\"ס ב\"ה."],[77,"ולהיות נבנה בבחי' בית שהוא ע\"י צירופי אותיות שתי אבנים בונות כו'. ועתיד הקב\"ה להנחיל לכל צדיק ש\"י עולמות בחי' יש וכמ\"ש להנחיל אוהבי יש. שע\"י כמה צמצומים וירידות והשתלשלות המדרגות יומשך שיתגלה החסד עליון והאהבה העליונה בבחי' יש כדי שיוכלו הנשמות לקבל ולהיות נהנים מזיו כו'."],[77,"וזהו שאמר לעולמו די הוא בחי' הצמצום שעי\"ז וארא אל אברהם כו' להיות גלוי האהבה העליונה שהיא העיקרית. וע\"ז נאמר ואהבת את ה' אלקיך ואהבת הוא פועל יוצא. וכן לאהבה את ה' ולא כתיב לאהוב כו' כי העיקר הוא להמשיך האהבה העליונה בק\"ש."],[77,"והוא מ\"ש אהבתי אתכם אמר ה' ואהבה זו תהיה בכל לבבך בתוך כל לבבך בשני יצריך. שגם היצה\"ר ישוב לאהבת ה' כי בהמשיך עליו האהבה העליונה ממילא לבו המס ימס כהמס דונג כו'. ויהיה לאכפייא כו'. וזה נמשך בק\"ש כי מפסוקי דזמרה עד ק\"ש צ\"ל האהבה שממטה למעלה אבל בק\"ש צ\"ל המשכת האהבה העליונה:"],[77,"<b>אך<\/b> הנה כל זה הוא בגלוי המשכת המדות אהוי\"ר שהוא יחוד הוי' באלקים כשכבר נמשך בבחי' אלקים. אבל ושמי הוי' דהיינו בבחי' הוי' לבדו קודם שבא לידי גלוי ההמשכה במדות שהוא מקור ושרש כל ההויות ומקור החיים כו' לא נודעתי להם שאינו בא לידי גילוי בנפש מחמת אתערותא דלתתא רק מפני כי אשר קדשנו במצותיו ⟦נו,ד⟧דייקא. הקב\"ה מניח תפילין כו'."],[77,"ות\"ת שכנגד כולם שמקור התורה הוא למעלה מעלה. וכמ\"ש בזהר ע\"פ מה יתרון לאדם בכל עמלו שיעמל תחת השמש שאני אורייתא דעמלה לעילא מן שמשא. פי' שהוא למעלה מעלה מבחי' שמש ומגן ה' אלקים דהיינו כשהוי\"ה נמשך באלקים כו'. וגילוי בחי' זו לא נמשך להאבות רק לישראל במ\"ת פנים בפנים דבר כו' אנכי מי שאנכי כו':"],[77,"<b>אך<\/b> הנה כדי שיהי' בחי' זו בגלוי במ\"ת צ\"ל תחלה בחי' הסתלקות למעלה כי שרשו למעלה הוא בחי' מטי ולא מטי והחיות רצוא ושוב. וכדי שיהיה בחי' מטי צ\"ל תחלה בחי' לא מטי."],[77,"וכפי ערך השוב בגלוי שאח\"כ כך הוא בחי' הרצוא שבתחלה. ולכן היה מתחלה זמן הגלות ושליטת מצרים מפני הסתלקות החיות למעלה. כי הנה כתיב רם על כל גוים ה' על השמים כבודו. שכל עכו\"ם מקבלים שפעם וחיותם מבחי' רוממות רם כו' על השמים כו'. שכשהוא בבחי' המשפילי לראות בשמים אזי מי כה' אלקינו כתיב שאין הקב\"ה משרה שכינתו אלא על ישראל."],[77,"והיינו בהמשכת גילוי אור א\"ס ב\"ה למטה שתלוי במעשה התחתונים הממשיכים בעבודתם בחי' גילוי זה. משא\"כ במקור למעלה שהוא בחי' רוממות גם העכו\"ם מקבלים שפעם משם ע\"י השתלשלות וירידת המדרגות. וכמ\"ש ואלה המלכים אשר מלכו בארץ אדום לפני מלך מלך לבנ\"י (כנודע מענין שבירת הכלים) וזהו שאמרו רז\"ל למה נק' הר סיני שירדה שנאה לעכו\"ם. דהיינו ע\"י הר סיני דוקא בגילוי מ\"ת. אבל קודם מ\"ת לא היתה שנאה כלל שמשם גם עכו\"ם מקבלים חיותם. ולזאת כאשר אמר משה למה הרעות היתה זאת התשובה כי וארא אל אברהם כו' ושמי הוי' לא נודעתי להם ועתה אני רוצה שוידעתם כי אני הוי' והייתי לכם לאלקים. פי' שבחי' הוי' לבדו הוא בעצמו יהיה לכם בבחי' אלקים השורה עליכם."],[77,"וכך היתה כוונת יעקב בתפלתו והיה הוי' לי לאלהים. פי' הוי' לבדו הוא בעצמו יהיה לי בבחי' אלקים. וכדי שיהיה גלוי זה גם בבחי' זו צ\"ל תחלה הסתלקות החיות. ושם הוא רם על כל גוים לפיכך במדה ומשקל שהיה צ\"ל גלוי אלקות במ\"ת. כך היה בחי' ההסתלקות וזמן הגלות ושליטת מצרים רד\"ו שנה כו'. ולכן גם בגלות אדום הוא אריכות הגלות בבחי' רצוא כדי שיהי' בחי' שוב לימות המשיח כו'. כי עין בעין כו' ביתר שאת ויתר עז מבמ\"ת שלא ראו עין בעין כ\"א שומעים הנראה וכו'."],[77,"והנה בחי' ראשונה שהוא בחי' יחוד הוי' באלקים בגלוי המשכת המדות נק' בכל לבבכם שהלב הוא מקור המדות ומשכנם. משא\"כ גלוי בחי' הוי' לבדו נק' בכל נפשכם שהוא בחי' התקשרות כל הנפש חב\"ד בחב\"ד ומחשבה דבור כו'. וכמ\"ש ואשים דברי בפיך ודברי אשר שמתי בפיך. וכענין שכינה מדברת מתוך גרונו של משה. ואני המשנה המדברת בפיך וכו' ועי\"ז ודברת בם כו':"],[78,"<b>ויאמר ה' אל משה ואל אהרן לאמר כו' קח את מטך והשלך לפני פרעה יהי לתנין כו' עד ויבלע מטה אהרן את מטתם.<\/b> להבין ענין המטה שנהפך לנחש (ואח\"כ חזר ונהפך למטה. וגם מה שזה היה המופת הראשון שנתנו לפרעה וקדם לכל העשר מכות) הנה כתיב וינצלו את מצרים וארז\"ל (פסחים קיט.) שעשאו' כמצולה שאין בה דגים. פי' שלקטו כל הנצוצין שנפלו בשבירה אליהם ונתרוקנו מצרים מהם עד שנשארו כמצולה כו' ולא השאירו שם אפי' נצוץ א'. והנה להבין ענין הנצוצות שנפלו בשבה\"כ וענין העלאתם. הענין כי הנה ידוע ענין השבירה הוא מיתת ז' מלכין קדמאין דתהו שנשברו ונפלו למטה לבי\"ע בבחי' הקליפות וסט\"א. והיינו כמו על דרך משל בנשמת האדם שקודם בואה לגוף היתה בטילה בתכלית ⟦נז,א⟧לגבי אור א\"ס ב\"ה (כמ\"ש חי ה' אשר עמדתי לפניו) והיינו משום שאז לא היה דבר המחשיך ומסתיר עליה הגילוי אלקות לכך היתה בטילה למקורה בתכלית. וכיון שירדה למטה ונתלבשה בגוף החומרי אזי הגוף מסתיר עליה להיות נדמה העולם ומלואו ליש ודבר נפרד בפ\"ע ואין רואה בחי' הבטול של כל העולמות לגבי אור א\"ס ב\"ה המחיה ומהוה אותם תמיד."],[78,"וכך עד\"מ הוא ענין שבה\"כ שנפלו הנצוצין דתהו ונתלבשו בקליפות דבי\"ע שהקליפות מחשיכות על הנצוצות ומסתירים אותם מכל צד שלא ירגישו גילוי אור א\"ס ב\"ה עד שיוכלו להיות יש ודבר בפ\"ע וכמאמ' פרעה לי יאורי ואני עשיתיני רק דקרו ליה אלהא דאלהיא."],[78,"ואף שקודם השבירה היו הנצוצי' בטלים ומיוחדים בא\"ס ב\"ה מפני שאז היה מתגלה אוא\"ס בהם בגילוי ויחוד גמור אבל לאחר השבירה שירדו הנצוצין ונתלבשו בתוך הקליפות שהם מלבישים אותם ומסתירים הגילוי אלקות כמשל הגוף שמסתיר ומחשיך לגבי הנשמה כנ\"ל. לכך אינם יכולים להיות בבחי' בטול כמו שהיו תחלה."],[78,"ולכך נק' בשם קליפות שהם כמשל הקליפה שהיא חופפת ומקפת על הפרי הכנוס בתוכה ומסתרת אותה כמשל קליפת האגוז. ואין תרופה להוציא הפרי כ\"א ע\"י שבירת הקליפה. וכך כדי להוציא נצוצי הקדושה מהקליפות המסתירים עליהם היה צ\"ל שבירת הקליפות וזה היה ענין אותות ומופתים ומכות שבמצרים כדלקמן אי\"ה:"],[78,"<b>והנה<\/b> כתיב ונהר יוצא מעדן כו' ומשם יפרד והיה לד' ראשים. שם האחד פישון כו'. ופי' נהר היוצא מעדן היא המשכה והארה הנמשכת מח\"ע דאצי' שבה מלובש אור א\"ס ב\"ה. ובה ועל ידה נמשך אור א\"ס ב\"ה בכל האצילות ונמשך עד בחי' מל' דאצי' הנק' גן. וזהו להשקות את הגן. ושם באצי' איהו וגרמוהי חד בהון. ולכן הנהר אחד שהוא עולם האחדות. וכיון שהגיע לראש הבריאה אזי משם יפרד בבחי' פירוד והתחלקות לד' נהרות שהוא תחלת ההתחלקות."],[78,"והנה כמשל הנהרות שאין נהר א' דומה לחבירו לא במהותו שזהו מים מתוקין וצלולין והשני אינו כן. ולא בגודלו שזה נמשך מאתים פרסאות והשני נמשך מאה וכה\"ג. כך אין דומים הנהרות עליונות זה לזה דהיינו פישון נילוס שר של מצרים נמשכו ונפלו בו נצוצים רבים מעולם התהו יותר ממה שנפלו לבבל כו':"],[78,"<b>ועתה<\/b> יובן ענין המופתים שהראה השי\"ת למצרים. וכמ\"ש וידעו מצרים כי אני ה'. פי' וידעו הוא מלשון שבירה כמ\"ש ויודע בם את אנשי סכות. והענין כמבואר למעלה שכדי להוציא הנצוץ מן הקליפה המכסה עליה א\"א להיות כ\"א ע\"י שבירת הקליפה וכמשל האגוז כו'. והענין שע\"י שבירת הקליפה יוכל להיות גילוי אור א\"ס ב\"ה להנצוץ עד שיוכלל באלקותו ית' וזהו ענין סוס ורוכבו רמה. פי' הרוכב הוא הקליפה הרוכב ומכסה על הנצוץ. וזהו ענין מרכבת פרעה כו' וע\"י שבירתם נתגלו הנצוצות ונכללו בא\"ס ב\"ה (ובזה יתורץ מ\"ש בקי\"ס וידעו מצרים כי אני ה'. ולכאורה תמוה שהרי להלן כתיב לא נשאר בהם עד אחד. אלא דפי' וידעו לשון שבירה כו'. ועי\"ז היה גילוי אוא\"ס להנצוצין והם ידעו ידיעה ממש כי אני ה' ועמ\"ש במ\"א על קושיא זו). ועד\"ז היה ענין העשר מכות בכדי לשבר הקליפות להוציא מהם הנצוצין. אבל ישראל עצמן לא היו צריכים למופתים כלל כי הם מאמינים בני מאמינים. וכמ\"ש ויאמן העם וישמעו כי פקד ה' כו' רק בשביל להוציא הנצוצות המובלעים תוך הקליפות ממש הוצרך להיות עשר מכות הנ\"ל שזהו בשביל וידעו מצרים כו':"],[78,"<b>ובזה<\/b> יובן ענין המופת הראשון שהראה הש\"י לפרעה שהוא ענין ⟦נז,ב⟧שנהפך המטה לנחש שזהו הקדמה לכל העשר מכות. כי הנה ענין העשר מכות מבואר שהוא לשבר הקליפות שהם בחי' יש ודבר בפ\"ע כמ\"ש לי יאורי כו' רק דקרו ליה אלהא דאלהיא כנ\"ל."],[78,"וענין המופתים הוא להראות להם איך שעם היותם בחי' קליפות וסט\"א ממש אעפ\"כ הם מקבלים חיות תמיד מקדושה בכל רגע ושבאמת אינם יש ודבר נפרד בפ\"ע כדמיונם הכוזב אלא שהם בטלים בתכלית לגבי אלקותו ית' רק שהחיות נמשך להם ע\"י מסכים והשתלשלות מדרגות רבים ועצומים וגברו כ\"כ הצמצומים וההסתרים עד שיוכלו לומר לי יאורי כו'."],[78,"ולכן בהגלות הארה רבה שלמעלה מן הצמצומים הם בטלים ומבוטלים וזה היה ענין המופתים כו'. וע\"ז היה מורה המופת הראשון בענין המטה שנהפך לנחש. פי' מטה הוא לשון המשכה והטייה. וכן שבט ג\"כ לשון המשכה כמו כוכבא דשביט. דהיינו כל המשכת סדר ההשתלשלות דקדושה מריש כל דרגין עד סוף כל דרגין נק' מטה."],[78,"ותנין היא מקור הקליפות דמצרים כמ\"ש התנים הגדול הרובץ בתוך יאוריו. והראו לו משה ואהרן איך שהמטה נהפך לנחש דהיינו שמבחי' אור והמשכה דקדושה הנק' מטה נמשך החיות והקיום להתנין מקור הקליפות. וכמ\"ש רגליה יורדות כו'. ומלכותו בכל משלה אלא שזהו ע\"י השתלשלות וצמצוצים רבים כנ\"ל עד שיוכל להיות נהפך ממטה לנחש (ועיין בתקוני זהר תקון כ\"ב בענין פי' מטה) שע\"י צמצומים רבים אלו מסתתר השפע מבחי' המטה כ\"כ עד שיוכל להיות התהוות בחינת התנים הגדול הרובץ בתוך יאוריו ואומר לי יאורי כו' כנ\"ל. ואח\"כ הראו לו איך שהנחש נהפך למטה וגם ויבלע מטה אהרן את מטתם. היינו שחזר בחי' התנין להתבטל לגבי הקדושה האלקית כבראשונה (וזהו ענין העלאת הנצוצות הנ\"ל) בזה הראו לפרעה ולמצרים אשר אינם יש ודבר בפ\"ע. כ\"א בכל רגע נמשך להם החיות מאלקות אלא שהוא ית' אל מסתתר (וברצותו נהפך הנחש למטה והיו כלא היו הקליפות) ועד\"ז היו כל המופתים להיות וידעו מצרים כי אני ה' כנ\"ל:"],[79,"<b>לכן אמר לבני ישראל אני ה' והוצאתי אתכם.<\/b> הנה ארז\"ל מזכירין יציאת מצרים בלילות. פי' גם בלילות. ולהבין מה נשתנה נס יצ\"מ מכל הנסים שלא הוזהרנו עליהם להזכירם כל כך. אך הנה בכל דור ודור חייב אדם לראות א\"ע בכל יום בבקר ובערב כאלו הוא עת יצ\"מ. והענין כי הנה נודע שיש זלעו\"ז. ולעומת מצרים דקליפה יש מצרים בקדושה. וכשם שיש מצרים למטה כך יש למעלה ברוחניות. וכן ישראל לתתא וישראל לעילא. וכשם שיש ברוחניות למעלה בעולמות עליונים. כך הוא למטה בנפש האדם בעבודת ה'."],[79,"והנה בחי' כנ\"י דלעילא הוא מ\"ש מה יפית ומה נעמת אהבה בתענוגים. ולמטה בנפש האדם בחי' אהבה בתענוגים היא שמחת הנפש בה' עושה. וכמ\"ש עבדו את ה' בשמחה וכתיב אם הבנים שמחה שהשמחה היא מחמת התבוננות באור א\"ס. וכדכתיב כי אם לבינה תקרא. והיינו ע\"י שיתבונן בגילוי אור א\"ס ב\"ה למטה אזי ישמח ישראל בעשיו ותהיה שמחת הנפש בהתגלות רשפי אש האהבה לצאת מנרתקה היא מאסר הגוף להיות חדות ה' היא מעוזו."],[79,"והנה כתיב תחת אשר לא עבדת כו' מרב כל כו'. דהיינו בחי' כל התענוגים הרוחניים ג\"ע עליון וג\"ע תחתון. והוא מחמת שיתבונן כמ\"ש כי נשגב שמו לבדו הודו על ארץ ושמים. פי' ששמו הוא מדת מלכותו אשר מלך שמו נקרא. וכמאמר ומביא גואל לבני בניהם למען שמו באהבה מלך עוזר וכו'. והוא בחי' שכינה ששוכן בתחתונים וכמ\"ש ושכנתי בתוכם ונק' שמו מלך על כל ⟦נז,ג⟧העולמות. וכמ\"ש מלכותך מלכות כל עולמים. וכמאמר יחיד חי העולמים מלך כו' שע\"י בחי' מלכותו יש לו יחוס ושייכות להעולמות שיקרא שמו מלך עליהם."],[79,"והנה גם בחי' שמו מצד עצמו הוא רם ונשא ונשגב בבחי' לבדו שאין ערוך להעולמות עם שמו ית' כלל. אלא הודו וזיוו של שמו הוא המאיר על הארץ זה ג\"ע תחתון. ושמים זה ג\"ע עליון ששם הצדיקים נהנין מזיו השכינה. אבל בשכינה שהוא בחי' שמו הוא בבחי' לבדו שלא נמשך ממנה להיות הנבראים נהנין ומתענגים בה בעצמה ממש. אבל בבחי' תורה ומצות הנה אומרים אשר קדשנו במצותיו (יש שמברכים בעל ויש שמברכים בלמ\"ד) במצותיו ממש כמארז\"ל הקב\"ה מניח תפילין הקב\"ה מתפלל. וכתיב אני מדבר בצדקה אני ממש. דהיינו הקב\"ה בכבודו ובעצמו. וכדאיתא בזוהר דאורייתא וקוב\"ה כולא חד. קוב\"ה ממש. וקוב\"ה הוא בחי' מה שהוא קדוש ומובדל מגדר עלמין לגמרי שאפי' בבחי' זיו והוד לא היו עולמות יכולים לקבל חיות ממנו. כי הנה כתיב כי ביה ה' צור עולמים שעוה\"ז ועוה\"ב ג\"ע תחתון ועליון נבראו בב' אותיות משמו בלבד."],[79,"ובזוהר איתא דבמחשבה אחת ברא את העולם. והוא ע\"ד מ\"ש היוצר יחד לבם כו' ואמרו רז\"ל כולם נסקרים בסקירה א' שהוא צופה ומביט עד סוף כל הדורות וקורא הדורות מראש כו' וכמ\"ש במ\"א שכל הדורות שהם שית אלפי שני דהוי עלמא וימות המשיח ותחיית המתים כולם הם לפניו במחשבה אחת. עד\"מ כמו שאין ערוך למחשבה אחת נגד כל המחשבות שיכול אדם לחשוב כל ימי חייו ומכ\"ש נגד עצמותו ומהותו שאינה אלא התפשטות הארה א' בעלמא. כך כל הדורות של שית אלפי שנין וימות המשיח ותחיית המתים אינן אלא בחי' זיו והתפשטות הארה א' מבחי' שמו בלבד. אבל הקב\"ה בכבודו ובעצמו הוא רם ונשא למעלה מעלה עד אין קץ ותכלית ולית מחשבה תפיסא ביה כלל שאינו נתפס ונתלבש בגדר עלמין כלל. משא\"כ בתורה ומצות הוא התלבשות אור א\"ס ב\"ה בעצמו ובכבודו ממש."],[79,"וכאשר ישים האדם אל לבו כל הדברים והאמת האלה ישמח לבו ויגל אף גילת ורנן באור א\"ס ב\"ה המתפשט ומתלבש בעסק התורה ומעשה המצות אשר יעשה אותם האדם וממשיך על נפשו אור ה' א\"ס ב\"ה ממש מה שאין כל העולמות כדאי לו:"],[79,"<b>אך<\/b> אין השמחה בהתגלות אור ה' במוח מחשבתו ובינתו לבד כ\"א כאשר נגעה אל נקודת לבו כי שמחה היא ההתגלות. וכמשל המלך שכל כבודו פנימה. אך בשעת השמחה הוא מתגלה. וזהו עבדו את ה' בשמחה דהיינו להיות גילוי אור ה' א\"ס ב\"ה שיהיה בבחי' ונגלה כבוד ה' ולמטה בנפש האדם ההתגלות הוא כשבא לידי גילוי הלב. והיינו דכתיב אם הבנים שמחה דהיינו כשנולדו הבנים שהם המדות ונתגלו בלב. משא\"כ כשהוא בהעלם ובהסתר תוך מוח מחשבתו ובינתו לבד הרי הן בבחי' עבור עדיין ואינה אם הבנים."],[79,"והנה המעכב בחי' הולדה והתגלות אור ה' לצאת מהעלם והסתר שבמוחו אל גילוי הלב הוא בחי' גלות מצרים שהוא בחי' מצר הגרון שהוא האמצעי בין מוחין שבראש ללב ושם הוא בחי' שר המשקים שר האופים ושר הטבחים שהוא בחי' וושט וורידין שהם הם בחי' כל תענוגי עוה\"ז ומחשבותיו ועסקיו ותחבולותיו אשר ישתמש בהם כל אחד לפי ערכו והם הם המונעים ומעכבים ומסכים המבדילין בין אור ה' שבמוח ובין גילוי הלב."],[79,"וזהו צער העבור כעצמות בבטן המליאה. ולכן כל גליות וצרות נק' בשם עבור כמארז\"ל בכל פרשת העבור יהיו צרכיהם לפניך. אפי' בשעה שאתה מתמלא עליהם עברה כאשה עוברה כו'. והגאולה נק' בשם לידה שהוא בחי' התגלות הולד ⟦נז,ד⟧לאויר העולם וחבלי משיח נק' בשם חבלי לידה."],[79,"וכתיב הרינו חלנו מפניך הוי\"ה. פי' שכל בחי' עבור וגליות הוא כדי שיהיה גלוי אור ה' ב\"ה. וצריך לזה חבלי לידה. דהיינו להרגיש הכאב והמרירות על מניעות התפשטות אור ה' בגלוי הלב מחמת המונעים ומעכבים שהם הם צרכי עוה\"ז."],[79,"ואזי כאשר יבא לבחי' לידה והתגלות בבחי' שמחה וישמח ישראל בעושיו יתפרדו כל המונעים ומעכבים והמסכים המבדילין יהיו כאין ואפס בלא תפיסת מקום כלל מחמת שמחת ה'. וכשם שלמעלה בחי' שמחה הם המתקת הדינין. כך למטה בנפש האדם היא מבטלת כל המונעים ומעכבים מבית ומבחוץ ונק' בשם ארץ כנען ע\"ש שמכנעת החיצונים שהם נדחים מפני ה' מאליהם וממילא כחשך שנדחה מפני אור. וכמשל האשה אשר חבלי לידה בא לה."],[79,"והנה בעת לידתה יוצאים ממנה כל המכאובות בדם לידתה שזב ממנה. כך הנה כתיב ואראך מתבוססת בדמיך כו' שכל המונעים והמעכבים נמסו והיו לדם דבר שאין בו ממש ואין בו תפיסת מקום כלל. וכמ\"ש ותשליך במצולות ים כל חטאתם כו'."],[79,"והנה כשם שגלות מצרים הוא בחי' מצר הגרון שהוא המבדיל ומפסיק בין המוח ללב כנ\"ל. כך ענין הגאולה ויצ\"מ הוא בחי' יציאתם ממצר הגרון ע\"י הקול קול יעקב. שהקול שהוא בגרון הוא הוא המקשר ומחבר בחינת מוחין שבראש לבא לידי גילוי הלב."],[79,"והיינו ע\"י קול קורא בתורה שע\"י קריאתו בתורה הוא קורא וממשיך אור ה' לצאת מההעלם שבמוח אל גילוי הלב. וזהו שארז\"ל כל הקורא בתורה הקב\"ה קורא כנגדו ונק' כנגדו מפני שבחי' קריאתו בתורה הוא בחי' ממכ\"ע והקב\"ה כנגדו הוא בחי' סוכ\"ע."],[79,"וזהו לשון קורא בתורה שקורא האור לחוץ. והיינו ע\"י תושב\"כ בחי' הוי\"ה דאורייתא וקוב\"ה כולא חד. וזהו לכן אמר לבני ישראל אני הוי\"ה והוצאתי אתכם מתחת סבלות מצרים וגו' שע\"י בחי' וגילוי הוי\"ה דהיינו ע\"י בחינת תורה שבכתב בחינת הקול קול יעקב עי\"ז יהיה בחינת יציאת מצרים וכל המונעים ומסכים המבדילים יבטלו ולא יהיה עוד סבלות מצרים ועבודתם:"],[79,"<b>אך<\/b> לא זו בלבד הוא תכלית המכוון כ\"א והבאתי אתכם אל הארץ וגו'. וביאור הענין כי הנה כתיב אל ארץ טובה ורחבה וגו'. וא\"י זו היא בחינת תושבע\"פ ונקרא ארץ רחבה ע\"ד מארז\"ל ע\"פ ארץ צבי צבאות גוים. מה צבי אין עורו מחזיק בשרו כו'."],[79,"והענין כי תורה שבכתב עיקר יסודתה הוא בחי' אותיות התורה. ולכן מדקדקין באותיותיה שלא יהי' חסר או יתיר ושיהיו צורתן עליהן כדמותן בצלמן ושיהיו גולם אחד. שאם נפסק היו\"ד שעל גג האל\"ף עד\"מ מעל גוף האות הרי זו ס\"ת פסולה."],[79,"ואין מברכין עליה. אבל אין נראה בה גילוי ההשכלה כמו בתורה שבע\"פ שעיקר גילוי השכלת הדינין והמשפטים שבתורה אינו מפורש בתורה איך ומה לעשות שכל התורה היא ספורי מעשיות. וגם הדינין שבה הן דרך ספורי דברים שכך אמר ה' שידבר אל בני ישראל ושכך אמר משה."],[79,"ואין כוונתה לידע ממנה לבדה כל הדינין על בוריין ומתכונתן כגון עד\"מ ענין התפלין אינו מפורש שיהיו ד' פרשיות ושיהי' כתוב כך וכך ושיהיו נכתבים על קלף דוקא ככל משפטי תפילין והלכותי' המסורות לנו בתורה שבע\"פ וכן שאר כל המצות."],[79,"והיינו לפי שעיקר יסודתה בהררי קדש בחי' חכמה עלאה דאורייתא מחמה נפקת. ותורה שבכתב היא בחי' ח\"ע. ותורה שבע\"פ היא חכמה תתאה ולחכימא ברמיזא. פי' שאינה רק כמשל הרב המרמז אל התלמיד באיזה רמז כל שהוא בכדי שהתלמיד יבין מעצמו איך ללמוד אבל לא זהו עיקר הלימוד עצמו. כך הנה כל אותיות התורה שבכתב הם רק רמזים והמשכות מחכמה עלאה בדרך רמז."],[79,"וכל ההמשכות נרמזים באותיות אלו דוקא שיהי' ⟦נח,א⟧הקרי כך והכתיב כך ולכן כל אותיותיה ספורים ומנויים בל יעדוף ובל יחסור. וכל אות ואות צ\"ל בדמותו וצלמו מפני שרומזים להמשכה עליונה מח\"ע אבל עצמות ההשכלה אינו מתלבש באותיות תורה שבכתב. משא\"כ בתורה שבע\"פ הן עצמות ההשכלה מלובשת באותיות ההלכה ולכן אין מדקדקין באותיותיה כ\"כ רק ההשכלה היא עיקרית המתגלה תוך האותיות גם לפי רבוי ההשכלה כך ירבו אותיותיה."],[79,"ולכן מה שמשכילים בה יותר כגון פרש\"י ותוספות ופוסקים הכל בכלל תושבע\"פ יחשב ואפי' כל מה שתלמיד ותיק עתיד לחדש. ולכן נק' ארץ טובה ורחבה שמתרחבת והולכת עד אין קץ. וזהו מה צבי אין עורו מחזיק בשרו כו'. והיינו לפי שהבשר והעור גדול כ\"כ שגידול העור הוא מחמת הבשר שבתוכו. כך הנה בחי' תושבע\"פ ג\"כ גדולים עצם ההשכלה והאותיות כאחד שהאותיות מתפשטים מצד עצם ההשכלה. משא\"כ בתושב\"כ אין האותיות מתפשטים מצד עצם ההשכלה כ\"א הארה בעלמא דרך רמז כנ\"ל:"],[79,"<b>ובזה<\/b> יובן מה שהתורה שבכתב נק' בשם מקרא בלשון הגמרא וקורא בתורה שע\"י שהוא רק כמו קורא וממשיך אור א\"ס ב\"ה על נפשו מההעלם שבמוח אל גילוי הלב כנ\"ל. אך עדיין הוא כאלו הוא דבר בפ\"ע כאדם הקורא לזולתו. אבל בתורה שבע\"פ אמרו מתניתין מלכתא כו' כמלך שמצוה כמ\"ש במ\"א מפני שנעשה יחוד גמור חב\"ד בחב\"ד כו'."],[79,"וכמ\"ש ואשים דברי בפיך דברי ממש. וכמ\"ש המגיד להב\"י אני המשנה המדברת בפיך. שנעשה עצמות אחד בבחי' בטול ממש וזו היא בחי' דירה בתחתונים ממש. והגם שמצד התפשטות עצם גילוי ההשכלה לאור ה' בתושבע\"פ הנה לירידה גדולה נחשבת אצלה להתפשט ולהתלבש בעשיה גשמית סדר זרעים כו'. הנה ע\"ז אמר הכתוב אשר נשאתי את ידי."],[79,"והוא עד\"מ שהיד יכול להרים הדבר הנופל ארצה ולשום למעלה על ראשו כך הנה סוף מעשה במחשבה תחלה. ואשת חיל עטרת בעלה ונעוץ סופן בתחלתן שנק' ארץ חפץ פי' כלי להשראת רצונו ית' כי גילוי רצון עליון הוא בסוף מעשה דוקא."],[79,"וכן בתורה שבע\"פ הוא התגלות רצון העליון יותר מבתושב\"כ שאין לידע ממנה לבדה מהות רצון עליון בכל הדינים והמשפטים כ\"א ע\"י תורה שבע\"פ דוקא. וזהו ונתתי צבי בארץ החיים. פי' שכל צביונו וחפצו הוא בארץ החיים בחינת תושבע\"פ ששם הוא גילוי אור ה' ורצונו ביתר שאת מבחי' תורה שבכתב והרצון הוא מקור החיים. וזהו אשר נשאתי את ידי לתת אתה לאברהם ליצחק וליעקב כו' שהם המדות חג\"ת כי אשת חיל עטרת בעלה כו' כנ\"ל. ונתתי אתה לכם מורשה אני הוי\"ה להיות בבחי' ואשים דברי בפיך כו' כנ\"ל:"],[79,"<b>אך<\/b> כל גילוי אור ה' בבחי' המשכות אלו הכל תלוי בלבו של אדם כמו לכל אשר יחפוץ הלב יטנו. לזאת צריך לעורר תחלה האהבה מקודם לעורר האהבה בלבו בתפלה כדי שיהי' לבו חפץ באמת לגילוי אור ה'."],[79,"ולכן אמרו מזכירין יצ\"מ בבקר ובערב. והיינו פרשת ציצית שכתוב שם להיות לכם לאלקים אני ה' אלקיכם. והענין כי לא די בהתעוררות הלב בתפלת השחר לבד אלא ליומו מכיון שאח\"כ פונה לעסקיו."],[79,"ואפי' מי שאינו בעל עסק הנה בלימודו בבחי' עשיה סדר זרעים כו' נמשך הלב אחר גשמיות הדברים בבחי' הסתר וצמצום בחי' אלקים. וצריך לעורר עוד את האהבה ושמחה מנקודת הלב להיות גילוי בחי' הוי\"ה כנ\"ל. אך לא די בהתגלות האהבה בזה לבד כ\"א ע\"י תושב\"כ הקל קול יעקב כנ\"ל להיות קורא וממשיך בתורה גילוי אור ה' ממש ואחר כך בתורה שבע\"פ בחי' בטול ממש ולהיות בחי' ואשים דברי בפיך כנ\"ל ודירה ⟦נח,ב⟧בתחתונים ממש כנ\"ל להיות בחי' הוי\"ה אלקיכם כו' וד\"ל:"]]);
